INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cb198d6-9540-49cd-9762-1731f35d58f0', '贈嚴四草屨', '贈嚴四草屨', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["輕微菅蒯將何用，容足偷安事頗同。","日入信陵賓館靜，贈君閑步月明中。"]', '["轻微菅蒯將何用，容足偷安事頗同。","日入信陵賓館静，贈君闲步月明中。"]', '诗', 'shi', '', NULL, '贈嚴四草屨 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0efece9a-8bfe-4b25-a872-1dcd7ccbd49e', '題劉偃莊', '題劉偃莊', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["何事退耕滄海畔，閑看富貴白雲飛。","門前種稻三回熟，縣裏官人四考歸。"]', '["何事退耕滄海畔，闲看富貴白云飞。","门前種稻三回熟，縣裏官人四考归。"]', '诗', 'shi', '', NULL, '題劉偃莊 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae9eab98-ccff-4285-97a1-4d91ca67fd8a', '題黃陂夫人祠', '題黄陂夫人祠', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["蒼山雲雨逐明神，唯有香名萬歲春。","東風三月黃陂水，只見桃花不見人。"]', '["蒼山云雨逐明神，唯有香名万歲春。","东风三月黄陂水，只见桃花不见人。"]', '诗', 'shi', '', NULL, '題黃陂夫人祠 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d110d8e-e1d9-4b4e-81ee-46d2993148a0', '題道濟上人房', '題道濟上人房', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["何處營求出世間，心中無事即身閑。","門外水流風葉落，唯將定性對前山。"]', '["何处營求出世间，心中無事即身闲。","门外水流风葉落，唯將定性对前山。"]', '诗', 'shi', '', NULL, '題道濟上人房 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8b88762-5c84-4462-a912-aba1899853e2', '棃樹陰', '棃樹陰', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["福庭人靜少攀援，雨露偏滋影易繁。","磊落紫香香亞樹，清陰滿地晝當軒。"]', '["福庭人静少攀援，雨露偏滋影易繁。","磊落紫香香亞樹，清陰满地晝當軒。"]', '诗', 'shi', '', NULL, '棃樹陰 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6a372a3-e248-4d31-a452-5dcbe7370636', '秋蟬聲', '秋蟬声', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["蕭條旅舍客心驚，斷續僧房靜又清。","借問蟬聲何所爲，人家古寺兩般聲。"]', '["蕭條旅舍客心驚，斷續僧房静又清。","借问蟬声何所爲，人家古寺兩般声。"]', '诗', 'shi', '', NULL, '秋蟬聲 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6547d07-69dc-469d-8d28-ec60b009af96', '歸山留別子姪二首 一', '归山留別子姪二首 一', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["車馬驅馳人在世，東西南北鶴隨雲。","莫言貧病無留別，百代簪纓將付君。"]', '["车马驱驰人在世，东西南北鹤隨云。","莫言貧病無留別，百代簪纓將付君。"]', '诗', 'shi', '', NULL, '歸山留別子姪二首 一 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1410e9c4-3ffc-4895-b5c4-c58fd4fdc88c', '歸山留別子姪二首 二', '归山留別子姪二首 二', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["不逐浮雲不羨魚，杏花茅屋向陽居。","鶴鳴華表應傳語，鴈度霜天懶寄書。"]', '["不逐浮云不羨鱼，杏花茅屋向陽居。","鹤鳴华表應傳語，鴈度霜天懶寄书。"]', '诗', 'shi', '', NULL, '歸山留別子姪二首 二 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c72b4fa-7c83-481f-9096-ad0fc6aa8235', '與湛上人院畫松', '與湛上人院畫松', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["水墨乍成巖下樹，摧殘半隱洞中[雲]。","猷公曾住天台寺，陰雨猨聲何處聞。"]', '["水墨乍成巖下樹，摧殘半隐洞中[云]。","猷公曾住天台寺，陰雨猨声何处闻。"]', '诗', 'shi', '', NULL, '與湛上人院畫松 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e86ab12-f4fd-4c3d-abbf-617af182cf1f', '白沙宿竇常宅觀妓', '白沙宿竇常宅观妓', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["楊子澄江映晚霞，柳條垂岸一千家。","主人留客江邊宿，十月繁霜見杏花。"]', '["楊子澄江映晚霞，柳條垂岸一千家。","主人留客江邊宿，十月繁霜见杏花。"]', '诗', 'shi', '', NULL, '白沙宿竇常宅觀妓 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('915e667e-09aa-43dd-bd83-3db7715c0d75', '上巳日兩縣寮友會集時主郵不遂馳赴輒題以寄方寸', '上巳日兩縣寮友會集时主郵不遂驰赴輒題以寄方寸', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["踏青看竹共佳期，春水晴山祓禊詞。","獨坐郵亭心欲醉，櫻桃落盡暮愁時。"]', '["踏青看竹共佳期，春水晴山祓禊词。","独坐郵亭心欲醉，櫻桃落尽暮愁时。"]', '诗', 'shi', '', NULL, '上巳日兩縣寮友會集時主郵不遂馳赴輒題以寄方寸 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7bfc7f7-1890-4597-8d4f-cd15dda7e301', '懷張璪', '懷張璪', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["苔石蒼蒼臨澗水，陰風褭褭動松枝。","世間唯有張通會，流向衡陽那得知。"]', '["苔石蒼蒼臨澗水，陰风褭褭动松枝。","世间唯有張通會，流向衡陽那得知。"]', '诗', 'shi', '', NULL, '懷張璪 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a6fff6a-6621-4194-a596-4e0d19f33788', '與于中丞', '與于中丞', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["萬頃荒臨不敢看，買山容足擬求安。","田園失計全蕪沒，何處春風種蕙蘭。"]', '["万頃荒臨不敢看，買山容足擬求安。","田园失計全蕪沒，何处春风種蕙蘭。"]', '诗', 'shi', '', NULL, '與于中丞 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5081bebf-3c51-40c4-a615-d41487a273ca', '袁十五遠訪山門', '袁十五远訪山门', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["僻居謀道不謀身，避病桃源不避秦。","遠入青山何所見，寒花滿徑白頭人。"]', '["僻居謀道不謀身，避病桃源不避秦。","远入青山何所见，寒花满徑白头人。"]', '诗', 'shi', '', NULL, '袁十五遠訪山門 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cdd5eb8-5768-4964-919c-f6d50f4aeda3', '行營病中', '行營病中', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["心許征南破虜歸，可言羸病臥戎衣。","遲遲不見憐弓箭，惆悵秋鴻敢近飛。"]', '["心許征南破虜归，可言羸病臥戎衣。","遲遲不见怜弓箭，惆悵秋鴻敢近飞。"]', '诗', 'shi', '', NULL, '行營病中 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f08289a-2852-4411-87cb-6aae32733852', '合谿水漲寄敬山人', '合谿水漲寄敬山人', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["共愛碧谿臨水住，相思來往踐莓苔。","而今却欲嫌谿水，雨漲春流隔往來。"]', '["共愛碧谿臨水住，相思来往踐莓苔。","而今却欲嫌谿水，雨漲春流隔往来。"]', '诗', 'shi', '', NULL, '合谿水漲寄敬山人 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b55eaf9f-f4da-427c-8c6a-3a4061e6fba5', '不羨花', '不羨花', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["惆悵朝陽午又斜，剩栽桃李學仙家。","花開花落人如舊，誰道容顏不及花。"]', '["惆悵朝陽午又斜，剩栽桃李学仙家。","花开花落人如旧，誰道容顏不及花。"]', '诗', 'shi', '', NULL, '不羨花 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('732e0045-a7cc-49f4-a55d-1f247560c770', '醉後', '醉後', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["春草秋風老此身，一瓢長醉任家貧。","醒來還愛浮萍草，漂寄官河不屬人。"]', '["春草秋风老此身，一瓢长醉任家貧。","醒来還愛浮萍草，漂寄官河不屬人。"]', '诗', 'shi', '', NULL, '醉後 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebcb34d5-39e8-4cc1-9ec0-2adb8b0c7106', '題水洞二首 一', '題水洞二首 一', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["桃花流出武陵洞，夢想仙家雲樹春。","今看水入洞中去，却是桃花源裏人。"]', '["桃花流出武陵洞，梦想仙家云樹春。","今看水入洞中去，却是桃花源裏人。"]', '诗', 'shi', '', NULL, '題水洞二首 一 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2d9200a-2ba4-4232-8ebc-3c07e377b060', '題水洞二首 二', '題水洞二首 二', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["長看巖穴泉流出，忽聽懸泉入洞聲。","莫摘山花拋水上，花浮出洞世人驚。"]', '["长看巖穴泉流出，忽听懸泉入洞声。","莫摘山花拋水上，花浮出洞世人驚。"]', '诗', 'shi', '', NULL, '題水洞二首 二 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c7c5f83-8f11-4174-ac35-fb3acdf4ba7a', '代人村中悼亡二首 一', '代人村中悼亡二首 一', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["花落茅簷轉寂寥，魂隨暮雨此中銷。","邇來庭柳無人折，長得垂枝一萬條。"]', '["花落茅簷轉寂寥，魂隨暮雨此中銷。","邇来庭柳無人折，长得垂枝一万條。"]', '诗', 'shi', '', NULL, '代人村中悼亡二首 一 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c11e69f-a174-486b-967e-4b8c1717b997', '代人村中悼亡二首 二', '代人村中悼亡二首 二', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["虛室無人乳燕飛，蒼苔滿地履痕稀。","庭前唯有薔薇在，花似殘妝葉似衣。"]', '["虛室無人乳燕飞，蒼苔满地履痕稀。","庭前唯有薔薇在，花似殘妝葉似衣。"]', '诗', 'shi', '', NULL, '代人村中悼亡二首 二 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7070a110-e4f7-4db0-a389-aaa8303665a6', '觀獵三首 一', '观獵三首 一', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["夢非熊虎數年間，驅盡豺狼宇宙閑。","傳道單于聞校獵，相期不敢過陰山。"]', '["梦非熊虎數年间，驱尽豺狼宇宙闲。","傳道單于闻校獵，相期不敢過陰山。"]', '诗', 'shi', '', NULL, '觀獵三首 一 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61b6f683-2b9e-41c0-88cb-46df7a1cc9af', '觀獵三首 二', '观獵三首 二', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["日隱寒山獵未歸，鳴絃落羽雪霏霏。","梁園射盡南飛鴈，淮楚人驚陽鳥啼。"]', '["日隐寒山獵未归，鳴絃落羽雪霏霏。","梁园射尽南飞鴈，淮楚人驚陽鸟啼。"]', '诗', 'shi', '', NULL, '觀獵三首 二 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dece4ca9-85a1-49fb-aa4a-85d004bb7574', '觀獵三首 三', '观獵三首 三', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["松月東軒許獨遊，深恩未報復淹留。","梁園日暮從公獵，每過青山不舉頭。"]', '["松月东軒許独游，深恩未報复淹留。","梁园日暮從公獵，每過青山不舉头。"]', '诗', 'shi', '', NULL, '觀獵三首 三 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd933711-1b4d-4fec-aa26-c87d4484c886', '畫石', '畫石', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["蒼蘚千年粉繪傳，堅貞一片色猶全。","那知忽遇非常用，不把分銖補上天。"]', '["蒼蘚千年粉繪傳，堅貞一片色猶全。","那知忽遇非常用，不把分銖補上天。"]', '诗', 'shi', '', NULL, '畫石 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2782132-3d54-4bf4-8d68-d2b9c2803bda', '詠雙開蓮花', '詠雙开蓮花', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["菡萏新花曉竝開，濃妝美笑面相隈。","西方采畫迦陵鳥，早晚雙飛池上來。"]', '["菡萏新花晓竝开，濃妝美笑面相隈。","西方采畫迦陵鸟，早晚雙飞池上来。"]', '诗', 'shi', '', NULL, '詠雙開蓮花 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('265957da-73d9-4c7c-be73-7768cbfb58a3', '夜聞鄰管', '夜闻鄰管', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["何事霜天月滿空，鸝雛百囀向春風。","鄰家思婦更長短，楊柳如絲在管中。"]', '["何事霜天月满空，鸝雛百囀向春风。","鄰家思婦更长短，楊柳如絲在管中。"]', '诗', 'shi', '', NULL, '夜聞鄰管 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73a6d10e-ee40-4b4c-9b2a-284b12b70e71', '山中寄元二侍御二首 一', '山中寄元二侍御二首 一', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["心期汗漫臥雲扃，家計漂零水上萍。","桃李向秋彫落盡，一枝松色獨青青。"]', '["心期汗漫臥云扃，家計漂零水上萍。","桃李向秋彫落尽，一枝松色独青青。"]', '诗', 'shi', '', NULL, '山中寄元二侍御二首 一 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61e43314-6f9b-4881-ab52-ecd073db4d74', '山中寄元二侍御二首 二', '山中寄元二侍御二首 二', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["拖紫鏘金濟世才，知君倚玉望三台。","深山窮谷無人到，唯有狂愚獨自來。"]', '["拖紫鏘金濟世才，知君倚玉望三台。","深山窮谷無人到，唯有狂愚独自来。"]', '诗', 'shi', '', NULL, '山中寄元二侍御二首 二 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02073a29-4c9c-4d60-b2fa-c92796cb24f2', '上崔十五老丈', '上崔十五老丈', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["天漢乘槎可問津，寂寥深景到無因。","看花獨往尋詩客，不爲經時謁丈人。"]', '["天漢乘槎可问津，寂寥深景到無因。","看花独往尋诗客，不爲經时謁丈人。"]', '诗', 'shi', '', NULL, '上崔十五老丈 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60a2019f-2e72-472b-8b8f-03150f7b986a', '袁德師求畫松', '袁德師求畫松', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["柏偃松𢼮勢自分，森梢古意出浮雲。","如今眼暗畫不得，舊有三株持贈君。"]', '["柏偃松𢼮勢自分，森梢古意出浮云。","如今眼暗畫不得，旧有三株持贈君。"]', '诗', 'shi', '', NULL, '袁德師求畫松 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bb54aba-3845-4717-9dec-1ed03b254f79', '早夏月夜問王開', '早夏月夜问王开', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["清風首夏夜猶寒，嫩笋侵階竹數竿。","君向蘇臺長見月，不知何事此中看。"]', '["清风首夏夜猶寒，嫩笋侵階竹數竿。","君向蘇台长见月，不知何事此中看。"]', '诗', 'shi', '', NULL, '早夏月夜問王開 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc075307-65e8-4814-90fa-3bf93d48608f', '裴十六廳即事', '裴十六廳即事', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["主人能政訟庭閑，帆影雲峰戶牖間。","每到夕陽嵐翠近，只言籬障倚前山。"]', '["主人能政訟庭闲，帆影云峰戶牖间。","每到夕陽嵐翠近，只言籬障倚前山。"]', '诗', 'shi', '', NULL, '裴十六廳即事 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d82bf4d8-ee33-41ad-a008-d4dbfcabd803', '春日行營即事', '春日行營即事', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["風引雙旌馬首齊，曹南戰勝日平西。","爲儒不解從戎事，花落春深聞鼓鼙。"]', '["风引雙旌马首齊，曹南戰勝日平西。","爲儒不解從戎事，花落春深闻鼓鼙。"]', '诗', 'shi', '', NULL, '春日行營即事 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2ac2ab6-d983-4f81-a059-b6fdea86d9aa', '畫樹後呈濬師', '畫樹後呈濬師', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["翔鳳邊風十月寒，蒼山古木更摧殘。","爲君壁上畫松柏，勁雪嚴霜君試看。"]', '["翔鳳邊风十月寒，蒼山古木更摧殘。","爲君壁上畫松柏，勁雪嚴霜君試看。"]', '诗', 'shi', '', NULL, '畫樹後呈濬師 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de848ea1-22cb-4dd5-94e3-9000a8cd754e', '弔從甥', '弔從甥', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["日晚河邊訪惸獨，衰柳寒蕪遶茅屋。","兒童驚走報人來，孀婦開門一聲哭。"]', '["日晚河邊訪惸独，衰柳寒蕪遶茅屋。","兒童驚走報人来，孀婦开门一声哭。"]', '诗', 'shi', '', NULL, '弔從甥 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c50e5462-3ccc-4aa7-b24b-d8f96f823aa2', '句', '句', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["郵筒不解獻茱萸。","趙侯首帶鹿耳巾，規模出自陶弘景。"]', '["郵筒不解獻茱萸。","趙侯首带鹿耳巾，規模出自陶弘景。"]', '诗', 'shi', '', NULL, '句 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c58d0fc5-6167-4f0b-b55c-7fd132aeec8e', '登城樓作', '登城楼作', 'c1f937bc-3866-4332-9446-a606ccd51ab3', '唐', '["井邑白雲間，嚴城遠帶山。","沙墟陰欲暮，郊色淡方閑。","孤徑迴榕岸，層巒破枳關。","寥寥分遠望，暫得一開顏。"]', '["井邑白云间，嚴城远带山。","沙墟陰欲暮，郊色淡方闲。","孤徑迴榕岸，層巒破枳关。","寥寥分远望，暫得一开顏。"]', '诗', 'shi', '', NULL, '登城樓作 陳翊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a94630e9-8d05-4f23-b942-1844901f030d', '宴柏臺', '宴柏台', 'c1f937bc-3866-4332-9446-a606ccd51ab3', '唐', '["華臺陳桂席，密榭宴清真。","柏葉猶霜氣，桃花似漢津。","青尊照深夕，綠綺映芳春。","欲憶相逢後，無言嶺海人。"]', '["华台陳桂席，密榭宴清真。","柏葉猶霜氣，桃花似漢津。","青尊照深夕，綠綺映芳春。","欲憶相逢後，無言嶺海人。"]', '诗', 'shi', '', NULL, '宴柏臺 陳翊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('301cc127-a514-4c46-af4f-5ccecaa32d2a', '過馬侍中亭', '過马侍中亭', 'c1f937bc-3866-4332-9446-a606ccd51ab3', '唐', '["草色照雙扉，軒車到客稀。","苔衣香屐迹，花綬少塵飛。","薄望憐池淨，開畦愛雨肥。","相過忘日昃，坐待白雲歸。"]', '["草色照雙扉，軒车到客稀。","苔衣香屐迹，花綬少塵飞。","薄望怜池淨，开畦愛雨肥。","相過忘日昃，坐待白云归。"]', '诗', 'shi', '', NULL, '過馬侍中亭 陳翊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e3b3e00-9cd5-410e-af4f-7465e0d0d273', '寄邵校書楚萇', '寄邵校书楚萇', 'c1f937bc-3866-4332-9446-a606ccd51ab3', '唐', '["愛酒時稱僻，高情自不凡。","向人方白眼，違俗有青巖。","雲際開三徑，煙中挂一帆。","相期同歲晚，閑興與松杉。"]', '["愛酒时稱僻，高情自不凡。","向人方白眼，違俗有青巖。","云際开三徑，煙中挂一帆。","相期同歲晚，闲兴與松杉。"]', '诗', 'shi', '', NULL, '寄邵校書楚萇 陳翊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7206fb5e-9794-4926-a77c-d49a48b66235', '龍池春草', '龙池春草', 'c1f937bc-3866-4332-9446-a606ccd51ab3', '唐', '["青春光鳳苑，細草徧龍池。","曲渚交蘋葉，迴塘惹柳枝。","因風初苒苒，覆岸欲離離。","色帶金堤靜，陰連玉樹移。","日光浮靃靡，波影動參差。","豈比生幽遠，芳馨衆不知。"]', '["青春光鳳苑，細草徧龙池。","曲渚交蘋葉，迴塘惹柳枝。","因风初苒苒，覆岸欲離離。","色带金堤静，陰連玉樹移。","日光浮靃靡，波影动參差。","豈比生幽远，芳馨衆不知。"]', '诗', 'shi', '', NULL, '龍池春草 陳翊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b986600-ebf4-4bfe-b2c9-0d625e290cd5', '郊行示友人', '郊行示友人', 'c1f937bc-3866-4332-9446-a606ccd51ab3', '唐', '["水開長鏡引諸巒，春洞花深落翠寒。","醉向絲蘿驚自醒，與君清耳聽松湍。"]', '["水开长镜引諸巒，春洞花深落翠寒。","醉向絲蘿驚自醒，與君清耳听松湍。"]', '诗', 'shi', '', NULL, '郊行示友人 陳翊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2759a051-c5c9-4b72-bcf6-fcbefe90ad40', '送別蕭二', '送別蕭二', 'c1f937bc-3866-4332-9446-a606ccd51ab3', '唐', '["橘花香覆白蘋洲，江引輕帆入遠遊。","千里雲天風雨夕，憶君不敢再登樓。"]', '["橘花香覆白蘋洲，江引轻帆入远游。","千里云天风雨夕，憶君不敢再登楼。"]', '诗', 'shi', '', NULL, '送別蕭二 陳翊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('201ebc09-9beb-4a5d-a962-92dc6afff5d4', '遊仙', '游仙', 'f339464b-cb90-4bc6-997f-c6e558ebe96b', '唐', '["稅駕倚扶桑，逍遙望九州。","二老佐軒轅，移戈戮蚩尤。","功成棄之去，乘龍上天遊。","天上見玉皇，壽與天地休。","俯視崑崙宮，五城十二樓。","王母何窈眇，玉質清且柔。","揚袂折瓊枝，寄我天東頭。","相思千萬歲，大運浩悠悠。","安用知吾道，日月不能周。","寄音青鳥翼，謝爾碧海流。"]', '["稅駕倚扶桑，逍遙望九州。","二老佐軒轅，移戈戮蚩尤。","功成棄之去，乘龙上天游。","天上见玉皇，壽與天地休。","俯視崑崙宮，五城十二楼。","王母何窈眇，玉質清且柔。","揚袂折瓊枝，寄我天东头。","相思千万歲，大運浩悠悠。","安用知吾道，日月不能周。","寄音青鸟翼，謝爾碧海流。"]', '诗', 'shi', '', NULL, '遊仙 劉復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45f5c07c-6fd7-4884-9107-e86be9cefe2d', '寺居清晨', '寺居清晨', 'f339464b-cb90-4bc6-997f-c6e558ebe96b', '唐', '["高枕對曉月，衣巾清且涼。","露華朝未晞，滴瀝含虛光。","隔竹聞汲井，開扉見焚香。","幽心感衰病，結念依法王。","青冥早雲飛，杳靄空鳥翔。","此情皆有釋，悠然知所忘。"]', '["高枕对晓月，衣巾清且涼。","露华朝未晞，滴瀝含虛光。","隔竹闻汲井，开扉见焚香。","幽心感衰病，結念依法王。","青冥早云飞，杳靄空鸟翔。","此情皆有釋，悠然知所忘。"]', '诗', 'shi', '', NULL, '寺居清晨 劉復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db1c8f32-7a4a-432e-9e8c-c16945988fca', '出東城', '出东城', 'f339464b-cb90-4bc6-997f-c6e558ebe96b', '唐', '["步出東城門，獨行已徬徨。","伊洛汎清流，密林含朝陽。","芳景雖可矚，憂懷在中腸。","人生幾何時，苒苒隨流光。","願得心所親，尊酒坐高堂。","一爲浮沈隔，會合殊未央。","雙戲水中鳧，和鳴自翱翔。","我無此羽翼，安可以比方。"]', '["步出东城门，独行已徬徨。","伊洛汎清流，密林含朝陽。","芳景雖可矚，憂懷在中腸。","人生幾何时，苒苒隨流光。","願得心所親，尊酒坐高堂。","一爲浮沈隔，會合殊未央。","雙戲水中鳧，和鳴自翱翔。","我無此羽翼，安可以比方。"]', '诗', 'shi', '', NULL, '出東城 劉復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f8eb0b3-d997-49f6-90bf-74a3400e9a73', '經禁城', '經禁城', 'f339464b-cb90-4bc6-997f-c6e558ebe96b', '唐', '["日沒路且長，遊子欲涕零。","荒城無人路，秋草飛寒螢。","東南古丘墟，莽蒼馳郊坰。","黃雲晦斷岸，枯井臨崩亭。","昔人竟何之，窮泉獨冥冥。","蒼苔沒碑版，朽骨無精靈。","俛仰寄世間，忽如流波萍。","金石非汝壽，浮生等臊腥。","不如學神仙，服食求丹經。"]', '["日沒路且长，游子欲涕零。","荒城無人路，秋草飞寒螢。","东南古丘墟，莽蒼驰郊坰。","黄云晦斷岸，枯井臨崩亭。","昔人竟何之，窮泉独冥冥。","蒼苔沒碑版，朽骨無精靈。","俛仰寄世间，忽如流波萍。","金石非汝壽，浮生等臊腥。","不如学神仙，服食求丹經。"]', '诗', 'shi', '', NULL, '經禁城 劉復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('054b8e52-9a8f-49b2-8341-801a5bff34be', '出三城留別幕中三判官', '出三城留別幕中三判官', 'f339464b-cb90-4bc6-997f-c6e558ebe96b', '唐', '["翔禽託高柯，倦客念主人。","恩義有所知，四海同一身。","況皆曠大姿，翰音見良辰。","陳規佐武略，高視據要津。","常願投素誠，今果得所申。","金罍列四座，廣廈無氛塵。","留連徂暑中，觀望歷數旬。","河山險以固，士卒勇且仁。","飭裝去未歸，相追越城闉。","愧無青玉案，緘佩永不泯。"]', '["翔禽託高柯，倦客念主人。","恩義有所知，四海同一身。","況皆曠大姿，翰音见良辰。","陳規佐武略，高視據要津。","常願投素誠，今果得所申。","金罍列四座，廣廈無氛塵。","留連徂暑中，观望歷數旬。","河山險以固，士卒勇且仁。","飭裝去未归，相追越城闉。","愧無青玉案，緘佩永不泯。"]', '诗', 'shi', '', NULL, '出三城留別幕中三判官 劉復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f000ab0-251b-480a-abfe-28d565c08797', '送劉秀才南歸', '送劉秀才南归', 'f339464b-cb90-4bc6-997f-c6e558ebe96b', '唐', '["鳥啼楊柳垂，此別千萬里。","古路入商山，春風生灞水。","停車落日在，罷酒離人起。","蓬戶寄龍沙，送歸情詎已。"]', '["鸟啼楊柳垂，此別千万里。","古路入商山，春风生灞水。","停车落日在，罷酒離人起。","蓬戶寄龙沙，送归情詎已。"]', '诗', 'shi', '', NULL, '送劉秀才南歸 劉復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe915623-7e9c-4ad3-8f87-8947fa3d6934', '送王倫', '送王倫', 'f339464b-cb90-4bc6-997f-c6e558ebe96b', '唐', '["春江日未曛，楚客酣送君。","翩翩孤黃鶴，萬里滄洲雲。","四方各有志，豈得常顧羣。","山連巴湘遠，水與荆吳分。","清光日修阻，尺素安可論。","相思寄夢寐，瑤草空氛氳。"]', '["春江日未曛，楚客酣送君。","翩翩孤黄鹤，万里滄洲云。","四方各有志，豈得常顧羣。","山連巴湘远，水與荆吳分。","清光日修阻，尺素安可論。","相思寄梦寐，瑤草空氛氳。"]', '诗', 'shi', '', NULL, '送王倫 劉復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a988f56-b22d-48cb-94f1-fc75e2532eab', '長相思', '长相思', 'f339464b-cb90-4bc6-997f-c6e558ebe96b', '唐', '["長相思，在桂林，蒼梧山遠瀟湘深。","秋堂零淚倚金瑟，朱顏搖落隨光陰。","長宵嘹唳鴻命侶，河漢蒼蒼隔牛女。","寧知一水不可渡，況復萬山修且阻。","綵絲織綺文雙鴛，昔時贈君君可憐。","何言一去瓶落井，流塵歇滅金爐前。"]', '["长相思，在桂林，蒼梧山远瀟湘深。","秋堂零泪倚金瑟，朱顏搖落隨光陰。","长宵嘹唳鴻命侶，河漢蒼蒼隔牛女。","寧知一水不可渡，況复万山修且阻。","綵絲织綺文雙鴛，昔时贈君君可怜。","何言一去瓶落井，流塵歇滅金爐前。"]', '诗', 'shi', '', NULL, '長相思 劉復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cd26645-b9bd-4b2c-bbbd-7af03d8bc1b0', '長歌行', '长歌行', 'f339464b-cb90-4bc6-997f-c6e558ebe96b', '唐', '["淮南木落秋雲飛，楚宮商歌今正悲。","青春白日不與我，當壚舉酒勸君持。","出門驅馳四方事，徒用辛勤不得意。","三山海底無見期，百齡世間莫虛棄。","君不見金城帝業漢家有，東制諸侯欲長久。","姦雄竊命風塵昏，函谷重關不能守。","龍蛇出沒經兩朝，胡虜憑陵大道銷。","河水東流宮闕盡，五陵松柏自蕭蕭。"]', '["淮南木落秋云飞，楚宮商歌今正悲。","青春白日不與我，當壚舉酒勸君持。","出门驱驰四方事，徒用辛勤不得意。","三山海底無见期，百齡世间莫虛棄。","君不见金城帝業漢家有，东制諸侯欲长久。","姦雄竊命风塵昏，函谷重关不能守。","龙蛇出沒經兩朝，胡虜憑陵大道銷。","河水东流宮闕尽，五陵松柏自蕭蕭。"]', '诗', 'shi', '', NULL, '長歌行 劉復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57d4ff2e-1617-4bbc-a647-be4beb69097a', '春遊曲', '春游曲', 'f339464b-cb90-4bc6-997f-c6e558ebe96b', '唐', '["春風戲狹斜，相見莫愁家。","細酌蒲桃酒，嬌歌玉樹花。","裁衫催白紵，迎客走朱車。","不覺重城暮，爭栖柳上鵶。"]', '["春风戲狹斜，相见莫愁家。","細酌蒲桃酒，嬌歌玉樹花。","裁衫催白紵，迎客走朱车。","不覺重城暮，爭栖柳上鵶。"]', '诗', 'shi', '', NULL, '春遊曲 劉復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0892fc2-dffd-4c1c-bb5d-7e1191d6b3d6', '雜曲', '杂曲', 'f339464b-cb90-4bc6-997f-c6e558ebe96b', '唐', '["寶劒飾文犀，當風似切泥。","逢君感意氣，貰酒杜陵西。","趙女顏雖少，宛駒齒正齊。","嬌多不肯別，更待夜烏啼。"]', '["寶劒飾文犀，當风似切泥。","逢君感意氣，貰酒杜陵西。","趙女顏雖少，宛駒齒正齊。","嬌多不肯別，更待夜烏啼。"]', '诗', 'shi', '', NULL, '雜曲 劉復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('664fbadd-e1f7-4f7e-b8b4-919f553258fd', '春雨', '春雨', 'f339464b-cb90-4bc6-997f-c6e558ebe96b', '唐', '["細雨度深閨，鶯愁欲嬾啼。","如煙飛漠漠，似露濕淒淒。","草色行看靡，花枝暮欲低。","曉聽鐘鼓動，早送錦障泥。"]', '["細雨度深閨，鶯愁欲嬾啼。","如煙飞漠漠，似露濕淒淒。","草色行看靡，花枝暮欲低。","晓听鐘鼓动，早送錦障泥。"]', '诗', 'shi', '', NULL, '春雨 劉復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0db8ad0c-911f-4fe2-88de-4cb245fcfd0d', '夕次襄邑', '夕次襄邑', 'f339464b-cb90-4bc6-997f-c6e558ebe96b', '唐', '["何處成吾道，經年遠路中。","客心猶向北，河水自歸東。","古戍飄殘角，疎林振夕風。","輕舟難載月，那與故人同。"]', '["何处成吾道，經年远路中。","客心猶向北，河水自归东。","古戍飄殘角，疎林振夕风。","轻舟难載月，那與故人同。"]', '诗', 'shi', '', NULL, '夕次襄邑 劉復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b45440d-9cf5-4912-97b6-ed2dbf4b28e5', '夏日', '夏日', 'f339464b-cb90-4bc6-997f-c6e558ebe96b', '唐', '["暎日紗窗深且閑，含桃紅日石榴殷。","銀瓶綆轉桐花井，沈水煙銷金博山。","文簟象牀嬌倚瑟，綵匳銅鏡嬾拈環。","明朝戲去誰相伴，年少相逢狹路間。"]', '["暎日紗窗深且闲，含桃紅日石榴殷。","銀瓶綆轉桐花井，沈水煙銷金博山。","文簟象牀嬌倚瑟，綵匳銅镜嬾拈环。","明朝戲去誰相伴，年少相逢狹路间。"]', '诗', 'shi', '', NULL, '夏日 劉復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14ed8f09-9c84-4e1e-b814-6c6c21aacf63', '送黃曄明府岳州湘陰赴任', '送黄曄明府岳州湘陰赴任', 'f339464b-cb90-4bc6-997f-c6e558ebe96b', '唐', '["擬占名塲第一科，龍門十上困風波。","三年護塞從戎遠，萬里投荒失意多。","花縣到時銅墨貴，葉舟行處水雲和。","遙知布惠蘇民後，應向祠堂弔汨羅。"]', '["擬占名塲第一科，龙门十上困风波。","三年護塞從戎远，万里投荒失意多。","花縣到时銅墨貴，葉舟行处水云和。","遙知布惠蘇民後，應向祠堂弔汨羅。"]', '诗', 'shi', '', NULL, '送黃曄明府岳州湘陰赴任 劉復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83ae6d70-db9c-47ec-856d-283076615700', '禪門寺暮鐘', '禪门寺暮鐘', 'f339464b-cb90-4bc6-997f-c6e558ebe96b', '唐', '["簨簴高懸于闐鐘，黃昏發地殷龍宮。","遊人憶到嵩山夜，疊閣連樓滿太空。"]', '["簨簴高懸于闐鐘，黄昏發地殷龙宮。","游人憶到嵩山夜，叠閣連楼满太空。"]', '诗', 'shi', '', NULL, '禪門寺暮鐘 劉復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a369c730-c93d-4fb1-a235-ce7a1ec8f40c', '同張深秀才遊華嚴寺', '同張深秀才游华嚴寺', '9f0732d5-e1de-441d-8bf7-a6de05ead378', '唐', '["同遊雲外寺，渡水入禪關。","立埽窗前石，坐看池上山。","有僧飛錫到，留客話松間。","不是緣名利，好來長伴閑。"]', '["同游云外寺，渡水入禪关。","立埽窗前石，坐看池上山。","有僧飞錫到，留客話松间。","不是緣名利，好来长伴闲。"]', '诗', 'shi', '', NULL, '同張深秀才遊華嚴寺 冷朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0bee52e-3b61-475b-9f5b-120e056e24da', '中秋與空上人同宿華嚴寺', '中秋與空上人同宿华嚴寺', '9f0732d5-e1de-441d-8bf7-a6de05ead378', '唐', '["埽榻相逢宿，論詩舊梵宮。","磬聲迎鼓盡，月色過山窮。","庭簇安禪草，窗飛帶火蟲。","一宵何惜別，回首隔秋風。"]', '["埽榻相逢宿，論诗旧梵宮。","磬声迎鼓尽，月色過山窮。","庭簇安禪草，窗飞带火蟲。","一宵何惜別，回首隔秋风。"]', '诗', 'shi', '', NULL, '中秋與空上人同宿華嚴寺 冷朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8a97318-e6dd-4bbf-a599-3ef79b4d6f13', '宿柏巖寺', '宿柏巖寺', '9f0732d5-e1de-441d-8bf7-a6de05ead378', '唐', '["幽寺在巖中，行唯一徑通。","客吟孤嶠月，蟬噪數枝風。","秋色生苔砌，泉聲入梵宮。","吾師修道處，不與世間同。"]', '["幽寺在巖中，行唯一徑通。","客吟孤嶠月，蟬噪數枝风。","秋色生苔砌，泉声入梵宮。","吾師修道处，不與世间同。"]', '诗', 'shi', '', NULL, '宿柏巖寺 冷朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aef47bc-c87f-4bf7-934d-bbc59b8da971', '登靈善寺塔', '登靈善寺塔', '9f0732d5-e1de-441d-8bf7-a6de05ead378', '唐', '["飛閣青霞裏，先秋獨早涼。","天花映窗近，月桂拂簷香。","華岳三峰小，黃河一帶長。","空聞指歸路，煙處有垂楊。"]', '["飞閣青霞裏，先秋独早涼。","天花映窗近，月桂拂簷香。","华岳三峰小，黄河一带长。","空闻指归路，煙处有垂楊。"]', '诗', 'shi', '', NULL, '登靈善寺塔 冷朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a5c5d0f-c729-4ca6-8655-68557df89721', '瀑布泉', '瀑布泉', '9f0732d5-e1de-441d-8bf7-a6de05ead378', '唐', '["潺湲半空裏，霖落石房邊。","風激珠光碎，山欹練影偏。","急流難起浪，迸沫祗如煙。","自古惟今日，淒涼一片泉。"]', '["潺湲半空裏，霖落石房邊。","风激珠光碎，山欹練影偏。","急流难起浪，迸沫祗如煙。","自古惟今日，淒涼一片泉。"]', '诗', 'shi', '', NULL, '瀑布泉 冷朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05bfc235-c784-4456-b6b2-9b0829433f28', '冬日逢馮法曹話懷', '冬日逢馮法曹話懷', '9f0732d5-e1de-441d-8bf7-a6de05ead378', '唐', '["分襟二年內，多少事相干。","禮樂風全變，塵埃路漸難。","秋林新葉落，霜月滿庭寒。","雖喜逢知己，他鄉歲又闌。"]', '["分襟二年內，多少事相干。","禮乐风全变，塵埃路漸难。","秋林新葉落，霜月满庭寒。","雖喜逢知己，他乡歲又闌。"]', '诗', 'shi', '', NULL, '冬日逢馮法曹話懷 冷朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7d09cc0-8468-4c8a-b340-67c15159da19', '送唐六赴舉', '送唐六赴舉', '9f0732d5-e1de-441d-8bf7-a6de05ead378', '唐', '["秋色生邊思，送君西入關。","草衰空大野，葉落露青山。","故國煙霞外，新安道路間。","碧霄知己在，香桂月中攀。"]', '["秋色生邊思，送君西入关。","草衰空大野，葉落露青山。","故国煙霞外，新安道路间。","碧霄知己在，香桂月中攀。"]', '诗', 'shi', '', NULL, '送唐六赴舉 冷朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6ce38df-fe11-4c4c-b584-b1df4b7bd580', '送遠上人歸京', '送远上人归京', '9f0732d5-e1de-441d-8bf7-a6de05ead378', '唐', '["夏臘歲方深，思歸徹曙吟。","未離銷雪院，已有過雲心。","寒磬清函谷，孤鐘宿華陰。","別京遊舊寺，月色似雙林。"]', '["夏臘歲方深，思归徹曙吟。","未離銷雪院，已有過云心。","寒磬清函谷，孤鐘宿华陰。","別京游旧寺，月色似雙林。"]', '诗', 'shi', '', NULL, '送遠上人歸京 冷朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f42d7731-d87a-4b1f-b9cb-c84c5fac675b', '別郎上人', '別郎上人', '9f0732d5-e1de-441d-8bf7-a6de05ead378', '唐', '["過雲尋釋子，話別更依依。","靜室開來久，遊人到自稀。","觸風香氣盡，隔水磬聲微。","獨傍孤松立，塵中多是非。"]', '["過云尋釋子，話別更依依。","静室开来久，游人到自稀。","觸风香氣尽，隔水磬声微。","独傍孤松立，塵中多是非。"]', '诗', 'shi', '', NULL, '別郎上人 冷朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e9e1d1d-9862-47d8-bf68-23cf477c1744', '立春', '立春', '9f0732d5-e1de-441d-8bf7-a6de05ead378', '唐', '["玉律傳佳節，青陽應此辰。","土牛呈歲稔，綵燕表年春。","臘盡星迴次，寒餘月建寅。","風光行處好，雲物望中新。","流水初銷凍，潛魚欲振鱗。","梅花將柳色，偏思越鄉人。"]', '["玉律傳佳節，青陽應此辰。","土牛呈歲稔，綵燕表年春。","臘尽星迴次，寒餘月建寅。","风光行处好，云物望中新。","流水初銷凍，潛鱼欲振鱗。","梅花將柳色，偏思越乡人。"]', '诗', 'shi', '', NULL, '立春 冷朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5ee91d2-3649-4ef3-9310-953468fc9eea', '送紅線', '送紅線', '9f0732d5-e1de-441d-8bf7-a6de05ead378', '唐', '["採菱歌怨木蘭舟，送客魂銷百尺樓。","還似洛妃乘霧去，碧天無際水空流。"]', '["採菱歌怨木蘭舟，送客魂銷百尺楼。","還似洛妃乘霧去，碧天無際水空流。"]', '诗', 'shi', '', NULL, '送紅線 冷朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52a41a91-414f-46df-97d5-e9aad9e036bf', '南至日太史登臺書雲物', '南至日太史登台书云物', '327767c2-784d-4c9e-8474-ecc043b3600a', '唐', '["至日行時令，登臺約禮文。","官稱伯趙氏，色辨五方雲。","晝漏聽初發，陽光望漸分。","司天爲歲備，持簡出人羣。","惠愛周微物，生靈荷聖君。","長當有嘉瑞，郁郁復紛紛。"]', '["至日行时令，登台約禮文。","官稱伯趙氏，色辨五方云。","晝漏听初發，陽光望漸分。","司天爲歲備，持簡出人羣。","惠愛周微物，生靈荷聖君。","长當有嘉瑞，郁郁复紛紛。"]', '诗', 'shi', '', NULL, '南至日太史登臺書雲物 于尹躬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3a0e085-4365-4f29-bcf1-0b3b2ad336ab', '贈別二首 一', '贈別二首 一', 'b9206a8c-e117-47d8-a527-a23350bfdf10', '唐', '["江浦程千里，離尊淚數行。","無論吳與楚，俱是客他鄉。"]', '["江浦程千里，離尊泪數行。","無論吳與楚，俱是客他乡。"]', '诗', 'shi', '', NULL, '贈別二首 一 柳郴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85bed92d-9dd4-4dbe-bda5-71b947320d5c', '贈別二首 二', '贈別二首 二', 'b9206a8c-e117-47d8-a527-a23350bfdf10', '唐', '["何處最悲辛，長亭臨古津。","往來舟檝路，前後別離人。"]', '["何处最悲辛，长亭臨古津。","往来舟檝路，前後別離人。"]', '诗', 'shi', '', NULL, '贈別二首 二 柳郴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac33036a-7a0b-44cb-bbc6-1362e9b53b62', '句', '句', 'b9206a8c-e117-47d8-a527-a23350bfdf10', '唐', '["他鄉生白髮，舊國有青山。"]', '["他乡生白髮，旧国有青山。"]', '诗', 'shi', '', NULL, '句 柳郴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63b9ffb4-4993-4fec-ab57-9276187a6e91', '望終南春雪', '望終南春雪', '25484cc8-36b6-4dad-913a-6e06e6084511', '唐', '["山勢抱西秦，初年瑞雪頻。","色搖鶉野霽，影落鳳城春。","輝燿銀峰逼，晶明玉樹親。","尚寒由氣勁，不夜爲光新。","荆岫全疑近，崑丘宛合鄰。","餘輝儻可借，迴照讀書人。"]', '["山勢抱西秦，初年瑞雪頻。","色搖鶉野霽，影落鳳城春。","輝燿銀峰逼，晶明玉樹親。","尚寒由氣勁，不夜爲光新。","荆岫全疑近，崑丘宛合鄰。","餘輝儻可借，迴照读书人。"]', '诗', 'shi', '', NULL, '望終南春雪 李子卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb93e8b8-19cd-4586-a6d0-875ec3506a1d', '九日登青山', '九日登青山', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["昔人惆悵處，繫馬又登臨。","舊地煙霞在，多時草木深。","水將空合色，雲與我無心。","想見龍山會，良辰亦似今。"]', '["昔人惆悵处，繫马又登臨。","旧地煙霞在，多时草木深。","水將空合色，云與我無心。","想见龙山會，良辰亦似今。"]', '诗', 'shi', '', NULL, '九日登青山 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('621d6001-ea93-4bce-adb6-7e085437f15f', '秋夜宴王郎中宅賦得露中菊', '秋夜宴王郎中宅賦得露中菊', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["衆芳春競發，寒菊露偏滋。","受氣何曾異，開花獨自遲。","晚成猶待賞，欲採未過時。","忍棄東籬下，看隨秋草衰。"]', '["衆芳春競發，寒菊露偏滋。","受氣何曾異，开花独自遲。","晚成猶待賞，欲採未過时。","忍棄东籬下，看隨秋草衰。"]', '诗', 'shi', '', NULL, '秋夜宴王郎中宅賦得露中菊 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc9d8acc-dd78-45a2-a5dd-5e62eb3ca8ff', '奉使設宴戲擲籠籌', '奉使設宴戲擲籠籌', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["今日陪樽俎，良籌復在茲。","獻酬君有禮，賞罰我無私。","莫怪斜相向，還將正自持。","一朝權入手，看取令行時。"]', '["今日陪樽俎，良籌复在茲。","獻酬君有禮，賞罰我無私。","莫怪斜相向，還將正自持。","一朝權入手，看取令行时。"]', '诗', 'shi', '', NULL, '奉使設宴戲擲籠籌 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6d41ea6-82ca-4be2-9c3a-844e62d5b573', '詠雙陸骰子', '詠雙陸骰子', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["采采應緣白，鑽心不爲名。","掌中猶可重，手下莫言輕。","有對唯求敵，無私直任爭。","君看一擲後，當取擅場聲。"]', '["采采應緣白，鑽心不爲名。","掌中猶可重，手下莫言轻。","有对唯求敵，無私直任爭。","君看一擲後，當取擅場声。"]', '诗', 'shi', '', NULL, '詠雙陸骰子 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eb22f0f-865f-45e9-9c97-95715d6a495a', '詠壁上酒瓢呈蕭明府', '詠壁上酒瓢呈蕭明府', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["不是難提挈，行藏固有期。","安身未得所，開口欲從誰。","應物心無倦，當壚柄會持。","莫將成廢器，還有對樽時。"]', '["不是难提挈，行藏固有期。","安身未得所，开口欲從誰。","應物心無倦，當壚柄會持。","莫將成廢器，還有对樽时。"]', '诗', 'shi', '', NULL, '詠壁上酒瓢呈蕭明府 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8f97067-cf54-4f31-9b18-8aa489c9b4b3', '詠玉', '詠玉', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["歌玉屢招疑，終朝省復思。","既哀黃鳥興，還復白圭詩。","請益先求友，將行必擇師。","誰知不鳴者，獨下董生帷。"]', '["歌玉屢招疑，終朝省复思。","既哀黄鸟兴，還复白圭诗。","請益先求友，將行必擇師。","誰知不鳴者，独下董生帷。"]', '诗', 'shi', '', NULL, '詠玉 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0af3c45d-ce51-428d-b68a-d1273339e102', '送陳偃賦得白鳥翔翠微', '送陳偃賦得白鸟翔翠微', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["不知鷗與鶴，天畔弄晴暉。","背日分明見，臨川相暎微。","淨中雲一點，回處雪孤飛。","正好南枝住，翩翩何所歸。"]', '["不知鷗與鹤，天畔弄晴暉。","背日分明见，臨川相暎微。","淨中云一点，回处雪孤飞。","正好南枝住，翩翩何所归。"]', '诗', 'shi', '', NULL, '送陳偃賦得白鳥翔翠微 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('065ec7f4-bdf5-4012-bf73-d38328e1001b', '題段上人院壁畫古松', '題段上人院壁畫古松', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["石上盤古根，謂言天生有。","安知草木性，變在畫師手。","陰深方丈間，直趣幽且閑。","木紋離披勢搓捽，中裂空心火燒出。","掃成三寸五寸枝，便是千年萬年物。","莓苔濃淡色不同，一面死皮生蠹蟲。","風霜未必來到此，氣色杳在寒山中。","孤標可玩不可取，能使支公道場古。"]', '["石上盤古根，謂言天生有。","安知草木性，变在畫師手。","陰深方丈间，直趣幽且闲。","木紋離披勢搓捽，中裂空心火燒出。","掃成三寸五寸枝，便是千年万年物。","莓苔濃淡色不同，一面死皮生蠹蟲。","风霜未必来到此，氣色杳在寒山中。","孤標可玩不可取，能使支公道場古。"]', '诗', 'shi', '', NULL, '題段上人院壁畫古松 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f4067b1-b822-4ef2-84d4-24f473b14178', '逼寒節寄崔七', '逼寒節寄崔七', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["閑庭只是長莓苔，三徑曾無車馬來。","旅館尚愁寒食火，羈心嬾向不然灰。","門前下客雖彈鋏，溪畔窮魚且曝腮。","他日趨庭應問禮，須言陋巷有顏回。"]', '["闲庭只是长莓苔，三徑曾無车马来。","旅館尚愁寒食火，羈心嬾向不然灰。","门前下客雖彈鋏，溪畔窮鱼且曝腮。","他日趨庭應问禮，須言陋巷有顏回。"]', '诗', 'shi', '', NULL, '逼寒節寄崔七 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c6325fe-fafd-4ed0-ba14-562b7e7ff760', '長安喜雪', '长安喜雪', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["千門萬戶雪花浮，點點無聲落瓦溝。","全似玉塵消更積，半成冰片結還流。","光含曉色清天苑，輕逐微風遶御樓。","平地已霑盈尺潤，年豐須荷富人侯。"]', '["千门万戶雪花浮，点点無声落瓦溝。","全似玉塵消更積，半成冰片結還流。","光含晓色清天苑，轻逐微风遶御楼。","平地已霑盈尺潤，年豐須荷富人侯。"]', '诗', 'shi', '', NULL, '長安喜雪 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c77bab05-cc71-4bdd-ae62-d41d35d0792e', '宴楊駙馬山亭', '宴楊駙马山亭', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["垂楊拂岸草茸茸，繡戶窗前花影重。","鱠下玉盤紅縷細，酒開金甕綠醅濃。","中朝駙馬何平叔，南國詞人陸士龍。","落日泛舟同醉處，回潭百丈映千峰。"]', '["垂楊拂岸草茸茸，繡戶窗前花影重。","鱠下玉盤紅縷細，酒开金甕綠醅濃。","中朝駙马何平叔，南国词人陸士龙。","落日泛舟同醉处，回潭百丈映千峰。"]', '诗', 'shi', '', NULL, '宴楊駙馬山亭 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ee73c58-cce4-4852-b95b-73ce2d12618e', '過宣上人湖上蘭若', '過宣上人湖上蘭若', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["十年湖上結幽期，偏向東林遇遠師。","未道姓名童子識，不酬言語上人知。","閑花落日滋苔徑，細雨和煙著柳枝。","問我別來何所得，解將無事當無爲。"]', '["十年湖上結幽期，偏向东林遇远師。","未道姓名童子識，不酬言語上人知。","闲花落日滋苔徑，細雨和煙著柳枝。","问我別来何所得，解將無事當無爲。"]', '诗', 'shi', '', NULL, '過宣上人湖上蘭若 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38a81bbb-f8b7-41a8-a456-a5c1cd4ba4ea', '同達奚宰遊竇子明仙壇', '同達奚宰游竇子明仙壇', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["松檜陰深一徑微，中峰石室到人稀。","仙官不住青山在，故老相傳白日飛。","華表問栽何歲木，片雲留著去時衣。","今朝茂宰尋真處，暫駐雙鳧且莫歸。"]', '["松檜陰深一徑微，中峰石室到人稀。","仙官不住青山在，故老相傳白日飞。","华表问栽何歲木，片云留著去时衣。","今朝茂宰尋真处，暫駐雙鳧且莫归。"]', '诗', 'shi', '', NULL, '同達奚宰遊竇子明仙壇 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecad5c4e-aaeb-4f85-bf79-036e6fe92b66', '平陵寓居再逢寒食', '平陵寓居再逢寒食', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["幾迴江上泣途窮，每遇良辰歎轉蓬。","火燧知從新節變，灰心還與故人同。","莫聽黃鳥愁啼處，自有花開久客中。","貧病固應無撓事，但將懷抱醉春風。"]', '["幾迴江上泣途窮，每遇良辰歎轉蓬。","火燧知從新節变，灰心還與故人同。","莫听黄鸟愁啼处，自有花开久客中。","貧病固應無撓事，但將懷抱醉春风。"]', '诗', 'shi', '', NULL, '平陵寓居再逢寒食 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24349e0b-7e0e-4ce2-9173-1550c7f8be81', '尋隱者韋九山人於東溪草堂', '尋隐者韋九山人於东溪草堂', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["尋得仙源訪隱淪，漸來深處漸無塵。","初行竹裹唯通馬，直到花間始見人。","四面雲山誰作主，數家煙火自爲鄰。","路傍樵客何須問，朝市如今不是秦。"]', '["尋得仙源訪隐淪，漸来深处漸無塵。","初行竹裹唯通马，直到花间始见人。","四面云山誰作主，數家煙火自爲鄰。","路傍樵客何須问，朝市如今不是秦。"]', '诗', 'shi', '', NULL, '尋隱者韋九山人於東溪草堂 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78a5efb6-04b4-46ba-b030-8deb41e810d3', '假攝池州留別東溪隱居', '假攝池州留別东溪隐居', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["一官仍是假，豈願數離羣。","愁鬢看如雪，浮名認是雲。","暫辭南國隱，莫勒北山文。","今後松溪月，還應夢見君。"]', '["一官仍是假，豈願數離羣。","愁鬢看如雪，浮名認是云。","暫辞南国隐，莫勒北山文。","今後松溪月，還應梦见君。"]', '诗', 'shi', '', NULL, '假攝池州留別東溪隱居 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('152fef94-01eb-445c-b918-434d41891ab8', '詠柏板', '詠柏板', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["赴節心長在，從繩道可觀。","須知片木用，莫向散材看。","空爲歌偏苦，仍愁和即難。","既能親掌握，願得接同歡。"]', '["赴節心长在，從繩道可观。","須知片木用，莫向散材看。","空爲歌偏苦，仍愁和即难。","既能親掌握，願得接同歡。"]', '诗', 'shi', '', NULL, '詠柏板 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1315df6-abd2-433d-a297-763163959091', '箏柱子', '箏柱子', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["散木今何幸，良工不棄捐。","力微慙一柱，材薄仰羣弦。","且喜聲相應，寧辭跡屢遷。","知音如見賞，雅調爲君傳。"]', '["散木今何幸，良工不棄捐。","力微慙一柱，材薄仰羣弦。","且喜声相應，寧辞跡屢遷。","知音如见賞，雅調爲君傳。"]', '诗', 'shi', '', NULL, '箏柱子 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b82ca5fb-1edb-4931-8c43-975a2a9ca0de', '送李司直歸浙東幕兼寄鮑行軍持節大夫初拜東平郡王', '送李司直归浙东幕兼寄鲍行軍持節大夫初拜东平郡王', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["翩翩書記早曾聞，二十年來願見君。","今日相逢悲白髮，同時幾許在青雲。","人從北固山邊去，水到西陵渡口分。","會作王門曳裙客，爲余前謝鮑參軍。"]', '["翩翩书記早曾闻，二十年来願见君。","今日相逢悲白髮，同时幾許在青云。","人從北固山邊去，水到西陵渡口分。","會作王门曳裙客，爲余前謝鲍參軍。"]', '诗', 'shi', '', NULL, '送李司直歸浙東幕兼寄鮑行軍持節大夫初拜東平郡王 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6197387a-f00c-48df-8812-d27213d7d543', '七賢廟', '七賢廟', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["常慕晉高士，放心日沈冥。","湛然對一壺，土木爲我形。","下馬訪陳迹，披榛詣荒庭。","相看兩不言，猶謂醉未醒。","長嘯或可擬，幽琴難再聽。","同心不共世，空見蘚門青。"]', '["常慕晉高士，放心日沈冥。","湛然对一壺，土木爲我形。","下马訪陳迹，披榛詣荒庭。","相看兩不言，猶謂醉未醒。","长嘯或可擬，幽琴难再听。","同心不共世，空见蘚门青。"]', '诗', 'shi', '', NULL, '七賢廟 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6400a6ba-98f1-4bd0-8f53-402727624022', '同清江師月夜聽堅正二上人爲懷州轉法華經歌', '同清江師月夜听堅正二上人爲懷州轉法华經歌', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["若耶谿畔雲門僧，夜閑燕坐聽真乘。","蓮花祕偈藥草喻，二師身住口不住。","鑿井求泉會到源，閉門避火終迷路。","前心後心皆此心，梵音妙音柔軟音。","清泠霜磬有時動，寂歷空堂宜夜深。","向來不寐何所事，一念纔生百慮息。","風翻亂葉林有聲，雪映閑庭月無色。","玄關密跡難可思，醒人悟兮醉人疑。","衣中繫寶覺者誰，臨川內史字得之。"]', '["若耶谿畔云门僧，夜闲燕坐听真乘。","蓮花祕偈藥草喻，二師身住口不住。","鑿井求泉會到源，閉门避火終迷路。","前心後心皆此心，梵音妙音柔軟音。","清泠霜磬有时动，寂歷空堂宜夜深。","向来不寐何所事，一念纔生百慮息。","风翻亂葉林有声，雪映闲庭月無色。","玄关密跡难可思，醒人悟兮醉人疑。","衣中繫寶覺者誰，臨川內史字得之。"]', '诗', 'shi', '', NULL, '同清江師月夜聽堅正二上人爲懷州轉法華經歌 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8493b95e-28d1-475c-8db3-756f2e662cf1', '寒城晚角', '寒城晚角', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["高臺高高畫角雄，五更初發寒城中。","寒城北臨大河水，淇門賊烽隔岸是。","長風送過黎陽川，我軍氣雄賊心死。","羇人此夜寐不成，萬里邊情枕上生。","乍似隴頭戍，寒泉幽咽流不住。","又如巴江頭，啼猨帶雨斷續愁。","忽憶嫖姚北征伐，空山宿兵寒對月。","一聲老將起，三奏行人發。","冀馬爲之嘶，朔雲爲之結。","二十年來天下兵，到處不曾無此聲。","洛陽陌，長安路。","角聲朝朝兼暮暮，平居聞之尚難度。","何況天山征戍兒，雲中下營雪裏吹。"]', '["高台高高畫角雄，五更初發寒城中。","寒城北臨大河水，淇门賊烽隔岸是。","长风送過黎陽川，我軍氣雄賊心死。","羇人此夜寐不成，万里邊情枕上生。","乍似隴头戍，寒泉幽咽流不住。","又如巴江头，啼猨带雨斷續愁。","忽憶嫖姚北征伐，空山宿兵寒对月。","一声老將起，三奏行人發。","冀马爲之嘶，朔云爲之結。","二十年来天下兵，到处不曾無此声。","洛陽陌，长安路。","角声朝朝兼暮暮，平居闻之尚难度。","何況天山征戍兒，云中下營雪裏吹。"]', '诗', 'shi', '', NULL, '寒城晚角 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0693d540-58d0-4345-b184-4e42c4360903', '重陽日陪韋卿讌', '重陽日陪韋卿讌', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["何必龍山好，南亭賞不暌。","清規陳侯事，雅興謝公題。","入座青峰近，當軒遠樹齊。","仙家自有月，莫歎夕陽西。"]', '["何必龙山好，南亭賞不暌。","清規陳侯事，雅兴謝公題。","入座青峰近，當軒远樹齊。","仙家自有月，莫歎夕陽西。"]', '诗', 'shi', '', NULL, '重陽日陪韋卿讌 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b1b0bdf-4b31-4849-8637-382b1f3f0350', '憶長安 四月', '憶长安 四月', 'fef74ee3-6b39-40bc-9d31-939b46ffabe1', '唐', '["憶長安，四月時，南郊萬乘旌旗。","嘗酎玉巵更獻，含桃絲籠交馳。","芳草落花無限，金張許史相隨。"]', '["憶长安，四月时，南郊万乘旌旗。","嘗酎玉巵更獻，含桃絲籠交驰。","芳草落花無限，金張許史相隨。"]', '诗', 'shi', '', NULL, '憶長安 四月 丘丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28970cea-caf4-4698-bc13-0560500b8235', '狀江南 季冬', '狀江南 季冬', 'fef74ee3-6b39-40bc-9d31-939b46ffabe1', '唐', '["江南季冬月，紅蟹大如𤬊。","湖水龍爲鏡，爐峰氣作煙。"]', '["江南季冬月，紅蟹大如𤬊。","湖水龙爲镜，爐峰氣作煙。"]', '诗', 'shi', '', NULL, '狀江南 季冬 丘丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9409e3c8-2fa4-4b6c-97c0-8de5e4d3cfec', '和韋使君秋夜見寄', '和韋使君秋夜见寄', 'fef74ee3-6b39-40bc-9d31-939b46ffabe1', '唐', '["露滴梧葉鳴，秋風桂花發。","中有學仙侶，吹簫弄山月。"]', '["露滴梧葉鳴，秋风桂花發。","中有学仙侶，吹簫弄山月。"]', '诗', 'shi', '', NULL, '和韋使君秋夜見寄 丘丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8d776d7-fdd3-4bb6-8a39-8806e79fa02f', '奉酬韋蘇州使君', '奉酬韋蘇州使君', 'fef74ee3-6b39-40bc-9d31-939b46ffabe1', '唐', '["久作煙霞侶，蹔將簪組親。","還同褚伯玉，入館忝州人。"]', '["久作煙霞侶，蹔將簪組親。","還同褚伯玉，入館忝州人。"]', '诗', 'shi', '', NULL, '奉酬韋蘇州使君 丘丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24d17590-1447-476d-9736-8f9f14c567f7', '和韋使君聽江笛送陳侍御', '和韋使君听江笛送陳侍御', 'fef74ee3-6b39-40bc-9d31-939b46ffabe1', '唐', '["離樽聞夜笛，寥亮入寒城。","月落車馬散，悽惻主人情。"]', '["離樽闻夜笛，寥亮入寒城。","月落车马散，悽惻主人情。"]', '诗', 'shi', '', NULL, '和韋使君聽江笛送陳侍御 丘丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34e1ae2f-fc4d-4f48-aff3-3a4902f4e44b', '奉酬韋使君送歸山之作', '奉酬韋使君送归山之作', 'fef74ee3-6b39-40bc-9d31-939b46ffabe1', '唐', '["側聞郡守至，偶乘黃犢出。","不別桃源人，一見經累日。","蟬鳴念秋稼，蘭酌動離瑟。","臨水降麾幢，野艇纔容膝。","參差碧山路，目送江帆疾。","涉海得驪珠，棲梧慚鳳質。","媿非鄭公里，歸掃蒙籠室。"]', '["側闻郡守至，偶乘黄犢出。","不別桃源人，一见經累日。","蟬鳴念秋稼，蘭酌动離瑟。","臨水降麾幢，野艇纔容膝。","參差碧山路，目送江帆疾。","涉海得驪珠，棲梧慚鳳質。","媿非鄭公里，归掃蒙籠室。"]', '诗', 'shi', '', NULL, '奉酬韋使君送歸山之作 丘丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80f04f2b-da28-4c7b-8015-f9e6c11d3400', '奉酬重送歸山', '奉酬重送归山', 'fef74ee3-6b39-40bc-9d31-939b46ffabe1', '唐', '["賣藥有時至，自知來往疎。","遽辭池上酌，新得山中書。","步出芙蓉府，歸乘觳𧥆車。","猥蒙招隱作，豈愧班生廬。"]', '["賣藥有时至，自知来往疎。","遽辞池上酌，新得山中书。","步出芙蓉府，归乘觳𧥆车。","猥蒙招隐作，豈愧班生廬。"]', '诗', 'shi', '', NULL, '奉酬重送歸山 丘丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7317a3f9-118f-401d-bc47-70f328d6341f', '經湛長史草堂', '經湛长史草堂', 'fef74ee3-6b39-40bc-9d31-939b46ffabe1', '唐', '["身退謝名累，道存嘉止足。","設醴降華幡，挂冠守空谷。","偶尋野外寺，仰慕賢者躅。","不見昔簪裾，猶有舊松竹。","煙霞雖異世，風韻如在矚。","余即江海上，歸轍青山曲。"]', '["身退謝名累，道存嘉止足。","設醴降华幡，挂冠守空谷。","偶尋野外寺，仰慕賢者躅。","不见昔簪裾，猶有旧松竹。","煙霞雖異世，风韻如在矚。","余即江海上，归轍青山曲。"]', '诗', 'shi', '', NULL, '經湛長史草堂 丘丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de8e8337-42e1-40c9-9cb6-0f846b1fb014', '蕭山祗園寺', '蕭山祗园寺', 'fef74ee3-6b39-40bc-9d31-939b46ffabe1', '唐', '["東晉許徴君，西方彥上人。","生時猶定見，悟後了前因。","靈塔多年古，高僧苦行頻。","碑存纔記日，藤老豈知春。","車騎歸蕭詧，雲林識許詢。","千秋不相見，悟定是吾身。"]', '["东晉許徴君，西方彥上人。","生时猶定见，悟後了前因。","靈塔多年古，高僧苦行頻。","碑存纔記日，藤老豈知春。","车騎归蕭詧，云林識許詢。","千秋不相见，悟定是吾身。"]', '诗', 'shi', '', NULL, '蕭山祗園寺 丘丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b08883e7-d43b-45fd-9c1d-b770b8e8bbdf', '奉使過石門觀瀑', '奉使過石门观瀑', 'fef74ee3-6b39-40bc-9d31-939b46ffabe1', '唐', '["溪上望懸泉，耿耿雲中見。","披榛上巖岫，峭壁正東面。","千仞瀉聯珠，一潭噴飛霰。","嵯𤄓滿山響，坐覺炎氛變。","照日類虹霓，從風似綃練。","靈奇既天造，惜處窮海甸。","吾祖昔登臨，謝公亦遊衍。","王程懼淹泊，下磴空延眷。","千里雷尚聞，巒迴樹葱蒨。","此來共賤役，探討愧前彥。","永欲洗塵纓，終當愜此願。"]', '["溪上望懸泉，耿耿云中见。","披榛上巖岫，峭壁正东面。","千仞瀉聯珠，一潭噴飞霰。","嵯𤄓满山响，坐覺炎氛变。","照日類虹霓，從风似綃練。","靈奇既天造，惜处窮海甸。","吾祖昔登臨，謝公亦游衍。","王程懼淹泊，下磴空延眷。","千里雷尚闻，巒迴樹葱蒨。","此来共賤役，探討愧前彥。","永欲洗塵纓，終當愜此願。"]', '诗', 'shi', '', NULL, '奉使過石門觀瀑 丘丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c67ab0b3-dea9-4b02-ab62-cae441b1d4a9', '秋夕宿石門館', '秋夕宿石门館', 'fef74ee3-6b39-40bc-9d31-939b46ffabe1', '唐', '["暝從石門宿，搖落四巖空。","潭月漾山足，天河瀉澗中。","杉松寒似雨，猨鳥夕驚風。","獨臥不成寢，蒼然想謝公。"]', '["暝從石门宿，搖落四巖空。","潭月漾山足，天河瀉澗中。","杉松寒似雨，猨鸟夕驚风。","独臥不成寢，蒼然想謝公。"]', '诗', 'shi', '', NULL, '秋夕宿石門館 丘丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc6dd58f-c26e-4f48-8b0c-cb5d5eb49f7f', '狀江南 孟夏', '狀江南 孟夏', '360ed5db-c7ab-49d8-bef5-fabdbcb97a77', '唐', '["江南孟夏天，慈竹笋如編。","蜃氣爲樓閣，蛙聲作管弦。"]', '["江南孟夏天，慈竹笋如編。","蜃氣爲楼閣，蛙声作管弦。"]', '诗', 'shi', '', NULL, '狀江南 孟夏 賈弇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cc46db5-4610-4109-b1b4-ff6e2c70ee06', '狀江南 仲秋', '狀江南 仲秋', '6b8c4345-2fe4-4283-a44f-000abfb2cd34', '唐', '["江南仲秋天，鱏鼻大如船。","雷是樟亭浪，苔爲界石錢。"]', '["江南仲秋天，鱏鼻大如船。","雷是樟亭浪，苔爲界石錢。"]', '诗', 'shi', '', NULL, '狀江南 仲秋 沈仲昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51c14574-7598-43a3-a8de-e7f95678f9d9', '憶長安 正月', '憶长安 正月', '6ce7e321-1f7b-4d76-963c-07f3ce676670', '唐', '["憶長安，正月時，和風喜氣相隨。","獻壽彤庭萬國，燒燈青玉五枝。","終南往往殘雪，渭水處處流澌。"]', '["憶长安，正月时，和风喜氣相隨。","獻壽彤庭万国，燒灯青玉五枝。","終南往往殘雪，渭水处处流澌。"]', '诗', 'shi', '', NULL, '憶長安 正月 謝良輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63ea4166-22f6-4640-b23d-06dc648c56f4', '憶長安 十二月', '憶长安 十二月', '6ce7e321-1f7b-4d76-963c-07f3ce676670', '唐', '["憶長安，臘月時，溫泉彩仗新移。","瑞氣遙迎鳳輦，日光先暖龍池。","取酒蝦蟇陵下，家家守歲傳巵。"]', '["憶长安，臘月时，溫泉彩仗新移。","瑞氣遙迎鳳輦，日光先暖龙池。","取酒蝦蟇陵下，家家守歲傳巵。"]', '诗', 'shi', '', NULL, '憶長安 十二月 謝良輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a073cbe-3531-40a9-97f6-4a0d5ffddb84', '狀江南 仲春', '狀江南 仲春', '6ce7e321-1f7b-4d76-963c-07f3ce676670', '唐', '["江南仲春天，細雨色如煙。","絲爲武昌柳，布作石門泉。"]', '["江南仲春天，細雨色如煙。","絲爲武昌柳，布作石门泉。"]', '诗', 'shi', '', NULL, '狀江南 仲春 謝良輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31cf12a5-51a2-4d42-9673-e110a4824fd8', '狀江南 孟冬', '狀江南 孟冬', '6ce7e321-1f7b-4d76-963c-07f3ce676670', '唐', '["江南孟冬天，荻穗軟如綿。","綠絹芭蕉裂，黃金橘柚懸。"]', '["江南孟冬天，荻穗軟如綿。","綠絹芭蕉裂，黄金橘柚懸。"]', '诗', 'shi', '', NULL, '狀江南 孟冬 謝良輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4bc93c8-417d-4670-8fc0-ca28d3fa3bf8', '憶長安 二月', '憶长安 二月', '57965443-6045-4af4-ac2a-1120c1a4fb26', '唐', '["憶長安，二月時，玄鳥初至禖祠。","百囀宮鶯繡羽，千條御柳黃絲。","更有曲江勝地，此來寒食佳期。"]', '["憶长安，二月时，玄鸟初至禖祠。","百囀宮鶯繡羽，千條御柳黄絲。","更有曲江勝地，此来寒食佳期。"]', '诗', 'shi', '', NULL, '憶長安 二月 鮑防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de1862c8-278a-40c6-90b8-9106cdb379bc', '狀江南 孟春', '狀江南 孟春', '57965443-6045-4af4-ac2a-1120c1a4fb26', '唐', '["江南孟春天，荇葉大如錢。","白[雪]裝梅樹，青袍似葑田。"]', '["江南孟春天，荇葉大如錢。","白[雪]裝梅樹，青袍似葑田。"]', '诗', 'shi', '', NULL, '狀江南 孟春 鮑防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4a21fba-29eb-4fe6-a426-05ef19f72c13', '雜感', '杂感', '57965443-6045-4af4-ac2a-1120c1a4fb26', '唐', '["漢家海內承平久，萬國戎王皆稽首。","天馬常銜苜蓿花，胡人歲獻葡萄酒。","五月荔枝初破顏，朝離象郡夕函關。","鴈飛不到桂陽嶺，馬走先過林邑山。","甘泉御果垂仙閣，日暮無人香自落。","遠物皆重近皆輕，雞雖有德不如鶴。"]', '["漢家海內承平久，万国戎王皆稽首。","天马常銜苜蓿花，胡人歲獻葡萄酒。","五月荔枝初破顏，朝離象郡夕函关。","鴈飞不到桂陽嶺，马走先過林邑山。","甘泉御果垂仙閣，日暮無人香自落。","远物皆重近皆轻，雞雖有德不如鹤。"]', '诗', 'shi', '', NULL, '雜感 鮑防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3951b5a2-207b-4dfe-a5d8-1dee23c1ffde', '送薛補闕入朝', '送薛補闕入朝', '57965443-6045-4af4-ac2a-1120c1a4fb26', '唐', '["平原門下十餘人，獨受恩多未殺身。","每歎陸家兄弟少，更憐楊氏子孫貧。","柴門豈斷施行馬，魯酒那堪醉近臣。","賴有軍中遺令在，猶將談笑對風塵。"]', '["平原门下十餘人，独受恩多未殺身。","每歎陸家兄弟少，更怜楊氏子孫貧。","柴门豈斷施行马，魯酒那堪醉近臣。","賴有軍中遺令在，猶將談笑对风塵。"]', '诗', 'shi', '', NULL, '送薛補闕入朝 鮑防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6507a20e-2fa3-47d6-ad95-9fc4bde194d6', '人日陪宣州范中丞傳正與范侍御傳真宴東峰亭', '人日陪宣州范中丞傳正與范侍御傳真宴东峰亭', '57965443-6045-4af4-ac2a-1120c1a4fb26', '唐', '["人日春風綻早梅，謝家兄弟看花來。","吳姬對酒歌千曲，秦女留人酒百杯。","絲柳向空輕婉轉，玉山看日漸裴回。","流光易去懽難得，莫厭頻頻上此臺。"]', '["人日春风綻早梅，謝家兄弟看花来。","吳姬对酒歌千曲，秦女留人酒百杯。","絲柳向空轻婉轉，玉山看日漸裴回。","流光易去懽难得，莫厭頻頻上此台。"]', '诗', 'shi', '', NULL, '人日陪宣州范中丞傳正與范侍御傳真宴東峰亭 鮑防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76cc99b7-c628-4f69-9855-4ebfc338b15c', '上巳寄孟中丞', '上巳寄孟中丞', '57965443-6045-4af4-ac2a-1120c1a4fb26', '唐', '["世間禊事風流處，鏡裏雲山若畫屏。","今日會稽王內史，好將賓客醉蘭亭。"]', '["世间禊事风流处，镜裏云山若畫屏。","今日會稽王內史，好將賓客醉蘭亭。"]', '诗', 'shi', '', NULL, '上巳寄孟中丞 鮑防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e409fd6-6f44-40e3-82b0-3c0fb1f146ef', '秋暮憶中秋夜與王璠侍御賞月因愴遠離聊以奉寄', '秋暮憶中秋夜與王璠侍御賞月因愴远離聊以奉寄', '57965443-6045-4af4-ac2a-1120c1a4fb26', '唐', '["前月月明夜，美人同遠光。","清塵一以間，今夕坐相忘。","風落芙蓉露，疑餘繡被香。"]', '["前月月明夜，美人同远光。","清塵一以间，今夕坐相忘。","风落芙蓉露，疑餘繡被香。"]', '诗', 'shi', '', NULL, '秋暮憶中秋夜與王璠侍御賞月因愴遠離聊以奉寄 鮑防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bf33f8b-b4a5-4cf1-8140-ddbb47cd1fed', '元日早朝行', '元日早朝行', '57965443-6045-4af4-ac2a-1120c1a4fb26', '唐', '["乾元發生春爲宗，盛德在木斗建東。","東方歲星大明宮，南山喜氣搖晴空。","望雲五等舞萬玉，獻壽一聲出千峰。","文昌隨彩禮樂正，太平下直旌旗紅。","師曠應律調黃鍾，王良運策調時龍。","玄冥無事歸朔土，青帝放身入朱宮。","九韶九變五聲裏，四方四友一身中。","天何言哉樂無窮，廣成彭祖爲三公。","野臣潛隨擊壤老，日下鼓腹歌可封。"]', '["乾元發生春爲宗，盛德在木斗建东。","东方歲星大明宮，南山喜氣搖晴空。","望云五等舞万玉，獻壽一声出千峰。","文昌隨彩禮乐正，太平下直旌旗紅。","師曠應律調黄鍾，王良運策調时龙。","玄冥無事归朔土，青帝放身入朱宮。","九韶九变五声裏，四方四友一身中。","天何言哉乐無窮，廣成彭祖爲三公。","野臣潛隨擊壤老，日下鼓腹歌可封。"]', '诗', 'shi', '', NULL, '元日早朝行 鮑防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fff3942-620d-4197-a5aa-6693fc7a573d', '憶長安 三月', '憶长安 三月', 'd0c20802-8c76-408b-9dec-8ed884b6f1d1', '唐', '["憶長安，三月時，上苑遍是花枝。","青門幾場送客，曲水竟日題詩。","駿馬金鞭無數，良辰美景追隨。"]', '["憶长安，三月时，上苑遍是花枝。","青门幾場送客，曲水竟日題诗。","駿马金鞭無數，良辰美景追隨。"]', '诗', 'shi', '', NULL, '憶長安 三月 杜奕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d3374bc-daa8-4ca0-a0f0-38137a7ea593', '憶長安 六月', '憶长安 六月', '01789b2f-bb92-43f6-8eb3-3d4ae7ce213d', '唐', '["憶長安，六月時，風臺水榭逶迤。","朱果雕籠香透，分明紫禁寒隨。","塵驚九衢客散，赭珂滴瀝青驪。"]', '["憶长安，六月时，风台水榭逶迤。","朱果雕籠香透，分明紫禁寒隨。","塵驚九衢客散，赭珂滴瀝青驪。"]', '诗', 'shi', '', NULL, '憶長安 六月 鄭概 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c0f48ee-13f1-4e4a-a763-effe08e90998', '狀江南 孟秋', '狀江南 孟秋', '01789b2f-bb92-43f6-8eb3-3d4ae7ce213d', '唐', '["江南孟秋天，稻花白如氈。","素腕慙新藕，殘妝妒晚蓮。"]', '["江南孟秋天，稻花白如氈。","素腕慙新藕，殘妝妒晚蓮。"]', '诗', 'shi', '', NULL, '狀江南 孟秋 鄭概 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c51ebd5d-f16d-4042-963f-b1ff984d8689', '憶長安 七月', '憶长安 七月', '3b7a37d5-4130-4e8f-a3b6-0f87b1419cc0', '唐', '["憶長安，七月時，槐花點散罘罳。","七夕針樓競出，中元香供初移。","繡轂金鞍無限，遊人處處歸遲。"]', '["憶长安，七月时，槐花点散罘罳。","七夕針楼競出，中元香供初移。","繡轂金鞍無限，游人处处归遲。"]', '诗', 'shi', '', NULL, '憶長安 七月 陳元初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8504f827-22c0-467b-9a22-a8650192fa63', '憶長安 八月', '憶长安 八月', '30170c73-1639-4a9e-80ea-cae9c2d06db2', '唐', '["憶長安，八月時，闕下天高舊儀。","衣冠共頒金鏡，犀象對舞丹墀。","更愛終南灞上，可憐秋草碧滋。"]', '["憶长安，八月时，闕下天高旧儀。","衣冠共頒金镜，犀象对舞丹墀。","更愛終南灞上，可怜秋草碧滋。"]', '诗', 'shi', '', NULL, '憶長安 八月 呂渭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0031a2e1-8915-43dc-9dfc-eb641d55443d', '狀江南 仲冬', '狀江南 仲冬', '30170c73-1639-4a9e-80ea-cae9c2d06db2', '唐', '["江南仲冬天，紫蔗節如鞭。","海將鹽作雪，山用火耕田。"]', '["江南仲冬天，紫蔗節如鞭。","海將鹽作雪，山用火耕田。"]', '诗', 'shi', '', NULL, '狀江南 仲冬 呂渭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3723cad1-60e6-4700-a4fa-a147346c7bd9', '貞元十一年知貢舉撓閣不能定去留寄詩前主司', '貞元十一年知貢舉撓閣不能定去留寄诗前主司', '30170c73-1639-4a9e-80ea-cae9c2d06db2', '唐', '["獨坐貢闈裏，愁多芳草生。","仙翁昨日事，應見此時情。"]', '["独坐貢闈裏，愁多芳草生。","仙翁昨日事，應见此时情。"]', '诗', 'shi', '', NULL, '貞元十一年知貢舉撓閣不能定去留寄詩前主司 呂渭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3c9d99b-f48a-44fa-9e0d-4034c3c4c0f6', '皇帝移晦日爲中和節', '皇帝移晦日爲中和節', '30170c73-1639-4a9e-80ea-cae9c2d06db2', '唐', '["皇心不向晦，改節號中和。","淑氣同風景，嘉名別詠歌。","湔裙移舊俗，賜尺下新科。","曆象千年正，酺醵四海多。","花隨春令發，鴻度歲陽過。","天地齊休慶，歡聲欲盪波。"]', '["皇心不向晦，改節號中和。","淑氣同风景，嘉名別詠歌。","湔裙移旧俗，賜尺下新科。","曆象千年正，酺醵四海多。","花隨春令發，鴻度歲陽過。","天地齊休慶，歡声欲盪波。"]', '诗', 'shi', '', NULL, '皇帝移晦日爲中和節 呂渭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6417fb43-b5ae-40c9-8ab4-e743e85a7ea1', '經湛長史草堂', '經湛长史草堂', '30170c73-1639-4a9e-80ea-cae9c2d06db2', '唐', '["巖居舊風景，人世今成昔。","木落古山空，猨啼秋月白。","誰同西府僚，幾謝南平客。","摧殘松桂老，蕭散煙雲夕。","跡留異代遠，境入空門寂。","惟有草堂僧，陳詩在石壁。"]', '["巖居旧风景，人世今成昔。","木落古山空，猨啼秋月白。","誰同西府僚，幾謝南平客。","摧殘松桂老，蕭散煙云夕。","跡留異代远，境入空门寂。","惟有草堂僧，陳诗在石壁。"]', '诗', 'shi', '', NULL, '經湛長史草堂 呂渭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eef69c91-a8a9-47fb-9bb6-d6f2aba3c387', '憶長安 九月', '憶长安 九月', '5f46614d-e170-489c-a192-09dbd3c6d8dd', '唐', '["憶長安，九月時，登高望見昆池。","上苑初開露菊，芳林正獻霜梨。","更想千門萬戶，[月]明砧杵參差。"]', '["憶长安，九月时，登高望见昆池。","上苑初开露菊，芳林正獻霜梨。","更想千门万戶，[月]明砧杵參差。"]', '诗', 'shi', '', NULL, '憶長安 九月 范燈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40e4f634-6e6b-4df8-a9d4-f3a52233b7a0', '狀江南 季夏', '狀江南 季夏', '5f46614d-e170-489c-a192-09dbd3c6d8dd', '唐', '["江南季夏天，身熱汗如泉。","蚊蚋成雷澤，袈裟作水田。"]', '["江南季夏天，身熱汗如泉。","蚊蚋成雷澤，袈裟作水田。"]', '诗', 'shi', '', NULL, '狀江南 季夏 范燈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a38ce26-2b37-4151-888b-3b7f78acafcb', '憶長安 十月', '憶长安 十月', '39338cb7-69e3-4642-ba89-f4550282ac26', '唐', '["憶長安，十月時，華清士馬相馳。","萬國來朝漢闕，五陵共獵秦祠。","晝夜歌鐘不歇，山河四塞京師。"]', '["憶长安，十月时，华清士马相驰。","万国来朝漢闕，五陵共獵秦祠。","晝夜歌鐘不歇，山河四塞京師。"]', '诗', 'shi', '', NULL, '憶長安 十月 樊珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86660317-2190-484f-86b1-c8b429cadbdb', '狀江南 仲夏', '狀江南 仲夏', '39338cb7-69e3-4642-ba89-f4550282ac26', '唐', '["江南仲夏天，時雨下如川。","盧橘垂金彈，甘蕉吐白蓮。"]', '["江南仲夏天，时雨下如川。","盧橘垂金彈，甘蕉吐白蓮。"]', '诗', 'shi', '', NULL, '狀江南 仲夏 樊珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac63c877-c425-4d01-93f7-a718859a403f', '憶長安 十一月', '憶长安 十一月', '7446de05-b5c2-42ac-aa18-2b07b1d65928', '唐', '["憶長安，子月時，千官賀至丹墀。","御苑雪開瓊樹，龍堂冰作瑤池。","獸炭氈爐正好，貂裘狐白相宜。"]', '["憶长安，子月时，千官賀至丹墀。","御苑雪开瓊樹，龙堂冰作瑤池。","獸炭氈爐正好，貂裘狐白相宜。"]', '诗', 'shi', '', NULL, '憶長安 十一月 劉蕃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('962103e4-47c6-462a-801b-cd981024217b', '狀江南 季秋', '狀江南 季秋', '7446de05-b5c2-42ac-aa18-2b07b1d65928', '唐', '["江南季秋天，栗熟大如拳。","楓葉紅霞舉，蒼蘆白浪川。"]', '["江南季秋天，栗熟大如拳。","楓葉紅霞舉，蒼蘆白浪川。"]', '诗', 'shi', '', NULL, '狀江南 季秋 劉蕃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('541a9811-acd4-41b2-95b9-cf9a63e9e4e9', '太寥歌', '太寥歌', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["化元靈哉，碧虛清哉。","紅霞明哉，冥哉茫哉，惟化之工無彊哉。"]', '["化元靈哉，碧虛清哉。","紅霞明哉，冥哉茫哉，惟化之工無彊哉。"]', '诗', 'shi', '', NULL, '太寥歌 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('705adb8f-f174-4221-8bdb-a2efd0e16b68', '空洞歌', '空洞歌', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["無自而然，自然之元。","無造而化，造化之端。","廓然慤然，其形團圞。","反爾之視，絕爾之思，可以觀。"]', '["無自而然，自然之元。","無造而化，造化之端。","廓然慤然，其形團圞。","反爾之視，絕爾之思，可以观。"]', '诗', 'shi', '', NULL, '空洞歌 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c7f80dd-29e4-4c72-b4b5-f967aa52b51a', '漁父歌 一', '漁父歌 一', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["西塞山前白鷺飛，桃花流水鱖魚肥。","青篛笠，綠簑衣，斜風細雨不須歸。"]', '["西塞山前白鷺飞，桃花流水鱖鱼肥。","青篛笠，綠簑衣，斜风細雨不須归。"]', '诗', 'shi', '', NULL, '漁父歌 一 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8f030b1-9e72-4243-92b3-3c4ec8028354', '漁父歌 二', '漁父歌 二', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["釣臺漁父褐爲裘，兩兩三三舴艋舟。","能縱櫂，慣乘流，長江白浪不曾憂。"]', '["釣台漁父褐爲裘，兩兩三三舴艋舟。","能縱櫂，慣乘流，长江白浪不曾憂。"]', '诗', 'shi', '', NULL, '漁父歌 二 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e99fd87-77f9-42d7-af47-1a845e2e865d', '漁父歌 三', '漁父歌 三', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["霅谿灣裏釣漁翁，舴艋爲家西復東。","江上雪，浦邊風，笑著荷衣不歎窮。"]', '["霅谿灣裏釣漁翁，舴艋爲家西复东。","江上雪，浦邊风，笑著荷衣不歎窮。"]', '诗', 'shi', '', NULL, '漁父歌 三 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29005e2b-3311-40df-a3b8-5ff8455bc4af', '漁父歌 四', '漁父歌 四', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["松江蟹舍主人歡，菰飯蓴羹亦共餐。","楓葉落，荻花乾，醉宿漁舟不覺寒。"]', '["松江蟹舍主人歡，菰飯蓴羹亦共餐。","楓葉落，荻花乾，醉宿漁舟不覺寒。"]', '诗', 'shi', '', NULL, '漁父歌 四 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdb3235d-6261-4b85-b5f5-53fc016942c3', '漁父歌 五', '漁父歌 五', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["青草湖中月正圓，巴陵漁父櫂歌連。","釣車子，橛頭船，樂在風波不用仙。"]', '["青草湖中月正圓，巴陵漁父櫂歌連。","釣车子，橛头船，乐在风波不用仙。"]', '诗', 'shi', '', NULL, '漁父歌 五 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58ed2f11-d26c-47bf-8daa-02eb522da5f1', '上巳日憶江南禊事', '上巳日憶江南禊事', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["黃河西繞郡城流，上巳應無祓禊遊。","爲憶淥江春水色，更隨宵夢向吳洲。"]', '["黄河西繞郡城流，上巳應無祓禊游。","爲憶淥江春水色，更隨宵梦向吳洲。"]', '诗', 'shi', '', NULL, '上巳日憶江南禊事 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d6eed96-a408-4c95-9d9a-fc1ba93675fc', '漁父', '漁父', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["八月九月蘆花飛，南谿老人垂釣歸。","秋山入簾翠滴滴，野艇倚檻雲依依。","却把漁竿尋小徑，閑梳鶴髮對斜暉。","翻嫌四皓曾多事，出爲儲皇定是非。"]', '["八月九月蘆花飞，南谿老人垂釣归。","秋山入簾翠滴滴，野艇倚檻云依依。","却把漁竿尋小徑，闲梳鹤髮对斜暉。","翻嫌四皓曾多事，出爲儲皇定是非。"]', '诗', 'shi', '', NULL, '漁父 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bb1ee39-265a-4c53-a5b4-311b2e65429c', '和荅弟志和漁父歌', '和荅弟志和漁父歌', '568ab229-a87e-425a-8e94-b305bf02d69d', '唐', '["樂是風波釣是閑，草堂松徑已勝攀。","太湖水，洞庭山，狂風浪起且須還。"]', '["乐是风波釣是闲，草堂松徑已勝攀。","太湖水，洞庭山，狂风浪起且須還。"]', '诗', 'shi', '', NULL, '和荅弟志和漁父歌 張松齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('392696d5-0270-4db7-9f78-a7a6dfc442fb', '歌', '歌', '6e5ca658-7b1b-4377-9ef0-2e0c9ddd41d8', '唐', '["不羨黃金罍，不羨白玉杯。","不羨朝入省，不羨暮入臺。","惟羨西江水，曾向金陵城下來。"]', '["不羨黄金罍，不羨白玉杯。","不羨朝入省，不羨暮入台。","惟羨西江水，曾向金陵城下来。"]', '诗', 'shi', '', NULL, '歌 陸羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7055ca5-213d-41d4-81f9-dba64d953e44', '會稽東小山', '會稽东小山', '6e5ca658-7b1b-4377-9ef0-2e0c9ddd41d8', '唐', '["月色寒潮入剡溪，青猨叫斷綠林西。","昔人已逐東流去，空見年年江草齊。"]', '["月色寒潮入剡溪，青猨叫斷綠林西。","昔人已逐东流去，空见年年江草齊。"]', '诗', 'shi', '', NULL, '會稽東小山 陸羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19812eab-6755-48b9-8c14-f44ce2d3ee14', '句', '句', '6e5ca658-7b1b-4377-9ef0-2e0c9ddd41d8', '唐', '["辟彊舊林間，怪石紛相向。","絕澗方險尋，亂巖亦危造。","瀉從千仞石，寄逐九江船。"]', '["辟彊旧林间，怪石紛相向。","絕澗方險尋，亂巖亦危造。","瀉從千仞石，寄逐九江船。"]', '诗', 'shi', '', NULL, '句 陸羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fadd4ab1-6b70-4a7b-b9b5-4190edae96e0', '寒食寄李補闕', '寒食寄李補闕', '0ba2baff-173f-4ce9-b534-bd4d70c0fee1', '唐', '["蘭陵士女滿晴川，郊外紛紛拜古埏。","萬井閭閻皆禁火，九原松柏自生煙。","人間後事悲前事，鏡裏今年老去年。","介子終知祿不及，王孫誰肯一相憐。"]', '["蘭陵士女满晴川，郊外紛紛拜古埏。","万井閭閻皆禁火，九原松柏自生煙。","人间後事悲前事，镜裏今年老去年。","介子終知祿不及，王孫誰肯一相怜。"]', '诗', 'shi', '', NULL, '寒食寄李補闕 郭鄖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12cdc618-7a5f-4cb3-9607-46025a48c467', '仲月賞花', '仲月賞花', '23e24d97-92bd-419c-8026-077c863530de', '唐', '["梅花似雪柳含煙，南地風光臘月前。","把酒且須拼却醉，風流何必待歌筵。"]', '["梅花似雪柳含煙，南地风光臘月前。","把酒且須拼却醉，风流何必待歌筵。"]', '诗', 'shi', '', NULL, '仲月賞花 韋同則 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff30dedd-92e7-47eb-8241-751240f036fc', '西亭暇日書懷十二韻獻上相公', '西亭暇日书懷十二韻獻上相公', '33d0e93c-d6b3-4e17-a62b-156bf2d8417b', '唐', '["勝賞不在遠，憮然念玄搜。","茲亭有殊致，經始富人侯。","澄澹分沼沚，縈迴間林丘。","荷香奪芳麝，石溜當鳴球。","撫俗來康濟，經邦去咨謀。","寬明洽時論，惠愛聞甿謳。","代斵豈容易，守成獲優游。","文翁舊學校，子產昔田疇。","琬琰富佳什，池臺想舊遊。","誰言矜改作，曾是日增修。","憲省忝陪屬，岷峨嗣徽猷。","提攜當有路，勿使滯刀州。"]', '["勝賞不在远，憮然念玄搜。","茲亭有殊致，經始富人侯。","澄澹分沼沚，縈迴间林丘。","荷香奪芳麝，石溜當鳴球。","撫俗来康濟，經邦去咨謀。","寬明洽时論，惠愛闻甿謳。","代斵豈容易，守成獲優游。","文翁旧学校，子產昔田疇。","琬琰富佳什，池台想旧游。","誰言矜改作，曾是日增修。","憲省忝陪屬，岷峨嗣徽猷。","提携當有路，勿使滯刀州。"]', '诗', 'shi', '', NULL, '西亭暇日書懷十二韻獻上相公 李夷簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43c2e197-20d6-4ed6-bef0-972b05d1dd41', '城南訪裴氏昆季', '城南訪裴氏昆季', '5482c330-a2bc-43e7-829b-2bdd17a56fdb', '唐', '["相思起中夜，夙駕訪柴荆。","早霧桑柘隱，曉光溪澗明。","村蹊嵩棘間，往往斷新耕。","貧野煙火微，晝無烏鳶聲。","田頭逢餉人，道君南山行。","南山千里峰，盡是相思情。","野老無拜揖，村童多躶形。","相呼看車馬，顏色喜相驚。","荒圃雞豚樂，雨牆禾莠生。","欲君知我來，壁上空書名。"]', '["相思起中夜，夙駕訪柴荆。","早霧桑柘隐，晓光溪澗明。","村蹊嵩棘间，往往斷新耕。","貧野煙火微，晝無烏鳶声。","田头逢餉人，道君南山行。","南山千里峰，尽是相思情。","野老無拜揖，村童多躶形。","相呼看车马，顏色喜相驚。","荒圃雞豚乐，雨牆禾莠生。","欲君知我来，壁上空书名。"]', '诗', 'shi', '', NULL, '城南訪裴氏昆季 李約 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64a346ea-e5ce-4b81-bd99-06ad50239f5b', '歲日感懷', '歲日感懷', '5482c330-a2bc-43e7-829b-2bdd17a56fdb', '唐', '["曙氣變東風，蟾壺夜漏窮。","新春幾人老，舊曆四時空。","身賤悲添歲，家貧喜過冬。","稱觴惟有感，歡慶在兒童。"]', '["曙氣变东风，蟾壺夜漏窮。","新春幾人老，旧曆四时空。","身賤悲添歲，家貧喜過冬。","稱觴惟有感，歡慶在兒童。"]', '诗', 'shi', '', NULL, '歲日感懷 李約 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eec52107-44eb-48eb-a47d-7f34277bea28', '從軍行三首 一', '從軍行三首 一', '5482c330-a2bc-43e7-829b-2bdd17a56fdb', '唐', '["看圖閑敎陣，畫地靜論邊。","烏壘天西戍，鷹姿塞上川。","路長唯算月，書遠每題年。","無復生還望，翻思未別前。"]', '["看圖闲敎陣，畫地静論邊。","烏壘天西戍，鷹姿塞上川。","路长唯算月，书远每題年。","無复生還望，翻思未別前。"]', '诗', 'shi', '', NULL, '從軍行三首 一 李約 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d400b97d-e36d-48a5-98c2-33db274c5ddd', '從軍行三首 二', '從軍行三首 二', '5482c330-a2bc-43e7-829b-2bdd17a56fdb', '唐', '["柵壕三面鬬，箭盡舉烽頻。","營柳和煙暮，關榆帶雪春。","邊城多老將，磧路少歸人。","殺盡金河卒，年年添塞塵。"]', '["柵壕三面鬬，箭尽舉烽頻。","營柳和煙暮，关榆带雪春。","邊城多老將，磧路少归人。","殺尽金河卒，年年添塞塵。"]', '诗', 'shi', '', NULL, '從軍行三首 二 李約 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4557894f-a024-44af-936c-f758cac66b46', '從軍行三首 三', '從軍行三首 三', '5482c330-a2bc-43e7-829b-2bdd17a56fdb', '唐', '["候火起雕城，塵沙擁戰聲。","遊軍藏漢幟，降騎說蕃情。","霜落滹沱淺，秋深太白明。","嫖姚方虎視，不覺說添兵。"]', '["候火起雕城，塵沙擁戰声。","游軍藏漢幟，降騎说蕃情。","霜落滹沱淺，秋深太白明。","嫖姚方虎視，不覺说添兵。"]', '诗', 'shi', '', NULL, '從軍行三首 三 李約 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbc4bedf-3a8a-4405-a241-2f4257a1cc08', '贈韋況', '贈韋況', '5482c330-a2bc-43e7-829b-2bdd17a56fdb', '唐', '["我有心中事，不與韋三說。","秋夜洛陽城，明月照張八。"]', '["我有心中事，不與韋三说。","秋夜洛陽城，明月照張八。"]', '诗', 'shi', '', NULL, '贈韋況 李約 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16e63d97-a2df-4388-ae70-66e0deb0ab91', '觀祈雨', '观祈雨', '5482c330-a2bc-43e7-829b-2bdd17a56fdb', '唐', '["桑條無葉土生煙，簫管迎龍水廟前。","朱門幾處看歌舞，猶恐春陰咽管弦。"]', '["桑條無葉土生煙，簫管迎龙水廟前。","朱门幾处看歌舞，猶恐春陰咽管弦。"]', '诗', 'shi', '', NULL, '觀祈雨 李約 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68e248c2-7de3-4f95-8f78-aef6c5e3d5a5', '江南春', '江南春', '5482c330-a2bc-43e7-829b-2bdd17a56fdb', '唐', '["池塘春暖水紋開，堤柳垂絲間野梅。","江上年年芳意早，蓬瀛春色逐潮來。"]', '["池塘春暖水紋开，堤柳垂絲间野梅。","江上年年芳意早，蓬瀛春色逐潮来。"]', '诗', 'shi', '', NULL, '江南春 李約 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d90c99e0-b50a-48e1-8331-e1539d86ceab', '過華清宮', '過华清宮', '5482c330-a2bc-43e7-829b-2bdd17a56fdb', '唐', '["君王遊樂萬機輕，一曲霓裳四海兵。","玉輦升天人已盡，故宮猶有樹長生。"]', '["君王游乐万機轻，一曲霓裳四海兵。","玉輦升天人已尽，故宮猶有樹长生。"]', '诗', 'shi', '', NULL, '過華清宮 李約 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac059717-856b-4e9c-8ab8-af17dbcf47a3', '病中宿宜陽館聞雨', '病中宿宜陽館闻雨', '5482c330-a2bc-43e7-829b-2bdd17a56fdb', '唐', '["難眠夏夜抵秋賒，簾幔深垂窗燭斜。","風吹桐竹更無雨，白髮病人心到家。"]', '["难眠夏夜抵秋賒，簾幔深垂窗燭斜。","风吹桐竹更無雨，白髮病人心到家。"]', '诗', 'shi', '', NULL, '病中宿宜陽館聞雨 李約 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97546486-e401-4b60-9983-154f784155d3', '江南曲', '江南曲', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["偶向江邊採白蘋，還隨女伴賽江神。","衆中不敢分明語，暗擲金錢卜遠人。"]', '["偶向江邊採白蘋，還隨女伴賽江神。","衆中不敢分明語，暗擲金錢卜远人。"]', '诗', 'shi', '', NULL, '江南曲 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c0a394a-59fb-4008-9f92-bf6d247be4c6', '山中寄樊僕射', '山中寄樊僕射', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["却憶東溪日，同年事魯儒。","僧房閑共宿，酒肆醉相扶。","天畔雙旌貴，山中病客孤。","無謀還有計，春谷種桑榆。"]', '["却憶东溪日，同年事魯儒。","僧房闲共宿，酒肆醉相扶。","天畔雙旌貴，山中病客孤。","無謀還有計，春谷種桑榆。"]', '诗', 'shi', '', NULL, '山中寄樊僕射 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f485ea0-1ba6-4f56-9962-7ca4c3054745', '題宇文𧚞山寺讀書院', '題宇文𧚞山寺读书院', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["讀書林下寺，不出動經年。","草閣連僧院，山廚共石泉。","雲庭無履跡，龕壁有燈煙。","年少今頭白，刪詩到幾篇。"]', '["读书林下寺，不出动經年。","草閣連僧院，山廚共石泉。","云庭無履跡，龕壁有灯煙。","年少今头白，刪诗到幾篇。"]', '诗', 'shi', '', NULL, '題宇文𧚞山寺讀書院 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eac82df3-36cd-412c-8144-337ce181f63b', '贈蘭若僧', '贈蘭若僧', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["一身禪誦苦，灑掃古花宮。","靜室門常閉，深蘿月不通。","懸燈喬木上，鳴磬亂幡中。","附入高僧傳，長稱二遠公。"]', '["一身禪誦苦，灑掃古花宮。","静室门常閉，深蘿月不通。","懸灯喬木上，鳴磬亂幡中。","附入高僧傳，长稱二远公。"]', '诗', 'shi', '', NULL, '贈蘭若僧 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c09e987d-f376-467e-a435-326368f3eb13', '題鄰居', '題鄰居', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["僻巷鄰家少，茅簷喜竝居。","蒸梨常共竈，澆薤亦同渠。","傳屐朝尋藥，分燈夜讀書。","雖然在城市，還得似樵漁。"]', '["僻巷鄰家少，茅簷喜竝居。","蒸梨常共竈，澆薤亦同渠。","傳屐朝尋藥，分灯夜读书。","雖然在城市，還得似樵漁。"]', '诗', 'shi', '', NULL, '題鄰居 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec973ae2-f409-4701-8ae2-7cc2abb850b2', '山中自述', '山中自述', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["三十無名客，空山獨臥秋。","病多知藥性，年長信人愁。","螢影竹窗下，松聲茅屋頭。","近來心更靜，不夢世間遊。"]', '["三十無名客，空山独臥秋。","病多知藥性，年长信人愁。","螢影竹窗下，松声茅屋头。","近来心更静，不梦世间游。"]', '诗', 'shi', '', NULL, '山中自述 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e0a488f-bbd7-4558-852e-55314a431d5a', '山中寄韋鉦', '山中寄韋鉦', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["嬾成身病日，因醉臥多時。","送客出谿少，讀書終卷遲。","幽窗聞墜葉，晴景見遊絲。","早晚來收藥，門前有紫芝。"]', '["嬾成身病日，因醉臥多时。","送客出谿少，读书終卷遲。","幽窗闻墜葉，晴景见游絲。","早晚来收藥，门前有紫芝。"]', '诗', 'shi', '', NULL, '山中寄韋鉦 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4582417a-dd1a-46fd-aada-337888556a06', '南谿書齋', '南谿书斋', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["茅屋往來久，山深不置門。","草生垂井口，花落擁籬根。","入院將雛鳥，尋蘿抱子猿。","曾逢異人說，風景似桃源。"]', '["茅屋往来久，山深不置门。","草生垂井口，花落擁籬根。","入院將雛鸟，尋蘿抱子猿。","曾逢異人说，风景似桃源。"]', '诗', 'shi', '', NULL, '南谿書齋 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a9a0a42-3109-4d0a-bd07-d8557137e0a7', '夜會李太守宅', '夜會李太守宅', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["郡齋常夜埽，不臥獨吟詩。","把燭近幽客，升堂戴接䍦。","微風吹凍葉，餘雪落寒枝。","明日逢山伴，須令隱者知。"]', '["郡斋常夜埽，不臥独吟诗。","把燭近幽客，升堂戴接䍦。","微风吹凍葉，餘雪落寒枝。","明日逢山伴，須令隐者知。"]', '诗', 'shi', '', NULL, '夜會李太守宅 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d76b40cc-adeb-46a5-a7a9-174ef98e6af5', '題柏臺山僧', '題柏台山僧', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["上方唯一室，禪定對山容。","行道臨孤壁，持齋聽遠鐘。","枯藤離舊樹，朽石落高峰。","不向雲間見，還應夢裏逢。"]', '["上方唯一室，禪定对山容。","行道臨孤壁，持斋听远鐘。","枯藤離旧樹，朽石落高峰。","不向云间见，還應梦裏逢。"]', '诗', 'shi', '', NULL, '題柏臺山僧 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9747409-7db3-4600-8a85-90465a503b29', '寄續尊師', '寄續尊師', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["得道任髮白，亦逢城市遊。","新經天上取，稀藥洞中收。","春木帶枯葉，新蒲生漫流。","年年望靈鶴，常在此山頭。"]', '["得道任髮白，亦逢城市游。","新經天上取，稀藥洞中收。","春木带枯葉，新蒲生漫流。","年年望靈鹤，常在此山头。"]', '诗', 'shi', '', NULL, '寄續尊師 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20a02018-3e6e-41df-bb28-6b901e047213', '題南峰褚道士', '題南峰褚道士', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["得道南山久，曾敎四皓碁。","閉門醫病鶴，倒篋養神龜。","松際風長在，泉中草不衰。","誰知茅屋裏，有路向峨嵋。"]', '["得道南山久，曾敎四皓碁。","閉门醫病鹤，倒篋養神龟。","松際风长在，泉中草不衰。","誰知茅屋裏，有路向峨嵋。"]', '诗', 'shi', '', NULL, '題南峰褚道士 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e31b486-7ec0-4af4-b137-4df1262b2b57', '贈不食姑', '贈不食姑', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["不食非關藥，天生是女仙。","見人還起拜，留伴亦開田。","無窟尋溪宿，兼衣掃葉眠。","不知何代女，猶帶剪刀錢。"]', '["不食非关藥，天生是女仙。","见人還起拜，留伴亦开田。","無窟尋溪宿，兼衣掃葉眠。","不知何代女，猶带剪刀錢。"]', '诗', 'shi', '', NULL, '贈不食姑 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8bc9e50-ee3c-4874-8081-f27d69cf217d', '送李明府歸別業', '送李明府归別業', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["寄家丹水邊，歸去種春田。","白髮無知己，空山又一年。","鹿裘長酒氣，茅屋有茶煙。","亦擬辭人世，何溪有瀑泉。"]', '["寄家丹水邊，归去種春田。","白髮無知己，空山又一年。","鹿裘长酒氣，茅屋有茶煙。","亦擬辞人世，何溪有瀑泉。"]', '诗', 'shi', '', NULL, '送李明府歸別業 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('821b3cad-6a18-4404-b54a-b105e4d89faa', '題樹下禪師', '題樹下禪師', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["久行多不定，樹下是禪牀。","寂寂心無住，年年日自長。","蟲虵同宿磵，草木共經霜。","已見南人說，天台有舊房。"]', '["久行多不定，樹下是禪牀。","寂寂心無住，年年日自长。","蟲虵同宿磵，草木共經霜。","已见南人说，天台有旧房。"]', '诗', 'shi', '', NULL, '題樹下禪師 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed50304d-9bf0-4f49-bde3-05efe0c27752', '宿王尊師隱居', '宿王尊師隐居', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["夜愛雲林好，寒天月裏行。","青牛眠樹影，白犬吠猨聲。","一磬山院靜，千燈谿路明。","從來此峰客，幾箇得長生。"]', '["夜愛云林好，寒天月裏行。","青牛眠樹影，白犬吠猨声。","一磬山院静，千灯谿路明。","從来此峰客，幾箇得长生。"]', '诗', 'shi', '', NULL, '宿王尊師隱居 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58156c74-4d4c-4371-9ad5-381c3fb80bc8', '題服柏先生', '題服柏先生', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["服柏不飛鍊，閑眠閉草堂。","有泉唯盥漱，留火爲焚香。","新雨閑門靜，孤松滿院涼。","仍聞枕中術，曾授漢淮王。"]', '["服柏不飞鍊，闲眠閉草堂。","有泉唯盥漱，留火爲焚香。","新雨闲门静，孤松满院涼。","仍闻枕中術，曾授漢淮王。"]', '诗', 'shi', '', NULL, '題服柏先生 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47454354-f2b9-4e03-8a7b-d649ec119bf1', '哭凌霄山光上人', '哭凌霄山光上人', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["身沒碧峰裏，門人改葬期。","買山尋主遠，壘塔化人遲。","鬼火穿空院，秋螢入素帷。","黃昏溪路上，聞哭竺乾師。"]', '["身沒碧峰裏，门人改葬期。","買山尋主远，壘塔化人遲。","鬼火穿空院，秋螢入素帷。","黄昏溪路上，闻哭竺乾師。"]', '诗', 'shi', '', NULL, '哭凌霄山光上人 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51af5465-00b8-4607-ae23-330377379608', '途中寄楊涉', '途中寄楊涉', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["蕭蕭蘆荻晚，一逕入荒陂。","日色雲收處，蛙聲雨歇時。","前村見來久，羸馬自行遲。","聞作王門客，應閑白接䍦。"]', '["蕭蕭蘆荻晚，一逕入荒陂。","日色云收处，蛙声雨歇时。","前村见来久，羸马自行遲。","闻作王门客，應闲白接䍦。"]', '诗', 'shi', '', NULL, '途中寄楊涉 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1efbe2fa-7b61-4bb7-b74c-180e2dc76acb', '送韋判官歸薊門', '送韋判官归薊门', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["桑乾歸路遠，聞說亦愁人。","有雪常經夏，無花空到春。","下營雲外火，收馬月中塵。","白首從戎客，青衫未離身。"]', '["桑乾归路远，闻说亦愁人。","有雪常經夏，無花空到春。","下營云外火，收马月中塵。","白首從戎客，青衫未離身。"]', '诗', 'shi', '', NULL, '送韋判官歸薊門 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b23be228-4d1f-4ef9-aef5-c069a1d5b803', '出塞 一', '出塞 一', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["葱嶺秋塵起，全軍取月支。","山川引行陣，蕃漢列旌旗。","轉戰疲兵少，孤城外救遲。","邊人逢聖代，不見偃戈時。"]', '["葱嶺秋塵起，全軍取月支。","山川引行陣，蕃漢列旌旗。","轉戰疲兵少，孤城外救遲。","邊人逢聖代，不见偃戈时。"]', '诗', 'shi', '', NULL, '出塞 一 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ee270d5-6ce9-4e1c-8ede-f71467d88dc9', '出塞 二', '出塞 二', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["微雪軍將出，吹笳天未明。","觀兵登古戍，斬將對雙旌。","分陣瞻山勢，潛兵制馬鳴。","如今青史上，已有滅胡名。"]', '["微雪軍將出，吹笳天未明。","观兵登古戍，斬將对雙旌。","分陣瞻山勢，潛兵制马鳴。","如今青史上，已有滅胡名。"]', '诗', 'shi', '', NULL, '出塞 二 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffb4a57d-fbd9-4210-82e9-070e0dfd80a4', '出塞 三', '出塞 三', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["單于驕愛獵，放火到軍城。","乘月調新馬，防秋置遠營。","空山朱戟影，寒磧鐵衣聲。","度水逢胡說，沙陰有伏兵。"]', '["單于驕愛獵，放火到軍城。","乘月調新马，防秋置远營。","空山朱戟影，寒磧鐵衣声。","度水逢胡说，沙陰有伏兵。"]', '诗', 'shi', '', NULL, '出塞 三 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e658815-27ab-41bd-aa91-6d649f3f5486', '贈李太守', '贈李太守', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["幾年爲郡守，家似布衣貧。","沽酒迎幽客，無金與近臣。","擣茶書院靜，講易藥堂春。","歸闕功成後，隨車有野人。"]', '["幾年爲郡守，家似布衣貧。","沽酒迎幽客，無金與近臣。","擣茶书院静，講易藥堂春。","归闕功成後，隨车有野人。"]', '诗', 'shi', '', NULL, '贈李太守 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f752d65-2fcf-4e77-88da-a63babf06e09', '送張司直入單于', '送張司直入單于', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["若過幷州北，誰人不憶家。","塞深無伴侶，路盡有平沙。","磧冷唯逢鴈，天春不見花。","莫隨征將意，垂老事輕車。"]', '["若過幷州北，誰人不憶家。","塞深無伴侶，路尽有平沙。","磧冷唯逢鴈，天春不见花。","莫隨征將意，垂老事轻车。"]', '诗', 'shi', '', NULL, '送張司直入單于 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3470ab57-356f-40ef-9733-762144efa971', '惜花', '惜花', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["夜來花欲盡，始惜兩三枝。","早起尋稀處，閑眠記落時。","蘂焦蜂自散，蔕折蝶還移。","攀著殷勤別，明年更有期。"]', '["夜来花欲尽，始惜兩三枝。","早起尋稀处，闲眠記落时。","蘂焦蜂自散，蔕折蝶還移。","攀著殷勤別，明年更有期。"]', '诗', 'shi', '', NULL, '惜花 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cc0d574-4d92-4b42-a70a-63f0f151d7cc', '春山居', '春山居', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["獨來多任性，唯與白雲期。","深處花開盡，遲眠人不知。","水流山暗處，風起月明時。","望見南峰近，年年嬾更移。"]', '["独来多任性，唯與白云期。","深处花开尽，遲眠人不知。","水流山暗处，风起月明时。","望见南峰近，年年嬾更移。"]', '诗', 'shi', '', NULL, '春山居 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5737ad7a-143d-4e8e-8e15-f1b7c4a7edd3', '遊瀑泉寺', '游瀑泉寺', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["日夕尋未遍，古木寺高低。","粉壁猶遮嶺，朱樓尚隔溪。","廚窗通澗鼠，殿跡立山雞。","更有無人處，明朝獨向西。"]', '["日夕尋未遍，古木寺高低。","粉壁猶遮嶺，朱楼尚隔溪。","廚窗通澗鼠，殿跡立山雞。","更有無人处，明朝独向西。"]', '诗', 'shi', '', NULL, '遊瀑泉寺 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07fbdc14-3490-43de-a1b3-4491731dbf3f', '送宮人入道歸山', '送宮人入道归山', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["十歲吹蕭入漢宮，看修水殿種芙蓉。","自傷白髮辭金屋，許著黃衣向玉峰。","解語老猨開曉戶，學飛雛鶴落高松。","定知別後宮中伴，應聽緱山半夜鐘。"]', '["十歲吹蕭入漢宮，看修水殿種芙蓉。","自傷白髮辞金屋，許著黄衣向玉峰。","解語老猨开晓戶，学飞雛鹤落高松。","定知別後宮中伴，應听緱山半夜鐘。"]', '诗', 'shi', '', NULL, '送宮人入道歸山 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5258bf0f-f67e-46ce-a99b-29526dcf4838', '巴女謠', '巴女謠', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["巴女騎牛唱竹枝，藕絲菱葉傍江時。","不愁日暮還家錯，記得芭蕉出槿籬。"]', '["巴女騎牛唱竹枝，藕絲菱葉傍江时。","不愁日暮還家錯，記得芭蕉出槿籬。"]', '诗', 'shi', '', NULL, '巴女謠 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c32d6c2c-b8d6-437d-89da-13d726e2f515', '公子行', '公子行', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["少年初拜大長秋，半醉垂鞭見列侯。","馬上抱雞三市鬬，袖中攜劒五陵遊。","玉簫金管迎歸院，錦袖紅妝擁上樓。","更向院西新買宅，月波春水入門流。"]', '["少年初拜大长秋，半醉垂鞭见列侯。","马上抱雞三市鬬，袖中携劒五陵游。","玉簫金管迎归院，錦袖紅妝擁上楼。","更向院西新買宅，月波春水入门流。"]', '诗', 'shi', '', NULL, '公子行 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d1c6fe2-f28e-4774-87ee-6c3cd7e3b663', '長安遊', '长安游', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["久臥長安春復秋，五侯長樂客長愁。","繡簾朱轂逢花住，錦幨銀珂觸雨遊。","何處少年吹玉笛，誰家鸚鵡語紅樓。","年年只是看他貴，不及南山任白頭。"]', '["久臥长安春复秋，五侯长乐客长愁。","繡簾朱轂逢花住，錦幨銀珂觸雨游。","何处少年吹玉笛，誰家鸚鵡語紅楼。","年年只是看他貴，不及南山任白头。"]', '诗', 'shi', '', NULL, '長安遊 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5be46944-35d5-4ca6-8e69-e5eeee29c452', '別齊太守', '別齊太守', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["花裏南樓春夜寒，還如王屋上天壇。","歸山不道無明月，誰共相從到曉看。"]', '["花裏南楼春夜寒，還如王屋上天壇。","归山不道無明月，誰共相從到晓看。"]', '诗', 'shi', '', NULL, '別齊太守 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('774f87d0-bbf3-41cf-a07e-98bea4945cd7', '登古城', '登古城', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["獨上閑城却下遲，秋山慘慘塚纍纍。","當時還有登城者，荒草如今知是誰。"]', '["独上闲城却下遲，秋山慘慘塚纍纍。","當时還有登城者，荒草如今知是誰。"]', '诗', 'shi', '', NULL, '登古城 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d8b0386-c539-45d8-8d63-f7d90c74f21c', '哭劉夫子', '哭劉夫子', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["近問南州客，云亡已數春。","痛心曾受業，追服恨無親。","孀婦歸鄉里，書齋屬四鄰。","不知經亂後，奠祭有何人。"]', '["近问南州客，云亡已數春。","痛心曾受業，追服恨無親。","孀婦归乡里，书斋屬四鄰。","不知經亂後，奠祭有何人。"]', '诗', 'shi', '', NULL, '哭劉夫子 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('958ab75b-c1ae-4606-b911-9e5cd490b03f', '醉後寄山中友人', '醉後寄山中友人', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["昨日山家春酒濃，野人相勸久從容。","獨憶卸冠眠細草，不知誰送出深松。","都忘醉後逢廉度，不省歸時見魯恭。","知己尚嫌身酩酊，路人應恐笑龍鍾。"]', '["昨日山家春酒濃，野人相勸久從容。","独憶卸冠眠細草，不知誰送出深松。","都忘醉後逢廉度，不省归时见魯恭。","知己尚嫌身酩酊，路人應恐笑龙鍾。"]', '诗', 'shi', '', NULL, '醉後寄山中友人 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d934ecd5-00ef-4665-bfd6-d3f5a9d9b933', '溫泉僧房', '溫泉僧房', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["雲裏前朝寺，修行獨幾年。","山村無施食，盥漱亦安禪。","古塔巢溪鳥，深房閉谷泉。","自言曾入室，知處梵王天。"]', '["云裏前朝寺，修行独幾年。","山村無施食，盥漱亦安禪。","古塔巢溪鸟，深房閉谷泉。","自言曾入室，知处梵王天。"]', '诗', 'shi', '', NULL, '溫泉僧房 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c67b136a-b391-4fcd-97d7-c27910856d79', '題美人', '題美人', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["秦女窺人不解羞，攀花趁蝶出牆頭。","胸前空帶宜男草，嫁得蕭郎愛遠遊。"]', '["秦女窺人不解羞，攀花趁蝶出牆头。","胸前空带宜男草，嫁得蕭郎愛远游。"]', '诗', 'shi', '', NULL, '題美人 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f556f19-fc2b-435a-82fd-183f9c6c0915', '尋李暹', '尋李暹', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["任性常多出，人來得見稀。","市樓逢酒住，野寺送僧歸。","簷下懸秋葉，籬頭曬褐衣。","門前南北路，誰肯入柴扉。"]', '["任性常多出，人来得见稀。","市楼逢酒住，野寺送僧归。","簷下懸秋葉，籬头曬褐衣。","门前南北路，誰肯入柴扉。"]', '诗', 'shi', '', NULL, '尋李暹 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5d5e816-974b-4ae6-8240-5392678b7781', '尋李逸人舊居', '尋李逸人旧居', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["舊隱松林下，衝泉入兩涯。","琴書隨弟子，雞犬在鄰家。","茅屋長黃菌，槿籬生白花。","幽墳無處訪，恐是入煙霞。"]', '["旧隐松林下，衝泉入兩涯。","琴书隨弟子，雞犬在鄰家。","茅屋长黄菌，槿籬生白花。","幽墳無处訪，恐是入煙霞。"]', '诗', 'shi', '', NULL, '尋李逸人舊居 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73786f95-e483-46bf-9f63-ca78bb9e5204', '贈碧玉', '贈碧玉', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["新繡籠裙荳蔲花，路人笑上返金車。","霓裳禁曲無人解，暗問梨園弟子家。"]', '["新繡籠裙荳蔲花，路人笑上返金车。","霓裳禁曲無人解，暗问梨园弟子家。"]', '诗', 'shi', '', NULL, '贈碧玉 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70858ddb-decc-4fc1-a372-a41879131d4d', '舟中月明夜聞笛', '舟中月明夜闻笛', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["浦裏移舟候信風，蘆花漠漠夜江空。","更深何處人吹笛，疑是孤吟寒水中。"]', '["浦裏移舟候信风，蘆花漠漠夜江空。","更深何处人吹笛，疑是孤吟寒水中。"]', '诗', 'shi', '', NULL, '舟中月明夜聞笛 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a715dbe1-8a5c-4249-ab03-b27132d62c26', '送遷客二首 一', '送遷客二首 一', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["得罪誰人送，來時不到家。","白頭無侍子，多病向天涯。","莽蒼凌江水，黃昏見塞花。","如今賈誼賦，不漫說長沙。"]', '["得罪誰人送，来时不到家。","白头無侍子，多病向天涯。","莽蒼凌江水，黄昏见塞花。","如今賈誼賦，不漫说长沙。"]', '诗', 'shi', '', NULL, '送遷客二首 一 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b443cd1f-e94c-43e6-95ae-b9351215fc8f', '送遷客二首 二', '送遷客二首 二', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["流人何處去，萬里向江州。","孤驛瘴煙重，行人巴草秋。","上帆南去遠，送鴈北看愁。","遍問炎方客，無人得白頭。"]', '["流人何处去，万里向江州。","孤驛瘴煙重，行人巴草秋。","上帆南去远，送鴈北看愁。","遍问炎方客，無人得白头。"]', '诗', 'shi', '', NULL, '送遷客二首 二 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f26cc1ff-5b47-44f7-b827-68077bbf1bb5', '贈王道者', '贈王道者', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["去尋長不出，門似絕人行。","牀下石苔滿，屋頭秋草生。","學琴寒月短，寫易晚窗明。","唯到黃昏後，溪中聞磬聲。"]', '["去尋长不出，门似絕人行。","牀下石苔满，屋头秋草生。","学琴寒月短，寫易晚窗明。","唯到黄昏後，溪中闻磬声。"]', '诗', 'shi', '', NULL, '贈王道者 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebebbb5c-e0bc-46d5-9392-61411c2e3ea2', '題合溪乾洞', '題合溪乾洞', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["渡水傍山尋絕壁，白雲飛處洞天開。","仙人來往行無跡，石徑春風長綠苔。"]', '["渡水傍山尋絕壁，白云飞处洞天开。","仙人来往行無跡，石徑春风长綠苔。"]', '诗', 'shi', '', NULL, '題合溪乾洞 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afea0c4a-9144-4c79-b212-a68c13b53d9b', '過張老園林', '過張老园林', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["身老無修飾，頭巾用白紗。","開門朝掃徑，輦水夜澆花。","藥氣聞深巷，桐陰到數家。","不愁還酒債，腰下有丹砂。"]', '["身老無修飾，头巾用白紗。","开门朝掃徑，輦水夜澆花。","藥氣闻深巷，桐陰到數家。","不愁還酒債，腰下有丹砂。"]', '诗', 'shi', '', NULL, '過張老園林 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aaf6380-d813-4330-9195-f4385b33fe1f', '寓意', '寓意', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["自小看花長不足，江邊尋得數株紅。","黃昏人散東風起，吹落誰家明月中。"]', '["自小看花长不足，江邊尋得數株紅。","黄昏人散东风起，吹落誰家明月中。"]', '诗', 'shi', '', NULL, '寓意 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dff667d-cef0-4f71-95bd-8151dd957335', '哭王都護', '哭王都護', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["老將明王識，臨終拜上公。","告哀鄉路遠，助葬戍城空。","素幔朱門裏，銘旌秋巷中。","史官如不濫，獨傳說英雄。"]', '["老將明王識，臨終拜上公。","告哀乡路远，助葬戍城空。","素幔朱门裏，銘旌秋巷中。","史官如不濫，独傳说英雄。"]', '诗', 'shi', '', NULL, '哭王都護 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cfb1ac1-3199-4d6c-a379-9977348129c6', '餞司農宋卿立太尉碑了還江東', '餞司農宋卿立太尉碑了還江东', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["追立新碑日，憐君苦一身。","遠移深澗石，助立故鄉人。","草色荒墳綠，松陰古殿春。","平生心已遂，歸去得垂綸。"]', '["追立新碑日，怜君苦一身。","远移深澗石，助立故乡人。","草色荒墳綠，松陰古殿春。","平生心已遂，归去得垂綸。"]', '诗', 'shi', '', NULL, '餞司農宋卿立太尉碑了還江東 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c96bdbb-c8f8-495d-ac25-52632f73c42c', '送唐大夫讓節歸山', '送唐大夫讓節归山', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["年老功成乞罷兵，玉階匍匐進雙旌。","朱門鴛瓦爲仙觀，白領狐裘出帝城。","侍女休梳官樣髻，蕃童新改道家名。","到時浸髮春泉裏，猶夢紅樓簫管聲。"]', '["年老功成乞罷兵，玉階匍匐進雙旌。","朱门鴛瓦爲仙观，白領狐裘出帝城。","侍女休梳官樣髻，蕃童新改道家名。","到时浸髮春泉裏，猶梦紅楼簫管声。"]', '诗', 'shi', '', NULL, '送唐大夫讓節歸山 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bbbc1e5-e32c-4fe8-9de1-19525e452291', '買山吟', '買山吟', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["買得幽山屬漢陽，槿籬疎處種桄榔。","唯有獼猴來往熟，弄人拋果滿書堂。"]', '["買得幽山屬漢陽，槿籬疎处種桄榔。","唯有獼猴来往熟，弄人拋果满书堂。"]', '诗', 'shi', '', NULL, '買山吟 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09aa8be6-8a6a-4693-9066-9853aa83ec7b', '古詞三首 一', '古词三首 一', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["素絲帶金地，窗間掬飛塵。","偷得鳳凰釵，門前乞行人。"]', '["素絲带金地，窗间掬飞塵。","偷得鳳凰釵，门前乞行人。"]', '诗', 'shi', '', NULL, '古詞三首 一 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc19d3db-9474-433c-93e1-a6c59ea495f6', '古詞三首 二', '古词三首 二', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["新長青絲髮，啞啞言語黠。","隨人敲銅鏡，街頭救明月。"]', '["新长青絲髮，啞啞言語黠。","隨人敲銅镜，街头救明月。"]', '诗', 'shi', '', NULL, '古詞三首 二 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bab3d928-cfb6-4c38-a339-281b2a324188', '古詞三首 三', '古词三首 三', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["東家新長兒，與妾同時生。","竝長兩心熟，到大相呼名。"]', '["东家新长兒，與妾同时生。","竝长兩心熟，到大相呼名。"]', '诗', 'shi', '', NULL, '古詞三首 三 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c947585-a808-48d2-869d-e549515cbbf6', '秦越人洞中詠', '秦越人洞中詠', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["扁鵲得仙處，傳是西南峰。","年年山下人，長見騎白龍。","洞門黑無底，日夜唯雷風。","清齋將入時，戴星兼抱松。","石徑陰且寒，地響知遠鐘。","似行山林外，聞葉履聲重。","低礙更俯身，漸遠晝夜同。","時時白蝙蝠，飛入茅衣中。","行久路轉窄，靜聞水淙淙。","但願逢一人，自得朝天宮。"]', '["扁鵲得仙处，傳是西南峰。","年年山下人，长见騎白龙。","洞门黑無底，日夜唯雷风。","清斋將入时，戴星兼抱松。","石徑陰且寒，地响知远鐘。","似行山林外，闻葉履声重。","低礙更俯身，漸远晝夜同。","时时白蝙蝠，飞入茅衣中。","行久路轉窄，静闻水淙淙。","但願逢一人，自得朝天宮。"]', '诗', 'shi', '', NULL, '秦越人洞中詠 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fd0fbcb-0230-4804-850e-686283bbecbb', '宿西山修下元齋詠', '宿西山修下元斋詠', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["幽人在何處，松檜深冥冥。","西峰望紫雲，知處安期生。","沐浴溪水暖，新衣禮仙名。","脫屐入靜堂，遶像隨禮行。","碧紗籠寒燈，長幡綴金鈴。","林下聽法人，起坐枯葉聲。","啓奏修律儀，天曙山鳥鳴。","分行布菅茅，列坐滿中庭。","持齋候撞鐘，玉函散寶經。","焚香開卷時，照耀金室明。","投簡石洞深，稱過上帝靈。","學道能苦心，自古無不成。"]', '["幽人在何处，松檜深冥冥。","西峰望紫云，知处安期生。","沐浴溪水暖，新衣禮仙名。","脫屐入静堂，遶像隨禮行。","碧紗籠寒灯，长幡綴金鈴。","林下听法人，起坐枯葉声。","啓奏修律儀，天曙山鸟鳴。","分行布菅茅，列坐满中庭。","持斋候撞鐘，玉函散寶經。","焚香开卷时，照耀金室明。","投簡石洞深，稱過上帝靈。","学道能苦心，自古無不成。"]', '诗', 'shi', '', NULL, '宿西山修下元齋詠 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90259ac4-473c-4451-97f9-7307c1ab0a61', '過凌霄洞天謁張先生祠', '過凌霄洞天謁張先生祠', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["戢戢亂峰裏，一峰獨凌天。","下看如尖高，上有十里泉。","志人愛幽深，一住五十年。","懸牘到其上，乘牛耕藥田。","衣食不下求，乃是雲中仙。","山僧獨知處，相引衝碧煙。","斷崖晝昏黑，槎臬橫隻椽。","面壁攀石稜，養力方敢前。","累歇日已沒，始到茅堂邊。","見客不問誰，禮質無周旋。","醉臥枕欹樹，寒坐展青氈。","折松掃藜牀，秋菓顏色鮮。","鍊蜜敲石炭，洗澡乘瀑泉。","白犬舐客衣，驚走聞腥膻。","乃知軒冕徒，寧比雲壑眠。"]', '["戢戢亂峰裏，一峰独凌天。","下看如尖高，上有十里泉。","志人愛幽深，一住五十年。","懸牘到其上，乘牛耕藥田。","衣食不下求，乃是云中仙。","山僧独知处，相引衝碧煙。","斷崖晝昏黑，槎臬橫隻椽。","面壁攀石稜，養力方敢前。","累歇日已沒，始到茅堂邊。","见客不问誰，禮質無周旋。","醉臥枕欹樹，寒坐展青氈。","折松掃藜牀，秋菓顏色鲜。","鍊蜜敲石炭，洗澡乘瀑泉。","白犬舐客衣，驚走闻腥膻。","乃知軒冕徒，寧比云壑眠。"]', '诗', 'shi', '', NULL, '過凌霄洞天謁張先生祠 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6988ee0e-7257-4539-8f2f-2518806b13e2', '早上凌霄第六峰入紫谿禮白鶴觀祠', '早上凌霄第六峰入紫谿禮白鹤观祠', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["路轉第六峰，傳是十里程。","放石試淺深，䃂壁虵鳥驚。","欲下先襞衣，路底避枯莖。","迴途歇嵌窟，整帶重冠纓。","及到紫石溪，晻晻已天明。","漸近神仙居，桂花濕溟溟。","陰苔無人蹤，時得白鶴翎。","忽然見朱樓，象牌題玉京。","沈沈五雲影，香風散縈縈。","清齋上玉堂，窗戶懸水精。","青童撞金屑，杵臼聲丁丁。","膻腥遙問誰，稽首稱姓名。","若容在溪口，願乞殘雲英。"]', '["路轉第六峰，傳是十里程。","放石試淺深，䃂壁虵鸟驚。","欲下先襞衣，路底避枯莖。","迴途歇嵌窟，整带重冠纓。","及到紫石溪，晻晻已天明。","漸近神仙居，桂花濕溟溟。","陰苔無人蹤，时得白鹤翎。","忽然见朱楼，象牌題玉京。","沈沈五云影，香风散縈縈。","清斋上玉堂，窗戶懸水精。","青童撞金屑，杵臼声丁丁。","膻腥遙问誰，稽首稱姓名。","若容在溪口，願乞殘云英。"]', '诗', 'shi', '', NULL, '早上凌霄第六峰入紫谿禮白鶴觀祠 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e9464f4-6c2f-4bf4-ae66-3ed16d66064e', '山中訪道者', '山中訪道者', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["觸煙入溪口，岸岸唯檉櫟。","其中盡碧流，十里不通屐。","出林山始轉，絕徑緣峭壁。","把藤借行勢，側足憑石脈。","㰹牙斷行處，光滑猿猱跡。","忽然風景異，乃到神仙宅。","天晴茅屋頭，殘雲蒸氣白。","隔窗梳髮聲，久立聞吹笛。","抱琴出門來，不顧人間客。","山院不灑掃，四時自虛寂。","落葉埋長松，出地纔數尺。","曾讀上清經，知注長生籍。","願示不死方，何山有瓊液。"]', '["觸煙入溪口，岸岸唯檉櫟。","其中尽碧流，十里不通屐。","出林山始轉，絕徑緣峭壁。","把藤借行勢，側足憑石脈。","㰹牙斷行处，光滑猿猱跡。","忽然风景異，乃到神仙宅。","天晴茅屋头，殘云蒸氣白。","隔窗梳髮声，久立闻吹笛。","抱琴出门来，不顧人间客。","山院不灑掃，四时自虛寂。","落葉埋长松，出地纔數尺。","曾读上清經，知注长生籍。","願示不死方，何山有瓊液。"]', '诗', 'shi', '', NULL, '山中訪道者 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01a40659-28cc-455d-a83a-73ec5a81d982', '寄盧儼員外秋衣詞', '寄盧儼員外秋衣词', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["寄遠空以心，心誠亦難知。","篋中有秋帛，裁作遠客衣。","縫製雖女功，尺度手自持。","容貌常目中，長短不復疑。","斜縫密且堅，遊客多塵緇。","意欲都無言，澣濯耐歲時。","殷勤託行人，傳語慎勿遺。","別來年已老，亦聞鬢成絲。","縱然更相逢，握手唯是悲。","所寄莫復棄，願見長相思。"]', '["寄远空以心，心誠亦难知。","篋中有秋帛，裁作远客衣。","縫製雖女功，尺度手自持。","容貌常目中，长短不复疑。","斜縫密且堅，游客多塵緇。","意欲都無言，澣濯耐歲时。","殷勤託行人，傳語慎勿遺。","別来年已老，亦闻鬢成絲。","縱然更相逢，握手唯是悲。","所寄莫复棄，願见长相思。"]', '诗', 'shi', '', NULL, '寄盧儼員外秋衣詞 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ae81318-1141-4de0-9455-7789fea59317', '種樹', '種樹', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["一樹新栽益四鄰，野夫如到舊山春。","樹成多是人先老，垂白看他攀折人。"]', '["一樹新栽益四鄰，野夫如到旧山春。","樹成多是人先老，垂白看他攀折人。"]', '诗', 'shi', '', NULL, '種樹 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2a9dfc9-7164-4841-8b44-1ab9d101437c', '哭李暹', '哭李暹', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["驅馬街中哭送君，靈車碾雪隔城聞。","唯有山僧與樵客，共舁孤櫬入幽墳。"]', '["驱马街中哭送君，靈车碾雪隔城闻。","唯有山僧與樵客，共舁孤櫬入幽墳。"]', '诗', 'shi', '', NULL, '哭李暹 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aea52322-33bf-4e83-9b77-3a47bd6f2ad0', '古挽歌 一', '古挽歌 一', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["雙轍出郭門，綿綿東西道。","送死多於生，幾人得終老。","見此切肺肝，不如歸山好。","不聞哀哭聲，默默安懷抱。","時盡從物化，又免生憂擾。","世間壽者稀，盡爲悲傷惱。"]', '["雙轍出郭门，綿綿东西道。","送死多於生，幾人得終老。","见此切肺肝，不如归山好。","不闻哀哭声，默默安懷抱。","时尽從物化，又免生憂擾。","世间壽者稀，尽爲悲傷惱。"]', '诗', 'shi', '', NULL, '古挽歌 一 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ef0bbc2-1e0c-4890-82ac-45905f097232', '古挽歌 二', '古挽歌 二', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["送哭誰家車，靈旛紫帶長。","青童抱何物，明月與香囊。","可惜羅衣色，看舁入水泉。","莫愁埏道暗，燒漆得千年。"]', '["送哭誰家车，靈旛紫带长。","青童抱何物，明月與香囊。","可惜羅衣色，看舁入水泉。","莫愁埏道暗，燒漆得千年。"]', '诗', 'shi', '', NULL, '古挽歌 二 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c47e788d-50a6-4c66-b5bb-1a121e179494', '古挽歌 三', '古挽歌 三', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["陰風吹黃蒿，挽歌度秋水。","車馬却歸城，孤墳月明裏。"]', '["陰风吹黄蒿，挽歌度秋水。","车马却归城，孤墳月明裏。"]', '诗', 'shi', '', NULL, '古挽歌 三 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e4751bd-5f14-487c-ae97-2a7706f3ed9d', '悼孩子', '悼孩子', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["年長始一男，心亦頗自娛。","生來歲未周，奄然却歸無。","裸送不以衣，瘞埋於中衢。","乳母抱出門，所生亦隨呼。","嬰孩無哭儀，禮經不可踰。","親戚相問時，抑悲空歎吁。","襁褓在舊牀，每見立踟躕。","靜思益傷情，畏老爲獨夫。"]', '["年长始一男，心亦頗自娛。","生来歲未周，奄然却归無。","裸送不以衣，瘞埋於中衢。","乳母抱出门，所生亦隨呼。","嬰孩無哭儀，禮經不可踰。","親戚相问时，抑悲空歎吁。","襁褓在旧牀，每见立踟躕。","静思益傷情，畏老爲独夫。"]', '诗', 'shi', '', NULL, '悼孩子 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aef32801-f25a-4a9f-8db8-3704e6005953', '別舊山', '別旧山', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["舊伴同遊盡却回，雲中獨宿守花開。","自是去人身漸老，暮山流水任東來。"]', '["旧伴同游尽却回，云中独宿守花开。","自是去人身漸老，暮山流水任东来。"]', '诗', 'shi', '', NULL, '別舊山 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03addfec-c24f-40b8-8f49-99ba51f39704', '寄周惲', '寄周惲', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["家在荒陂長似秋，蓼花芹葉水蟲幽。","去年相伴尋山客，明月今宵何處遊。"]', '["家在荒陂长似秋，蓼花芹葉水蟲幽。","去年相伴尋山客，明月今宵何处游。"]', '诗', 'shi', '', NULL, '寄周惲 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70098333-7c28-4a3a-96d2-40d5e2e38b77', '野田行', '野田行', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["日暮出古城，野田何茫茫。","寒狐上孤冢，鬼火燒白楊。","昔人未爲泉下客，若到此中還斷腸。"]', '["日暮出古城，野田何茫茫。","寒狐上孤冢，鬼火燒白楊。","昔人未爲泉下客，若到此中還斷腸。"]', '诗', 'shi', '', NULL, '野田行 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3dbe1cd-bf0b-40f6-9367-63ea2fea908d', '塞上曲', '塞上曲', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["行人朝走馬，直走薊城傍。","薊城通漢北，萬里別吳鄉。","海上一烽火，沙中百戰場。","軍書發上郡，春色度河陽。","嫋嫋漢宮柳，青青胡地桑。","琵琶出塞曲，橫笛斷君腸。"]', '["行人朝走马，直走薊城傍。","薊城通漢北，万里別吳乡。","海上一烽火，沙中百戰場。","軍书發上郡，春色度河陽。","嫋嫋漢宮柳，青青胡地桑。","琵琶出塞曲，橫笛斷君腸。"]', '诗', 'shi', '', NULL, '塞上曲 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd39b6f4-de96-4d5a-aa5e-5169a43bae7b', '襄陽寒食', '襄陽寒食', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["煙水初銷見萬家，東風吹柳萬條斜。","大堤欲上誰相伴，馬踏春泥半是花。"]', '["煙水初銷见万家，东风吹柳万條斜。","大堤欲上誰相伴，马踏春泥半是花。"]', '诗', 'shi', '', NULL, '襄陽寒食 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b2a90e2-562a-440c-a447-b38de75a6152', '汎舟入後谿', '汎舟入後谿', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["雨餘芳草淨沙塵，水綠沙平一帶春。","唯有啼鵑似留客，桃花深處更無人。"]', '["雨餘芳草淨沙塵，水綠沙平一带春。","唯有啼鵑似留客，桃花深处更無人。"]', '诗', 'shi', '', NULL, '汎舟入後谿 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b7c46b7-e451-418a-bb12-5219040905bc', '寶劒篇', '寶劒篇', 'ecbfe5f2-0274-4fef-9d83-127e8c8500ce', '唐', '["寶劒不可得，相逢幾許難。","今朝一度見，赤色照人寒。","匣裏星文動，環邊月影殘。","自然神鬼伏，無事莫空彈。"]', '["寶劒不可得，相逢幾許难。","今朝一度见，赤色照人寒。","匣裏星文动，环邊月影殘。","自然神鬼伏，無事莫空彈。"]', '诗', 'shi', '', NULL, '寶劒篇 劉長川 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('655944c8-1dff-4de3-9774-28d561b466d2', '將赴東都上李相公', '將赴东都上李相公', 'ecbfe5f2-0274-4fef-9d83-127e8c8500ce', '唐', '["四海兵初偃，平津閣正開。","誰知大爐下，還有不然灰。"]', '["四海兵初偃，平津閣正开。","誰知大爐下，還有不然灰。"]', '诗', 'shi', '', NULL, '將赴東都上李相公 劉長川 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba081551-ed70-4be3-8a89-2414dd6b312a', '寄邢逸人', '寄邢逸人', '85402394-4b23-4bc8-9290-aa8e02a9aec5', '唐', '["羨君無外事，日與世情違。","地僻人難到，溪深鳥自飛。","儒衣荷葉老，野飯藥苗肥。","疇昔江湖意，而今憶共歸。"]', '["羨君無外事，日與世情違。","地僻人难到，溪深鸟自飞。","儒衣荷葉老，野飯藥苗肥。","疇昔江湖意，而今憶共归。"]', '诗', 'shi', '', NULL, '寄邢逸人 鄭常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeb28c6b-8831-4018-a16a-7434ecf48df2', '送頭陀上人赴廬山寺', '送头陀上人赴廬山寺', '85402394-4b23-4bc8-9290-aa8e02a9aec5', '唐', '["僧家無住著，早晚出東林。","得道非真相，頭陀是苦心。","持齋山果熟，倚錫野雲深。","溪寺誰相待，香花與梵音。"]', '["僧家無住著，早晚出东林。","得道非真相，头陀是苦心。","持斋山果熟，倚錫野云深。","溪寺誰相待，香花與梵音。"]', '诗', 'shi', '', NULL, '送頭陀上人赴廬山寺 鄭常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0ef3f5a-9c30-4f6f-b1c7-2d986ba31425', '謫居漢陽白沙口阻雨因題驛亭', '謫居漢陽白沙口阻雨因題驛亭', '85402394-4b23-4bc8-9290-aa8e02a9aec5', '唐', '["漢陽無遠近，見說過湓城。","雲雨經春客，江山幾日程。","終隨鷗鳥去，秖待海潮生。","前路逢漁父，多慚問姓名。"]', '["漢陽無远近，见说過湓城。","云雨經春客，江山幾日程。","終隨鷗鸟去，秖待海潮生。","前路逢漁父，多慚问姓名。"]', '诗', 'shi', '', NULL, '謫居漢陽白沙口阻雨因題驛亭 鄭常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90612ff9-2970-4c39-b5a9-df622a7405de', '穆陵路', '穆陵路', '336bcd77-7ea3-482c-a66a-e95f6c0ac23d', '唐', '["西遊匣長劒，日暮湘楚間。","歇馬上秋草，逢人問故關。","孤村綠塘水，曠野白雲山。","方念此中去，何時此路還。"]', '["西游匣长劒，日暮湘楚间。","歇马上秋草，逢人问故关。","孤村綠塘水，曠野白云山。","方念此中去，何时此路還。"]', '诗', 'shi', '', NULL, '穆陵路 陳存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af2430da-f902-4987-a23c-094d81cc5b4c', '清溪館作', '清溪館作', '336bcd77-7ea3-482c-a66a-e95f6c0ac23d', '唐', '["指途清溪裏，左右唯深林。","雲蔽望鄉處，雨愁爲客心。","遇人多物役，聽鳥時幽音。","何必滄浪水，庶茲浣塵襟。"]', '["指途清溪裏，左右唯深林。","云蔽望乡处，雨愁爲客心。","遇人多物役，听鸟时幽音。","何必滄浪水，庶茲浣塵襟。"]', '诗', 'shi', '', NULL, '清溪館作 陳存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fff6dff-900e-4e48-8966-eb1b8632b54f', '寓居武丁館', '寓居武丁館', '336bcd77-7ea3-482c-a66a-e95f6c0ac23d', '唐', '["暑雨飄已過，涼飆觸幽衿。","虛館無喧塵，綠槐多晝陰。","俯視古苔積，仰聆早蟬吟。","放卷一長想，閉門千里心。"]', '["暑雨飄已過，涼飆觸幽衿。","虛館無喧塵，綠槐多晝陰。","俯視古苔積，仰聆早蟬吟。","放卷一长想，閉门千里心。"]', '诗', 'shi', '', NULL, '寓居武丁館 陳存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d51cce8e-37b1-4dca-b5e3-9aba68f3a90b', '楚州贈別周愿侍御', '楚州贈別周愿侍御', '336bcd77-7ea3-482c-a66a-e95f6c0ac23d', '唐', '["漂泊楚水來，捨舟坐高館。","途窮在中路，孤征慕前伴。","風雨一留宿，關山去欲嬾。","淮南木葉飛，夜聞廣陵散。"]', '["漂泊楚水来，捨舟坐高館。","途窮在中路，孤征慕前伴。","风雨一留宿，关山去欲嬾。","淮南木葉飞，夜闻廣陵散。"]', '诗', 'shi', '', NULL, '楚州贈別周愿侍御 陳存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d8d5a4d-2cbd-4f13-b159-9cd635051d57', '送劉秀才南歸', '送劉秀才南归', '336bcd77-7ea3-482c-a66a-e95f6c0ac23d', '唐', '["鳥啼楊柳垂，此別千萬里。","古路入商山，春風去灞水。","停車落日在，罷酒離人起。","蓬戶寄龍沙，送歸情詎已。"]', '["鸟啼楊柳垂，此別千万里。","古路入商山，春风去灞水。","停车落日在，罷酒離人起。","蓬戶寄龙沙，送归情詎已。"]', '诗', 'shi', '', NULL, '送劉秀才南歸 陳存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77c46717-ab73-49ec-ad4b-10e918a6d924', '丹陽作', '丹陽作', '336bcd77-7ea3-482c-a66a-e95f6c0ac23d', '唐', '["暫入新豐市，猶聞舊酒香。","抱琴沽一醉，盡日臥垂楊。"]', '["暫入新豐市，猶闻旧酒香。","抱琴沽一醉，尽日臥垂楊。"]', '诗', 'shi', '', NULL, '丹陽作 陳存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('420f8947-b9d9-4645-8770-5cad877d0c58', '早行', '早行', '9291622b-1933-4a13-89b8-686e0ffb1afc', '唐', '["雞唱催人起，又生前去愁。","路明殘月在，山露宿雲收。","村店煙火動，漁家燈燭幽。","趨名與趨利，行役幾時休。"]', '["雞唱催人起，又生前去愁。","路明殘月在，山露宿云收。","村店煙火动，漁家灯燭幽。","趨名與趨利，行役幾时休。"]', '诗', 'shi', '', NULL, '早行 王觀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11966f61-b40f-4f30-95d3-4a3cbc72fa91', '贈營妓', '贈營妓', 'd210c4b2-4e37-42d1-8f6f-8313059f5a25', '唐', '["寒簷寂寂雨霏霏，候館蕭條燭燼微。","只有今宵同此宴，翠娥佯醉欲先歸。"]', '["寒簷寂寂雨霏霏，候館蕭條燭燼微。","只有今宵同此宴，翠娥佯醉欲先归。"]', '诗', 'shi', '', NULL, '贈營妓 崔瓘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a15c066c-4002-40a3-84b9-fdd360e8c34f', '酒席賦得匏瓢', '酒席賦得匏瓢', '0a970f9d-a936-4126-925c-012767461c08', '唐', '["華閣與賢開。","仙瓢自遠來，幽林嘗伴許。","陋巷亦隨回，挂影憐紅壁。","傾心向綠杯，何曾斟酌處。","不使玉山頹。"]', '["华閣與賢开。","仙瓢自远来，幽林嘗伴許。","陋巷亦隨回，挂影怜紅壁。","傾心向綠杯，何曾斟酌处。","不使玉山頹。"]', '诗', 'shi', '', NULL, '酒席賦得匏瓢 鄭審 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b653bb96-6980-4140-9fc5-a458611966b0', '奉使巡檢兩京路種果樹事畢入秦因詠', '奉使巡檢兩京路種果樹事畢入秦因詠', '0a970f9d-a936-4126-925c-012767461c08', '唐', '["聖德周天壤，韶華滿帝畿。","九重承渙汗，千里樹芳菲。","陜塞餘陰薄，關河舊色微。","發生和氣動，封植衆心歸。","春露條應弱，秋霜果定肥。","影移行子蓋，香撲使臣衣。","入逕迷馳道，分行接禁闈。","何當扈仙蹕，攀折奉恩輝。"]', '["聖德周天壤，韶华满帝畿。","九重承渙汗，千里樹芳菲。","陜塞餘陰薄，关河旧色微。","發生和氣动，封植衆心归。","春露條應弱，秋霜果定肥。","影移行子蓋，香撲使臣衣。","入逕迷驰道，分行接禁闈。","何當扈仙蹕，攀折奉恩輝。"]', '诗', 'shi', '', NULL, '奉使巡檢兩京路種果樹事畢入秦因詠 鄭審 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f410eb46-155b-4693-9a4a-403d65198f00', '丹陽作', '丹陽作', '83cfefda-492b-4814-b2ba-2be4a595ffe6', '唐', '["暫入新豐市，猶聞舊酒香。","抱琴沽一醉，盡日臥垂楊。"]', '["暫入新豐市，猶闻旧酒香。","抱琴沽一醉，尽日臥垂楊。"]', '诗', 'shi', '', NULL, '丹陽作 朱彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d1d454d-2443-49fe-a691-781179374678', '採桑', '採桑', 'bd9116da-a68d-4502-8f6f-c09e39dcc9d0', '唐', '["採桑畏日高，不待春眠足。","攀條有餘態，那矜貌如玉。","千金豈不贈，五馬空躑躅。","何以變真性，幽篁雪中綠。"]', '["採桑畏日高，不待春眠足。","攀條有餘態，那矜貌如玉。","千金豈不贈，五马空躑躅。","何以变真性，幽篁雪中綠。"]', '诗', 'shi', '', NULL, '採桑 李彥遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2be7c1ab-63e2-49b3-899d-45c762b2e904', '章仇公席上詠真珠姬', '章仇公席上詠真珠姬', 'd138ce4f-710e-4972-a701-7bca28fd7c54', '唐', '["神女初離碧玉階，彤雲猶擁牡丹鞋。","應知子建憐羅襪，顧步裴回拾翠釵。"]', '["神女初離碧玉階，彤云猶擁牡丹鞋。","應知子建怜羅襪，顧步裴回拾翠釵。"]', '诗', 'shi', '', NULL, '章仇公席上詠真珠姬 范元凱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('160a79e1-a9ec-4eb5-87d5-3c8c206198d7', '爛柯山四首 一', '爛柯山四首 一', '494d27ba-61bb-45eb-80ba-d0a78d7a432c', '唐', '["白雲引策仗，苔徑誰往還。","漸見松樹偃，時聞鳥聲閑。","豁然喧氛盡，獨對萬重山。"]', '["白云引策仗，苔徑誰往還。","漸见松樹偃，时闻鸟声闲。","豁然喧氛尽，独对万重山。"]', '诗', 'shi', '', NULL, '爛柯山四首 一 劉迥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92544841-0b65-452e-be50-81059808d5b8', '爛柯山四首 二', '爛柯山四首 二', '494d27ba-61bb-45eb-80ba-d0a78d7a432c', '唐', '["石橋架絕壑，蒼翠橫鳥道。","憑檻雲脚下，頹陽日猶蚤。","霓裳倘一遇，千載長不老。"]', '["石橋架絕壑，蒼翠橫鸟道。","憑檻云脚下，頹陽日猶蚤。","霓裳倘一遇，千載长不老。"]', '诗', 'shi', '', NULL, '爛柯山四首 二 劉迥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b78402fe-fd8f-4a03-a2c2-fad16d474c14', '爛柯山四首 三', '爛柯山四首 三', '494d27ba-61bb-45eb-80ba-d0a78d7a432c', '唐', '["靈境偶一尋，洞天碧雲上。","爛柯有遺跡，羽客何由訪。","日暮悵欲還，晴煙滿千嶂。"]', '["靈境偶一尋，洞天碧云上。","爛柯有遺跡，羽客何由訪。","日暮悵欲還，晴煙满千嶂。"]', '诗', 'shi', '', NULL, '爛柯山四首 三 劉迥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ffb8cde-44c1-4a31-ae1a-e60a3eda2897', '爛柯山四首 四', '爛柯山四首 四', '494d27ba-61bb-45eb-80ba-d0a78d7a432c', '唐', '["繩牀宴坐久，石窟絕行跡。","能在人代中，遂將人代隔。","白雲風颺飛，非欲待歸客。"]', '["繩牀宴坐久，石窟絕行跡。","能在人代中，遂將人代隔。","白云风颺飞，非欲待归客。"]', '诗', 'shi', '', NULL, '爛柯山四首 四 劉迥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('896cdf9b-805f-450f-87a7-fd266cf979f7', '前年春與獨孤常州兄花時爲別倏已三年矣今鶯花又爾覩物增懷因之抒情聊以奉寄', '前年春與独孤常州兄花时爲別倏已三年矣今鶯花又爾覩物增懷因之抒情聊以奉寄', 'f190d050-07ab-46e7-944a-c6dd87b9d678', '唐', '["近日霜毛一番新，別時芳草兩迴春。","不堪花落花開處，況是江南江北人。","薄宦龍鍾心懶慢，故山寥落水奫淪。","緣君愛我疵瑕少，願竊仁風寄老身。"]', '["近日霜毛一番新，別时芳草兩迴春。","不堪花落花开处，況是江南江北人。","薄宦龙鍾心懶慢，故山寥落水奫淪。","緣君愛我疵瑕少，願竊仁风寄老身。"]', '诗', 'shi', '', NULL, '前年春與獨孤常州兄花時爲別倏已三年矣今鶯花又爾覩物增懷因之抒情聊以奉寄 李幼卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('730fb60d-f059-48cc-9be4-d166ee44757f', '遊爛柯山四首 一', '游爛柯山四首 一', 'f190d050-07ab-46e7-944a-c6dd87b9d678', '唐', '["拂霧理孤策，薄霄眺層岑。","迥升煙霧外，豁見天地心。","物象不可及，遲回空詠吟。"]', '["拂霧理孤策，薄霄眺層岑。","迥升煙霧外，豁见天地心。","物象不可及，遲回空詠吟。"]', '诗', 'shi', '', NULL, '遊爛柯山四首 一 李幼卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17c5283a-e49e-45e5-afa6-49c2084d50ee', '遊爛柯山四首 二', '游爛柯山四首 二', 'f190d050-07ab-46e7-944a-c6dd87b9d678', '唐', '["巨石何崔嵬，橫橋架山頂。","傍通日月過，仰望虹霓迥。","聖者開津梁，誰能度茲嶺。"]', '["巨石何崔嵬，橫橋架山頂。","傍通日月過，仰望虹霓迥。","聖者开津梁，誰能度茲嶺。"]', '诗', 'shi', '', NULL, '遊爛柯山四首 二 李幼卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9ba2957-e87a-4b50-b77f-98e0b79a44ea', '遊爛柯山四首 三', '游爛柯山四首 三', 'f190d050-07ab-46e7-944a-c6dd87b9d678', '唐', '["二仙自圍棊，偶與樵夫會。","仙家異人代，俄頃千年外。","笙鶴何時還，儀形尚相對。"]', '["二仙自圍棊，偶與樵夫會。","仙家異人代，俄頃千年外。","笙鹤何时還，儀形尚相对。"]', '诗', 'shi', '', NULL, '遊爛柯山四首 三 李幼卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1487df1d-eef7-404d-8416-148190c359d3', '遊爛柯山四首 四', '游爛柯山四首 四', 'f190d050-07ab-46e7-944a-c6dd87b9d678', '唐', '["石室過雲外，二僧儼禪寂。","不語對空山，無心向來客。","作禮未及終，忘循舊形跡。"]', '["石室過云外，二僧儼禪寂。","不語对空山，無心向来客。","作禮未及終，忘循旧形跡。"]', '诗', 'shi', '', NULL, '遊爛柯山四首 四 李幼卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8d5935c-b41a-41da-b326-0e188ac37b01', '遊爛柯山四首 一', '游爛柯山四首 一', 'b2b96c21-b112-472b-bf0e-da5273413410', '唐', '["尋源路不迷，絕頂與雲齊。","坐引羣峰小，平看萬木低。","雙林春色上，正有子規啼。"]', '["尋源路不迷，絕頂與云齊。","坐引羣峰小，平看万木低。","雙林春色上，正有子規啼。"]', '诗', 'shi', '', NULL, '遊爛柯山四首 一 李深 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d4a3e3d-e679-4352-8074-42bc387feaf1', '遊爛柯山四首 二', '游爛柯山四首 二', 'b2b96c21-b112-472b-bf0e-da5273413410', '唐', '["嵌空橫洞天，磅礴倚崖巘。","宛如虹勢出，可賞不可轉。","真興得津粱，抽簪永游衍。"]', '["嵌空橫洞天，磅礴倚崖巘。","宛如虹勢出，可賞不可轉。","真兴得津粱，抽簪永游衍。"]', '诗', 'shi', '', NULL, '遊爛柯山四首 二 李深 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10793ae1-9b22-421d-a339-01df3c73435e', '遊爛柯山四首 三', '游爛柯山四首 三', 'b2b96c21-b112-472b-bf0e-da5273413410', '唐', '["羽客無姓名，仙棊但聞見。","行看負薪客，坐使桑田變。","懷古正怡然，前山早鶯囀。"]', '["羽客無姓名，仙棊但闻见。","行看負薪客，坐使桑田变。","懷古正怡然，前山早鶯囀。"]', '诗', 'shi', '', NULL, '遊爛柯山四首 三 李深 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9497caa8-d6ad-48d4-96a7-e6ace892699b', '遊爛柯山四首 四', '游爛柯山四首 四', 'b2b96c21-b112-472b-bf0e-da5273413410', '唐', '["稽首期發蒙，吾師豈無說。","安禪即方丈，演法皆寂滅。","鳴磬雨花香，齋堂飯松屑。"]', '["稽首期發蒙，吾師豈無说。","安禪即方丈，演法皆寂滅。","鳴磬雨花香，斋堂飯松屑。"]', '诗', 'shi', '', NULL, '遊爛柯山四首 四 李深 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63c51e96-384a-4e36-bbfb-e607e53b002b', '遊爛柯山 一', '游爛柯山 一', '5c818e2e-3e80-4c2d-bca3-6d2de267db0e', '唐', '["步登春巖裏，更上最遠山。","聊見宇宙闊，遂令身世閑。","清輝賞不盡，高駕何時還。"]', '["步登春巖裏，更上最远山。","聊见宇宙闊，遂令身世闲。","清輝賞不尽，高駕何时還。"]', '诗', 'shi', '', NULL, '遊爛柯山 一 羊滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30af2636-10b1-4767-a465-16576c09536d', '遊爛柯山 二', '游爛柯山 二', '5c818e2e-3e80-4c2d-bca3-6d2de267db0e', '唐', '["石梁聳千尺，高盼出林囗。","亙壑躡丹虹，排雲弄清影。","路期訪道客，遊衍空井井。"]', '["石梁聳千尺，高盼出林囗。","亙壑躡丹虹，排云弄清影。","路期訪道客，游衍空井井。"]', '诗', 'shi', '', NULL, '遊爛柯山 二 羊滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('643f73f3-6946-46a0-9e3f-5dcd6670b186', '遊爛柯山 三', '游爛柯山 三', '5c818e2e-3e80-4c2d-bca3-6d2de267db0e', '唐', '["採薪窮冥搜，深路轉清暎。","安知洞天裏，偶坐得棋聖。","至今追靈跡，可用陶靜性。"]', '["採薪窮冥搜，深路轉清暎。","安知洞天裏，偶坐得棋聖。","至今追靈跡，可用陶静性。"]', '诗', 'shi', '', NULL, '遊爛柯山 三 羊滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f5bc09a-374e-4fdc-845e-a2facaa7a8fc', '遊爛柯山 四', '游爛柯山 四', '5c818e2e-3e80-4c2d-bca3-6d2de267db0e', '唐', '["沙門何處人，攜手俱滅跡。","深入不動境，乃知真圓寂。","有時歸羅浮，白日見飛錫。"]', '["沙门何处人，携手俱滅跡。","深入不动境，乃知真圓寂。","有时归羅浮，白日见飞錫。"]', '诗', 'shi', '', NULL, '遊爛柯山 四 羊滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7feaa005-b044-4d99-94ad-21734d0d48d1', '遊爛柯山 一', '游爛柯山 一', '4a9d4e9e-c260-4a54-a6af-dbfb45bcdfff', '唐', '["登巖已寂歷，絕頂更岧嶤。","響像如天近，窺臨與世遙。","悠然暢心目，萬慮一時銷。"]', '["登巖已寂歷，絕頂更岧嶤。","响像如天近，窺臨與世遙。","悠然暢心目，万慮一时銷。"]', '诗', 'shi', '', NULL, '遊爛柯山 一 薛戎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc32fedf-ed94-41b2-a621-c9c6f8587895', '遊爛柯山 二', '游爛柯山 二', '4a9d4e9e-c260-4a54-a6af-dbfb45bcdfff', '唐', '["聖遊本無跡，留此示津粱。","架險知何適，遺名但不亡。","只今成佛宇，化度果難量。"]', '["聖游本無跡，留此示津粱。","架險知何適，遺名但不亡。","只今成佛宇，化度果难量。"]', '诗', 'shi', '', NULL, '遊爛柯山 二 薛戎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27c8ddbe-a5e3-45a8-845a-2037dd47a15b', '遊爛柯山 三', '游爛柯山 三', '4a9d4e9e-c260-4a54-a6af-dbfb45bcdfff', '唐', '["二仙行自適，日月徒遷徙。","不語寄手談，無心引樵子。","蒙分一丸藥，相偶窮年祀。"]', '["二仙行自適，日月徒遷徙。","不語寄手談，無心引樵子。","蒙分一丸藥，相偶窮年祀。"]', '诗', 'shi', '', NULL, '遊爛柯山 三 薛戎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad28684c-b58f-4480-9f1c-57e451d79fa6', '遊爛柯山 四', '游爛柯山 四', '4a9d4e9e-c260-4a54-a6af-dbfb45bcdfff', '唐', '["仙山習禪處，了知通李釋。","昔作異時人，今成相對寂。","便是不二門，自生瞻仰意。"]', '["仙山習禪处，了知通李釋。","昔作異时人，今成相对寂。","便是不二门，自生瞻仰意。"]', '诗', 'shi', '', NULL, '遊爛柯山 四 薛戎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb53777c-911e-4aa2-a921-5d12707d82c3', '遊爛柯山 一', '游爛柯山 一', '9f6472d7-ee7f-4630-b6f3-0e8878dd3368', '唐', '["獨凌清景出，下視衆山中。","雲日遙相對，川原無不通。","自致高標末，何心待馭風。"]', '["独凌清景出，下視衆山中。","云日遙相对，川原無不通。","自致高標末，何心待馭风。"]', '诗', 'shi', '', NULL, '遊爛柯山 一 謝勮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('674e19cf-209a-4170-8dbc-04f1704f6ce0', '遊爛柯山 二', '游爛柯山 二', '9f6472d7-ee7f-4630-b6f3-0e8878dd3368', '唐', '["宛演橫半規，穹崇翠微上。","雲扃掩苔石，千古無人賞。","寧知後賢心，登此共來往。"]', '["宛演橫半規，穹崇翠微上。","云扃掩苔石，千古無人賞。","寧知後賢心，登此共来往。"]', '诗', 'shi', '', NULL, '遊爛柯山 二 謝勮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cf4d796-09e7-44bc-b6a0-6b98d6ac872c', '遊爛柯山 三', '游爛柯山 三', '9f6472d7-ee7f-4630-b6f3-0e8878dd3368', '唐', '["仙弈示樵夫，能言忘歸路。","因看斧柯爛，孫子髮已素。","孰云遺跡久，舉意如旦暮。"]', '["仙弈示樵夫，能言忘归路。","因看斧柯爛，孫子髮已素。","孰云遺跡久，舉意如旦暮。"]', '诗', 'shi', '', NULL, '遊爛柯山 三 謝勮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dba9ad86-b6a8-4db2-b67a-686ea1dd8670', '遊爛柯山 四', '游爛柯山 四', '9f6472d7-ee7f-4630-b6f3-0e8878dd3368', '唐', '["仙僧會真要，應物常淵默。","惟將無住理，轉與信人說。","月影清江中，可觀不可得。"]', '["仙僧會真要，應物常淵默。","惟將無住理，轉與信人说。","月影清江中，可观不可得。"]', '诗', 'shi', '', NULL, '遊爛柯山 四 謝勮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8386aabc-4ddd-4c38-a062-c3e8c7c47486', '奉和聖製三日書懷因以示百寮', '奉和聖製三日书懷因以示百寮', 'e1807e2d-0a46-4765-9223-337aaa1faba4', '唐', '["佳節上元巳，芳時屬暮春。","流觴想蘭亭，捧劒傳金人。","風輕水初綠，日遲花更新。","天文信昭回，皇道頗敷陳。","恭己每從儉，清心常保真。","戒茲遊衍樂，書以示羣臣。"]', '["佳節上元巳，芳时屬暮春。","流觴想蘭亭，捧劒傳金人。","风轻水初綠，日遲花更新。","天文信昭回，皇道頗敷陳。","恭己每從儉，清心常保真。","戒茲游衍乐，书以示羣臣。"]', '诗', 'shi', '', NULL, '奉和聖製三日書懷因以示百寮 崔元翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8621bb1-0103-4ce2-88ec-af505c36b118', '奉和聖製重陽旦日百寮曲江宴示懷', '奉和聖製重陽旦日百寮曲江宴示懷', 'e1807e2d-0a46-4765-9223-337aaa1faba4', '唐', '["偶聖覩昌期，受恩慙弱質。","幸逢良宴會，況是清秋日。","遠岫對壺觴，澄瀾映簪紱。","炮羔備豐膳，集鳳調鳴律。","薄劣廁英豪，歡娛忘衰疾。","平臯行雁下，曲渚雙鳧出。","沙岸菊開花，霜枝果垂實。","天文見成象，帝念資勤恤。","探道得玄珠，齋心居特室。","豈如橫汾唱，其事徒驕逸。"]', '["偶聖覩昌期，受恩慙弱質。","幸逢良宴會，況是清秋日。","远岫对壺觴，澄瀾映簪紱。","炮羔備豐膳，集鳳調鳴律。","薄劣廁英豪，歡娛忘衰疾。","平臯行雁下，曲渚雙鳧出。","沙岸菊开花，霜枝果垂實。","天文见成象，帝念資勤恤。","探道得玄珠，斋心居特室。","豈如橫汾唱，其事徒驕逸。"]', '诗', 'shi', '', NULL, '奉和聖製重陽旦日百寮曲江宴示懷 崔元翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa9b7de0-a697-4f5b-b2f9-bac84361a46d', '奉和聖製中元日題奉敬寺', '奉和聖製中元日題奉敬寺', 'e1807e2d-0a46-4765-9223-337aaa1faba4', '唐', '["妙道非本說，殊途成異名。","聖人得其要，俱以化羣生。","鳳吹從上苑，龍宮連外城。","花鬘列後殿，雲車駐前庭。","松竹含新秋，軒窗有餘清。","緬懷崆峒事，須繼簫管聲。","離相境都寂，忘言理更精。","域中信稱大，天下乃爲輕。","屈己由濟物，堯心豈所榮。"]', '["妙道非本说，殊途成異名。","聖人得其要，俱以化羣生。","鳳吹從上苑，龙宮連外城。","花鬘列後殿，云车駐前庭。","松竹含新秋，軒窗有餘清。","緬懷崆峒事，須繼簫管声。","離相境都寂，忘言理更精。","域中信稱大，天下乃爲轻。","屈己由濟物，堯心豈所榮。"]', '诗', 'shi', '', NULL, '奉和聖製中元日題奉敬寺 崔元翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d73b38a-6d38-4bcb-98fc-8454a61de134', '奉和登玄武樓觀射即事書懷賜孟涉應制', '奉和登玄武楼观射即事书懷賜孟涉應制', 'e1807e2d-0a46-4765-9223-337aaa1faba4', '唐', '["寧歲常有備，殊方靡不賓。","禁營列武衛，帝座彰威神。","講事一臨幸，加恩徧撫巡。","城高鳳樓聳，塲逈獸侯新。","飲羽連百中，控弦踰六鈞。","揀材盡爪士，受任皆信臣。","光賞文藻麗，便繁心膂親。","復如觀太清，昭爛垂芳辰。"]', '["寧歲常有備，殊方靡不賓。","禁營列武衛，帝座彰威神。","講事一臨幸，加恩徧撫巡。","城高鳳楼聳，塲逈獸侯新。","饮羽連百中，控弦踰六鈞。","揀材尽爪士，受任皆信臣。","光賞文藻丽，便繁心膂親。","复如观太清，昭爛垂芳辰。"]', '诗', 'shi', '', NULL, '奉和登玄武樓觀射即事書懷賜孟涉應制 崔元翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a7c53b1-7214-4fb5-8b94-ba0ded548abb', '清明節郭侍御偶與李侍御孔校書王秀才遊開化寺臥病不得同遊賦得十韻兼呈馬十八郎丞公', '清明節郭侍御偶與李侍御孔校书王秀才游开化寺臥病不得同游賦得十韻兼呈马十八郎丞公', 'e1807e2d-0a46-4765-9223-337aaa1faba4', '唐', '["山色入層城，鍾聲臨複岫。","乘閑息邊事，探異憐春候。","曲閣下重階，迴廊遙對霤。","石間花徧落，草上雲時覆。","鑽火見樵人，飲泉逢野獸。","道情親法侶，時望登朝右。","執憲糺姦邪，刊書正訛謬。","茂才當時選，公子生人秀。","贈荅繼篇章，歡娛重朋舊。","垂簾獨衰疾，擊缶酬金奏。"]', '["山色入層城，鍾声臨複岫。","乘闲息邊事，探異怜春候。","曲閣下重階，迴廊遙对霤。","石间花徧落，草上云时覆。","鑽火见樵人，饮泉逢野獸。","道情親法侶，时望登朝右。","執憲糺姦邪，刊书正訛謬。","茂才當时選，公子生人秀。","贈荅繼篇章，歡娛重朋旧。","垂簾独衰疾，擊缶酬金奏。"]', '诗', 'shi', '', NULL, '清明節郭侍御偶與李侍御孔校書王秀才遊開化寺臥病不得同遊賦得十韻兼呈馬十八郎丞公 崔元翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cac20d0-4eb1-4b7b-a829-ff529c939a1c', '雜言奉和聖製至承光院見自生藤感其得地因以成詠應制', '杂言奉和聖製至承光院见自生藤感其得地因以成詠應制', 'e1807e2d-0a46-4765-9223-337aaa1faba4', '唐', '["新藤正可翫，得地又逢時。","羅生密葉交綠蔓，欲布清陰垂紫蕤。","已帶朝光暖，猶含輕露滋。","遙依千華殿，稍上萬年枝。","餘芳連桂樹，積潤傍蓮池。","豈如幽谷無人見，空覆荒榛雜兔絲。","聖心對此應有感，隱迹如斯誰復知。","懷賢勞永歎，比物賦新詩。","聘丘園，訪茅茨。","爲謝中林士，王道本無私。"]', '["新藤正可翫，得地又逢时。","羅生密葉交綠蔓，欲布清陰垂紫蕤。","已带朝光暖，猶含轻露滋。","遙依千华殿，稍上万年枝。","餘芳連桂樹，積潤傍蓮池。","豈如幽谷無人见，空覆荒榛杂兔絲。","聖心对此應有感，隐迹如斯誰复知。","懷賢勞永歎，比物賦新诗。","聘丘园，訪茅茨。","爲謝中林士，王道本無私。"]', '诗', 'shi', '', NULL, '雜言奉和聖製至承光院見自生藤感其得地因以成詠應制 崔元翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06bcd5bc-f822-48b9-9204-08e3eff83f4d', '雨中對後簷叢竹', '雨中对後簷叢竹', 'e1807e2d-0a46-4765-9223-337aaa1faba4', '唐', '["含風搖硯水，帶雨拂牆衣。","乍似秋江上，漁家半掩扉。"]', '["含风搖硯水，带雨拂牆衣。","乍似秋江上，漁家半掩扉。"]', '诗', 'shi', '', NULL, '雨中對後簷叢竹 崔元翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a253649-bc67-4efb-b7a9-6486a4cf591c', '賦得沈珠於泉', '賦得沈珠於泉', 'e3f22954-3af5-49d2-9e2c-a1b6f576a38b', '唐', '["皎潔沈泉水，熒煌照乘珠。","沈非將寶契，還與不貪符。","風折璿成浪，空涵影似浮。","深看星幷入，靜向月同無。","光價憐時重，亡情信道樞。","不應無脛至，自爲暗投殊。"]', '["皎潔沈泉水，熒煌照乘珠。","沈非將寶契，還與不貪符。","风折璿成浪，空涵影似浮。","深看星幷入，静向月同無。","光價怜时重，亡情信道樞。","不應無脛至，自爲暗投殊。"]', '诗', 'shi', '', NULL, '賦得沈珠於泉 獨孤良器 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('824960be-7ecd-4bfd-902d-689a3a9d39b3', '雪席口占', '雪席口占', '7ccbaa23-a630-4826-8147-79398bf3380e', '唐', '["崇文宗武不崇文，提戈出塞號將軍。","那箇𩩉兒射雁落，白毛空裏亂紛紛。"]', '["崇文宗武不崇文，提戈出塞號將軍。","那箇𩩉兒射雁落，白毛空裏亂紛紛。"]', '诗', 'shi', '', NULL, '雪席口占 高崇文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b43cff2-ab22-4a9b-b8e3-d6dd4b4dde1b', '雪席口占', '雪席口占', '7ccbaa23-a630-4826-8147-79398bf3380e', '唐', '["崇文崇武不崇文，提戈出塞舊從軍。","有似蕃兒射雁落，白毛空裏亂紛紛。"]', '["崇文崇武不崇文，提戈出塞旧從軍。","有似蕃兒射雁落，白毛空裏亂紛紛。"]', '诗', 'shi', '', NULL, '雪席口占 高崇文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eec7b9f-8420-4c2d-9dfe-cfaec4d6622a', '行縣至浮查山寺', '行縣至浮查山寺', 'c9b61b67-3678-4648-9cab-9aa29d54d30f', '唐', '["三十年前此布衣，鹿鳴西上虎符歸。","行時賓從過前寺，到處松杉長舊圍。","野老競遮官道拜，沙鷗遙避隼旟飛。","春風一宿琉璃地，自有泉聲愜素機。"]', '["三十年前此布衣，鹿鳴西上虎符归。","行时賓從過前寺，到处松杉长旧圍。","野老競遮官道拜，沙鷗遙避隼旟飞。","春风一宿琉璃地，自有泉声愜素機。"]', '诗', 'shi', '', NULL, '行縣至浮查山寺 羅珦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb531005-605f-4a66-8fbd-9512f14e03cf', '賦四相詩 中書令漢陽王張柬之', '賦四相诗 中书令漢陽王張柬之', 'c954aafc-a289-4bc1-987d-d730089aba3b', '唐', '["周曆革元命，天步值艱阻。","烈烈張漢陽，左袒清諸武。","休明神器正，文物舊儀覩。","南向翊大君，西宮朝聖母。","茂勳鏤鐘鼎，鴻勞食茅土。","至今稱五王，卓立邁萬古。"]', '["周曆革元命，天步值艱阻。","烈烈張漢陽，左袒清諸武。","休明神器正，文物旧儀覩。","南向翊大君，西宮朝聖母。","茂勳鏤鐘鼎，鴻勞食茅土。","至今稱五王，卓立邁万古。"]', '诗', 'shi', '', NULL, '賦四相詩 中書令漢陽王張柬之 皇甫澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebc87cea-4917-49ad-bb47-87ad0612f826', '賦四相詩 中書令鍾紹京', '賦四相诗 中书令鍾紹京', 'c954aafc-a289-4bc1-987d-d730089aba3b', '唐', '["景龍仙駕遠，中禁奸釁結。","謀猷叶聖朝，披鱗奮英節。","青宮閶闔啓，滌穢氛沴滅。","紫氣重昭回，皇天新日月。","從容廟堂上，肅穆人神悅。","唐元佐命功，輝煥何烈烈。"]', '["景龙仙駕远，中禁奸釁結。","謀猷叶聖朝，披鱗奮英節。","青宮閶闔啓，滌穢氛沴滅。","紫氣重昭回，皇天新日月。","從容廟堂上，肅穆人神悅。","唐元佐命功，輝煥何烈烈。"]', '诗', 'shi', '', NULL, '賦四相詩 中書令鍾紹京 皇甫澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6852da31-3e1c-4d0f-b825-d783ac0be104', '賦四相詩 禮部尚書門下侍郎平章事李峴', '賦四相诗 禮部尚书门下侍郎平章事李峴', 'c954aafc-a289-4bc1-987d-d730089aba3b', '唐', '["時來遇明聖，道濟寧邦國。","猗歟瑚璉器，竭我股肱力。","進賢黜不肖，錯枉舉諸直。","宦官既却坐，權奸亦移職。","載踐每若驚，三已無慍色。","昭昭垂憲章，來世實作則。"]', '["时来遇明聖，道濟寧邦国。","猗歟瑚璉器，竭我股肱力。","進賢黜不肖，錯枉舉諸直。","宦官既却坐，權奸亦移職。","載踐每若驚，三已無慍色。","昭昭垂憲章，来世實作則。"]', '诗', 'shi', '', NULL, '賦四相詩 禮部尚書門下侍郎平章事李峴 皇甫澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('291140fd-f2f1-4f69-b20c-69ca187a02d9', '賦四相詩 門下侍郎平章事王縉', '賦四相诗 门下侍郎平章事王縉', 'c954aafc-a289-4bc1-987d-d730089aba3b', '唐', '["舟檝濟巨川，山河資秀氣。","服膺究儒業，屈指取高位。","北征戮驕悍，東守輯攜貳。","論道致巍巍，持衡無事事。","知己不易遇，宰相固有器。","瞻事華壁中，來者誰其嗣。"]', '["舟檝濟巨川，山河資秀氣。","服膺究儒業，屈指取高位。","北征戮驕悍，东守輯携貳。","論道致巍巍，持衡無事事。","知己不易遇，宰相固有器。","瞻事华壁中，来者誰其嗣。"]', '诗', 'shi', '', NULL, '賦四相詩 門下侍郎平章事王縉 皇甫澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72c74470-21f6-448b-876d-a147866b09dd', '上巳泛舟得遲字', '上巳泛舟得遲字', '4755852b-b3e1-4fbc-9cc8-497eb251d246', '唐', '["令節推元巳，天涯喜有期。","初筵臨泛地，舊俗祓禳時。","枉渚潮新上，殘春日正遲。","竹枝遊女曲，桃葉渡江詞。","風鷁今方退，沙鷗亦未疑。","且同山簡醉，倒載莫褰帷。"]', '["令節推元巳，天涯喜有期。","初筵臨泛地，旧俗祓禳时。","枉渚潮新上，殘春日正遲。","竹枝游女曲，桃葉渡江词。","风鷁今方退，沙鷗亦未疑。","且同山簡醉，倒載莫褰帷。"]', '诗', 'shi', '', NULL, '上巳泛舟得遲字 張登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ab954e0-68ab-4681-abcc-cbf18bb5818f', '送王主簿遊南海', '送王主簿游南海', '4755852b-b3e1-4fbc-9cc8-497eb251d246', '唐', '["平生推久要，留滯共三年。","明日東南路，窮荒霧露天。","曠懷常寄酒，素業不言錢。","道在貧非病，時來醜亦妍。","過山乘蠟屐，涉海附樓船。","行矣無爲恨，宗門有大賢。"]', '["平生推久要，留滯共三年。","明日东南路，窮荒霧露天。","曠懷常寄酒，素業不言錢。","道在貧非病，时来醜亦妍。","過山乘蠟屐，涉海附楼船。","行矣無爲恨，宗门有大賢。"]', '诗', 'shi', '', NULL, '送王主簿遊南海 張登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32dc9f07-4c78-4901-991c-a66cb0a3c2aa', '重陽宴集同用寒字', '重陽宴集同用寒字', '4755852b-b3e1-4fbc-9cc8-497eb251d246', '唐', '["錫宴逢佳節，窮荒亦共歡。","恩深百日澤，雨借九秋寒。","望氣人謠洽，臨風客以難。","座移山色在，杯盡菊香殘。","欲識投醪遍，應從落帽看。","還宵須命燭，舉首謝三官。"]', '["錫宴逢佳節，窮荒亦共歡。","恩深百日澤，雨借九秋寒。","望氣人謠洽，臨风客以难。","座移山色在，杯尽菊香殘。","欲識投醪遍，應從落帽看。","還宵須命燭，舉首謝三官。"]', '诗', 'shi', '', NULL, '重陽宴集同用寒字 張登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80e0d5d2-f668-45c0-8f80-11eca42467e0', '仲秋夜郡內西亭對月', '仲秋夜郡內西亭对月', '4755852b-b3e1-4fbc-9cc8-497eb251d246', '唐', '["天高月滿影悠悠，一夜炎荒併覺秋。","氣與露清凝衆草，色如霜白怯輕裘。","高臨華宇還知隙，靜映長江不共流。","囗直西傾河漢曙，遺風猶想武昌樓。"]', '["天高月满影悠悠，一夜炎荒併覺秋。","氣與露清凝衆草，色如霜白怯轻裘。","高臨华宇還知隙，静映长江不共流。","囗直西傾河漢曙，遺风猶想武昌楼。"]', '诗', 'shi', '', NULL, '仲秋夜郡內西亭對月 張登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d83c470-1dbe-4930-9b54-e50a1f128bfe', '冬至夜郡齋宴別前華陰盧主簿', '冬至夜郡斋宴別前华陰盧主簿', '4755852b-b3e1-4fbc-9cc8-497eb251d246', '唐', '["虎宿方冬至，雞人積夜籌。","相逢一尊酒，共結兩鄉愁。","王儉花爲府，盧諶幄內璆。","明朝更臨水，悵望嶺南流。"]', '["虎宿方冬至，雞人積夜籌。","相逢一尊酒，共結兩乡愁。","王儉花爲府，盧諶幄內璆。","明朝更臨水，悵望嶺南流。"]', '诗', 'shi', '', NULL, '冬至夜郡齋宴別前華陰盧主簿 張登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2040723e-bc4c-4083-bf86-35b25bc37c7f', '小雪日戲題絕句', '小雪日戲題絕句', '4755852b-b3e1-4fbc-9cc8-497eb251d246', '唐', '["甲子徒推小雪天，刺梧猶綠槿花然。","融和長養無時歇，却是炎洲雨露偏。"]', '["甲子徒推小雪天，刺梧猶綠槿花然。","融和长養無时歇，却是炎洲雨露偏。"]', '诗', 'shi', '', NULL, '小雪日戲題絕句 張登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a253b91-286c-4148-8f41-cd675c5df318', '招客遊寺', '招客游寺', '4755852b-b3e1-4fbc-9cc8-497eb251d246', '唐', '["江城吏散捲春陰，山寺鳴鐘隔雨深。","招取遺民赴僧社，竹堂分坐靜看心。"]', '["江城吏散捲春陰，山寺鳴鐘隔雨深。","招取遺民赴僧社，竹堂分坐静看心。"]', '诗', 'shi', '', NULL, '招客遊寺 張登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5f1043b-4313-461f-bda7-260191751398', '句', '句', '4755852b-b3e1-4fbc-9cc8-497eb251d246', '唐', '["孤高齊帝石，蕭灑晉亭峰。","境曠窮山外，城標漲海頭。"]', '["孤高齊帝石，蕭灑晉亭峰。","境曠窮山外，城標漲海头。"]', '诗', 'shi', '', NULL, '句 張登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2310c7a-b1e5-4ade-8b9c-61dd403a8c05', '陪韓退之竇貽周同尋劉尊師不遇得師字', '陪韓退之竇貽周同尋劉尊師不遇得師字', 'ccea52f4-760d-4fe9-a079-52ee15e1bfa0', '唐', '["早尚逍遙境，常懷汗漫期。","星郎同訪道，羽客杳何之。","物外求仙侶，人間失我師。","不知柯爛者，何處看圍棊。"]', '["早尚逍遙境，常懷汗漫期。","星郎同訪道，羽客杳何之。","物外求仙侶，人间失我師。","不知柯爛者，何处看圍棊。"]', '诗', 'shi', '', NULL, '陪韓退之竇貽周同尋劉尊師不遇得師字 韋執中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d78bede-6620-4b78-b820-cc1ef372f550', '尋人偶題', '尋人偶題', '0a651bbe-a439-409c-ad25-6d88c1d20b09', '唐', '["日昃不復午，落花難歸樹。","人生能幾何，莫厭相逢遇。"]', '["日昃不复午，落花难归樹。","人生能幾何，莫厭相逢遇。"]', '诗', 'shi', '', NULL, '尋人偶題 邵真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5b5f360-038f-448a-9998-7cf5b41329de', '牆陰殘雪', '牆陰殘雪', '10c23df4-27ae-438c-8c67-eac6034ca2ee', '唐', '["積雪還因地，牆陰久尚殘。","影添斜月白，光借夕陽寒。","皎潔開簾近，清熒步履看。","狀花飛著樹，如玉不成盤。","冰薄方寧及，霜濃比亦難。","誰憐高臥處，歲暮歎袁安。"]', '["積雪還因地，牆陰久尚殘。","影添斜月白，光借夕陽寒。","皎潔开簾近，清熒步履看。","狀花飞著樹，如玉不成盤。","冰薄方寧及，霜濃比亦难。","誰怜高臥处，歲暮歎袁安。"]', '诗', 'shi', '', NULL, '牆陰殘雪 何頻瑜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5fc66ba-be3d-468c-9e22-e600355dabeb', '題度支雜事典庭中柏樹', '題度支杂事典庭中柏樹', 'cfc9faa7-d1f2-49a7-ac15-539397538ea8', '唐', '["幹聳一條青玉直，葉鋪千疊綠雲低。","爭如燕雀偏巢此，却是鴛鴦不得棲。"]', '["幹聳一條青玉直，葉鋪千叠綠云低。","爭如燕雀偏巢此，却是鴛鴦不得棲。"]', '诗', 'shi', '', NULL, '題度支雜事典庭中柏樹 駱浚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a66133c3-2ede-417c-94cd-d52c4bd4b4cc', '梢雲', '梢云', '6d8c8dc2-79be-4b11-8233-71637161a014', '唐', '["殊質資靈貺，凌空發瑞雲。","梢梢含樹彩，郁郁動霞文。","不比因風起，全非觸石分。","葉光閑泛灩，枝杪靜氛氳。","隱見心無宰，裴回慶自君。","翻飛如可託，長願在橫汾。"]', '["殊質資靈貺，凌空發瑞云。","梢梢含樹彩，郁郁动霞文。","不比因风起，全非觸石分。","葉光闲泛灩，枝杪静氛氳。","隐见心無宰，裴回慶自君。","翻飞如可託，长願在橫汾。"]', '诗', 'shi', '', NULL, '梢雲 羅讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ce1c554-784f-4654-8d0c-ea19813e232d', '閏月定四時', '閏月定四时', '6d8c8dc2-79be-4b11-8233-71637161a014', '唐', '["月閏隨寒暑，疇人定職司。","餘分將考日，積算自成時。","律候行宜表，陰陽運不欺。","氣薰灰琯驗，數扐卦辭推。","六律文明序，三年理暗移。","當知歲功立，唯是奉無私。"]', '["月閏隨寒暑，疇人定職司。","餘分將考日，積算自成时。","律候行宜表，陰陽運不欺。","氣薰灰琯驗，數扐卦辞推。","六律文明序，三年理暗移。","當知歲功立，唯是奉無私。"]', '诗', 'shi', '', NULL, '閏月定四時 羅讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ea39dc8-7451-4ecc-a894-ffbd61914936', '享文恭太子廟樂章', '享文恭太子廟乐章', '5f89bf13-d1d4-4c79-a8e0-e1dfd4f2ae0e', '唐', '["歌以德發，聲以樂貴。","樂善名存，追仙禮異。","鸞旌拱修，鳳鳴合次。","神聽皇慈，仲月皆至。"]', '["歌以德發，声以乐貴。","乐善名存，追仙禮異。","鸾旌拱修，鳳鳴合次。","神听皇慈，仲月皆至。"]', '诗', 'shi', '', NULL, '享文恭太子廟樂章 陳京 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78bf0059-45ef-46fb-8cf4-21ff9af4c86b', '步虛詞十九首 一', '步虛词十九首 一', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["玉簡真人降，金書道籙通。","煙霞方蔽日，雲雨已生風。","四極威儀異，三天使命同。","那將人世戀，不去上清宮。"]', '["玉簡真人降，金书道籙通。","煙霞方蔽日，云雨已生风。","四極威儀異，三天使命同。","那將人世戀，不去上清宮。"]', '诗', 'shi', '', NULL, '步虛詞十九首 一 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8448e2fc-9cfa-48ba-ac37-b6f527dd4086', '步虛詞十九首 二', '步虛词十九首 二', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["羽駕正翩翩，雲鴻最自然。","霞冠將月曉，珠珮與星連。","鏤玉留新訣，雕金得舊編。","不知飛鸞鶴，更有幾人仙。"]', '["羽駕正翩翩，云鴻最自然。","霞冠將月晓，珠珮與星連。","鏤玉留新訣，雕金得旧編。","不知飞鸾鹤，更有幾人仙。"]', '诗', 'shi', '', NULL, '步虛詞十九首 二 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b950e2f-f09c-4ccc-9fdc-b387f9a713f7', '步虛詞十九首 三', '步虛词十九首 三', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["上帝求仙使，真符取玉郎。","三才閑布象，二景鬱生光。","騎吏排龍虎，笙歌走鳳皇。","天高人不見，暗入白雲鄉。"]', '["上帝求仙使，真符取玉郎。","三才闲布象，二景鬱生光。","騎吏排龙虎，笙歌走鳳皇。","天高人不见，暗入白云乡。"]', '诗', 'shi', '', NULL, '步虛詞十九首 三 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d4350b3-d20f-44b9-ae00-12ca275df160', '步虛詞十九首 四', '步虛词十九首 四', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["鸞鶴共裴回，仙官使者催。","香花三洞啓，風雨百神來。","鳳篆文初定，龍泥印已開。","何須生羽翼，始得上瑤臺。"]', '["鸾鹤共裴回，仙官使者催。","香花三洞啓，风雨百神来。","鳳篆文初定，龙泥印已开。","何須生羽翼，始得上瑤台。"]', '诗', 'shi', '', NULL, '步虛詞十九首 四 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7047b72d-516e-4fbb-8a87-782664d488d9', '步虛詞十九首 五', '步虛词十九首 五', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["羽節忽排煙，蘇君已得仙。","命風驅日月，縮地走山川。","幾處留丹竈，何時種玉田。","一朝騎白虎，直上紫微天。"]', '["羽節忽排煙，蘇君已得仙。","命风驱日月，縮地走山川。","幾处留丹竈，何时種玉田。","一朝騎白虎，直上紫微天。"]', '诗', 'shi', '', NULL, '步虛詞十九首 五 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9407c33b-66b9-485c-bd9e-0217167089d6', '步虛詞十九首 六', '步虛词十九首 六', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["靜發降靈香，思神意智長。","虎存時促步，龍想更成章。","扣齒風雷響，挑燈日月光。","仙雲在何處，髣髴滿空堂。"]', '["静發降靈香，思神意智长。","虎存时促步，龙想更成章。","扣齒风雷响，挑灯日月光。","仙云在何处，髣髴满空堂。"]', '诗', 'shi', '', NULL, '步虛詞十九首 六 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb2ff622-762d-4021-8231-969adb3b3575', '步虛詞十九首 七', '步虛词十九首 七', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["幾度遊三洞，何方召百神。","風雲皆守一，龍虎亦全真。","執節仙童小，燒香玉女春。","應須絕巖內，委曲問皇人。"]', '["幾度游三洞，何方召百神。","风云皆守一，龙虎亦全真。","執節仙童小，燒香玉女春。","應須絕巖內，委曲问皇人。"]', '诗', 'shi', '', NULL, '步虛詞十九首 七 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64a58b4d-e749-4e65-93fa-9ac7a8431803', '步虛詞十九首 八', '步虛词十九首 八', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["上法杳無營，玄修似有情。","道宮瓊作想，真帝玉爲名。","召岳馳旌節，驅雷發吏兵。","雲車降何處，齋室有仙卿。"]', '["上法杳無營，玄修似有情。","道宮瓊作想，真帝玉爲名。","召岳驰旌節，驱雷發吏兵。","云车降何处，斋室有仙卿。"]', '诗', 'shi', '', NULL, '步虛詞十九首 八 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('351ba95c-9ebb-45b7-928f-b57ce42fc4fc', '步虛詞十九首 九', '步虛词十九首 九', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["羽衛一何鮮，香雲起暮煙。","方朝太素帝，更向玉清天。","鳳曲凝猶吹，龍驂儼欲前。","真文幾時降，知在永和年。"]', '["羽衛一何鲜，香云起暮煙。","方朝太素帝，更向玉清天。","鳳曲凝猶吹，龙驂儼欲前。","真文幾时降，知在永和年。"]', '诗', 'shi', '', NULL, '步虛詞十九首 九 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6284471-7726-4de2-ae2f-cca09eb5bf40', '步虛詞十九首 十', '步虛词十九首 十', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["大道何年學，真符此日催。","還持金作印，未要玉爲臺。","羽節分明授，霞衣整頓裁。","應緣五雲使，敎上列仙來。"]', '["大道何年学，真符此日催。","還持金作印，未要玉爲台。","羽節分明授，霞衣整頓裁。","應緣五云使，敎上列仙来。"]', '诗', 'shi', '', NULL, '步虛詞十九首 十 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('164e0e37-ece0-4172-acc8-7b785134dff0', '步虛詞十九首 十一', '步虛词十九首 十一', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["獨自授金書，蕭條詠紫虛。","龍行還當馬，雲起自成車。","九轉風煙合，千年井竈餘。","參差從太一，壽等混元初。"]', '["独自授金书，蕭條詠紫虛。","龙行還當马，云起自成车。","九轉风煙合，千年井竈餘。","參差從太一，壽等混元初。"]', '诗', 'shi', '', NULL, '步虛詞十九首 十一 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bce8d67e-ee84-425e-aea3-8cae1cd48321', '步虛詞十九首 十二', '步虛词十九首 十二', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["道學已通神，香花會女真。","霞牀珠斗帳，金薦玉輿輪。","一室心偏靜，三天夜正春。","靈官竟誰降，仙相有夫人。"]', '["道学已通神，香花會女真。","霞牀珠斗帳，金薦玉輿輪。","一室心偏静，三天夜正春。","靈官竟誰降，仙相有夫人。"]', '诗', 'shi', '', NULL, '步虛詞十九首 十二 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca9a3b79-4b08-4905-93e4-1fae7fe4766b', '步虛詞十九首 十三', '步虛词十九首 十三', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["上界有黃房，仙家道路長。","神來知位次，樂變叶宮商。","競把瑠璃盞，都傾白玉漿。","霞衣最芬馥，蘇合是靈香。"]', '["上界有黄房，仙家道路长。","神来知位次，乐变叶宮商。","競把瑠璃盞，都傾白玉漿。","霞衣最芬馥，蘇合是靈香。"]', '诗', 'shi', '', NULL, '步虛詞十九首 十三 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2de81208-7492-4c3e-ba56-4dd795b03156', '步虛詞十九首 十四', '步虛词十九首 十四', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["珠佩紫霞纓，夫人會八靈。","太霄猶有觀，絕宅豈無形。","暮雨裴回降，仙歌宛轉聽。","誰逢玉妃輦，應檢九真經。"]', '["珠佩紫霞纓，夫人會八靈。","太霄猶有观，絕宅豈無形。","暮雨裴回降，仙歌宛轉听。","誰逢玉妃輦，應檢九真經。"]', '诗', 'shi', '', NULL, '步虛詞十九首 十四 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a322d06-85db-48ee-a1d1-5b5d3964e2d0', '步虛詞十九首 十五', '步虛词十九首 十五', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["西海辭金母，東方拜木公。","雲行疑帶雨，星步欲凌風。","羽袖揮丹鳳，霞巾曳彩虹。","飄颻九霄外，下視望仙宮。"]', '["西海辞金母，东方拜木公。","云行疑带雨，星步欲凌风。","羽袖揮丹鳳，霞巾曳彩虹。","飄颻九霄外，下視望仙宮。"]', '诗', 'shi', '', NULL, '步虛詞十九首 十五 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc07c8a8-4df7-4b47-9f55-65ed8ed6f1b5', '步虛詞十九首 十六', '步虛词十九首 十六', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["玉樹襍金花，天河織女家。","月邀丹鳳舃，風送紫鸞車。","霧縠籠綃帶，雲屏列錦霞。","瑤臺千萬里，不覺往來賒。"]', '["玉樹襍金花，天河织女家。","月邀丹鳳舃，风送紫鸾车。","霧縠籠綃带，云屏列錦霞。","瑤台千万里，不覺往来賒。"]', '诗', 'shi', '', NULL, '步虛詞十九首 十六 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6e12a9c-978b-4b14-8e5c-21703e06df3b', '步虛詞十九首 十七', '步虛词十九首 十七', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["舞鳳凌天出，歌麟入夜聽。","雲容衣眇眇，風韻曲泠泠。","扣齒端金簡，焚香檢玉經。","仙宮知不遠，祗近太微星。"]', '["舞鳳凌天出，歌麟入夜听。","云容衣眇眇，风韻曲泠泠。","扣齒端金簡，焚香檢玉經。","仙宮知不远，祗近太微星。"]', '诗', 'shi', '', NULL, '步虛詞十九首 十七 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d9a1d2c-074b-499d-9c81-71ce34ccfd10', '步虛詞十九首 十八', '步虛词十九首 十八', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["紫府與玄洲，誰來物外遊。","無煩騎白鹿，不用駕青牛。","金化顏應駐，雲飛鬢不秋。","仍聞碧海上，更用玉爲樓。"]', '["紫府與玄洲，誰来物外游。","無煩騎白鹿，不用駕青牛。","金化顏應駐，云飞鬢不秋。","仍闻碧海上，更用玉爲楼。"]', '诗', 'shi', '', NULL, '步虛詞十九首 十八 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aad34ed-7bf5-425f-ab60-c7e2dcc2cf21', '步虛詞十九首 十九', '步虛词十九首 十九', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["轡鶴復驂鸞，全家去不難。","雞聲隨羽化，犬影入雲看。","釀玉當成酒，燒金且轉丹。","何妨五色綬，次第給仙官。"]', '["轡鹤复驂鸾，全家去不难。","雞声隨羽化，犬影入云看。","釀玉當成酒，燒金且轉丹。","何妨五色綬，次第給仙官。"]', '诗', 'shi', '', NULL, '步虛詞十九首 十九 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44401911-0654-445a-ba06-909468174a8d', '覽外生盧綸詩因以示此', '覽外生盧綸诗因以示此', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["衛玠清談性最強，明時獨拜正員郎。","關心珠玉曾無價，滿手瓊瑤更有光。","謀略久參花府盛，才名常帶粉闈香。","終期內殿聊詩句，共汝朝天會柏梁。"]', '["衛玠清談性最強，明时独拜正員郎。","关心珠玉曾無價，满手瓊瑤更有光。","謀略久參花府盛，才名常带粉闈香。","終期內殿聊诗句，共汝朝天會柏梁。"]', '诗', 'shi', '', NULL, '覽外生盧綸詩因以示此 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('501ee5f7-cbd9-4a26-bb5b-32ee7e645fe5', '贈竇五判官', '贈竇五判官', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["故舊相逢三兩家，愛君兄弟有聲華。","文輝錦綵珠垂露，逸興江天綺散霞。","美玉自矜頻獻璞，真金難與細披沙。","終須撰取新詩品，更比芙蓉出水花。"]', '["故旧相逢三兩家，愛君兄弟有声华。","文輝錦綵珠垂露，逸兴江天綺散霞。","美玉自矜頻獻璞，真金难與細披沙。","終須撰取新诗品，更比芙蓉出水花。"]', '诗', 'shi', '', NULL, '贈竇五判官 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c65455a7-a886-4473-b0b6-c8e654964998', '湖上閑居', '湖上闲居', 'd9d932e0-2cfc-4316-91a0-c8b1149bcdf7', '唐', '["避影將息陰，自然知音稀。","向來深林中，偶亦有所窺。","飛鳥口銜食，引雛上高枝。","高枝但各有，安知宜不宜。","止止復何云，物情何自私。"]', '["避影將息陰，自然知音稀。","向来深林中，偶亦有所窺。","飞鸟口銜食，引雛上高枝。","高枝但各有，安知宜不宜。","止止复何云，物情何自私。"]', '诗', 'shi', '', NULL, '湖上閑居 竇參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1052b8e-ca43-4092-b9fd-66568fd10143', '遷謫江表久未歸', '遷謫江表久未归', 'd9d932e0-2cfc-4316-91a0-c8b1149bcdf7', '唐', '["一自經放逐，裴回無所從。","便爲寒山雲，不得隨飛龍。","名豈不欲保，歸豈不欲早。","苟無三月資，難適千里道。","離心與羈思，終日常草草。","人生年幾齊，憂苦即先老。","誰能假羽翼，使我暢懷抱。"]', '["一自經放逐，裴回無所從。","便爲寒山云，不得隨飞龙。","名豈不欲保，归豈不欲早。","苟無三月資，难適千里道。","離心與羈思，終日常草草。","人生年幾齊，憂苦即先老。","誰能假羽翼，使我暢懷抱。"]', '诗', 'shi', '', NULL, '遷謫江表久未歸 竇參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1369520-bef5-4613-8b43-711f35300c56', '登潛山觀', '登潛山观', 'd9d932e0-2cfc-4316-91a0-c8b1149bcdf7', '唐', '["山勢欲相抱，一條微徑盤。","攀蘿歇復行，始得凌仙壇。","聞道葛夫子，此中鍊還丹。","丹成五色光，服之生羽翰。","靈草空自綠，餘霞誰共餐。","至今步虛處，猶有孤飛鸞。","幽幽古殿門，下壓浮雲端。","萬丈水聲落，四時松色寒。","既入無何鄉，轉嫌人事難。","終當遠塵俗，高臥從所安。"]', '["山勢欲相抱，一條微徑盤。","攀蘿歇复行，始得凌仙壇。","闻道葛夫子，此中鍊還丹。","丹成五色光，服之生羽翰。","靈草空自綠，餘霞誰共餐。","至今步虛处，猶有孤飞鸾。","幽幽古殿门，下壓浮云端。","万丈水声落，四时松色寒。","既入無何乡，轉嫌人事难。","終當远塵俗，高臥從所安。"]', '诗', 'shi', '', NULL, '登潛山觀 竇參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4520b4ef-e24a-4338-b25c-e6d85afa33bd', '淮西席上醉歌', '淮西席上醉歌', '4daa1296-24a4-48a9-8bde-4cf68c352d7e', '唐', '["祥瑞不在鳳凰麒麟，太平須得邊將忠臣。","衛霍真誠奉主，貔虎十萬一身。","江河潛注息浪，蠻貊款塞無塵。","但得百寮師長肝膽，不用三軍羅綺金銀。"]', '["祥瑞不在鳳凰麒麟，太平須得邊將忠臣。","衛霍真誠奉主，貔虎十万一身。","江河潛注息浪，蠻貊款塞無塵。","但得百寮師长肝膽，不用三軍羅綺金銀。"]', '诗', 'shi', '', NULL, '淮西席上醉歌 盧羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdaef630-3ae1-4899-8358-1a674ccfab02', '天池晚櫂', '天池晚櫂', '52ee5f84-9adc-4c08-841d-99d06eee67aa', '唐', '["雨霽天池生意足，花間誰詠採蓮曲。","舟浮十里芰荷香，歌發一聲山水綠。","春暖魚拋水面綸，晚晴鷺立波心玉。","扣舷歸載月黃昏，直至更深不假燭。"]', '["雨霽天池生意足，花间誰詠採蓮曲。","舟浮十里芰荷香，歌發一声山水綠。","春暖鱼拋水面綸，晚晴鷺立波心玉。","扣舷归載月黄昏，直至更深不假燭。"]', '诗', 'shi', '', NULL, '天池晚櫂 韋臯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8206ea85-575a-43e7-b3e8-0b7ead649adb', '贈何遐', '贈何遐', '52ee5f84-9adc-4c08-841d-99d06eee67aa', '唐', '["腰間寶劒七星文，掌上彎弓挂六鈞。","箭發囗雲雙鴈落，始知秦地有將軍。"]', '["腰间寶劒七星文，掌上彎弓挂六鈞。","箭發囗云雙鴈落，始知秦地有將軍。"]', '诗', 'shi', '', NULL, '贈何遐 韋臯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb1ef8d5-7c1b-43e6-bb30-dc16fcd24478', '憶玉簫', '憶玉簫', '52ee5f84-9adc-4c08-841d-99d06eee67aa', '唐', '["黃雀銜來已數春，別時留解贈佳人。","長江不見魚書至，爲遣相思夢入秦。"]', '["黄雀銜来已數春，別时留解贈佳人。","长江不见鱼书至，爲遣相思梦入秦。"]', '诗', 'shi', '', NULL, '憶玉簫 韋臯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80755f56-38a4-4d80-a366-cce77d9578ba', '觀翟玉妓', '观翟玉妓', '99564124-c046-4116-be43-d12dffe3b5d2', '唐', '["女郎閨閣春，抱瑟坐花茵。","豔粉宜斜燭，羞蛾慘向人。","寄情搖玉柱，流眄整羅巾。","幸以芳香袖，承君宛轉塵。"]', '["女郎閨閣春，抱瑟坐花茵。","豔粉宜斜燭，羞蛾慘向人。","寄情搖玉柱，流眄整羅巾。","幸以芳香袖，承君宛轉塵。"]', '诗', 'shi', '', NULL, '觀翟玉妓 李愿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f066cb1-dd30-4622-8b07-492afd2e9a85', '思婦', '思婦', '99564124-c046-4116-be43-d12dffe3b5d2', '唐', '["良人久不至，惟恨錦屏孤。","顦顇衣寬日，空房問女巫。"]', '["良人久不至，惟恨錦屏孤。","顦顇衣寬日，空房问女巫。"]', '诗', 'shi', '', NULL, '思婦 李愿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6218387b-d123-409f-ab48-754dba36b772', '徐州使院賦', '徐州使院賦', 'b1be3979-1527-4bed-96b4-414cfab723e6', '唐', '["三十年前老健兒，剛被郎中遣作詩。","江南花柳從君詠，塞北煙塵我獨知。"]', '["三十年前老健兒，剛被郎中遣作诗。","江南花柳從君詠，塞北煙塵我独知。"]', '诗', 'shi', '', NULL, '徐州使院賦 王智興 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71a62f85-a346-4872-927c-b12ef74f36d6', '茶山詩', '茶山诗', 'ef3d0931-62cb-4f93-b91f-066e77b6e34a', '唐', '["禹貢通遠俗，所圖在安人。","後王失其本，職吏不敢陳。","亦有姦佞者，因茲欲求伸。","動生千金費，日使萬姓貧。","我來顧渚源，得與茶事親。","甿輟耕農耒，采采實苦辛。","一夫旦當役，盡室皆同臻。","捫葛上欹壁，蓬頭入荒榛。","終朝不盈掬，手足皆鱗皴。","悲嗟遍空山，草木爲不春。","陰嶺芽未吐，使者牒已頻。","心爭造化功，走挺麋鹿均。","選納無晝夜，搗聲昏繼晨。","衆工何枯櫨，俯視彌傷神。","皇帝尚巡狩，東郊路多堙。","周迴遶天涯，所獻愈艱勤。","況減兵革困，重茲固疲民。","未知供御餘，誰合分此珍。","顧省忝邦守，又慙復因循。","茫茫滄海間，丹憤何由申。"]', '["禹貢通远俗，所圖在安人。","後王失其本，職吏不敢陳。","亦有姦佞者，因茲欲求伸。","动生千金費，日使万姓貧。","我来顧渚源，得與茶事親。","甿輟耕農耒，采采實苦辛。","一夫旦當役，尽室皆同臻。","捫葛上欹壁，蓬头入荒榛。","終朝不盈掬，手足皆鱗皴。","悲嗟遍空山，草木爲不春。","陰嶺芽未吐，使者牒已頻。","心爭造化功，走挺麋鹿均。","選納無晝夜，捣声昏繼晨。","衆工何枯櫨，俯視彌傷神。","皇帝尚巡狩，东郊路多堙。","周迴遶天涯，所獻愈艱勤。","況減兵革困，重茲固疲民。","未知供御餘，誰合分此珍。","顧省忝邦守，又慙复因循。","茫茫滄海间，丹憤何由申。"]', '诗', 'shi', '', NULL, '茶山詩 袁高 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e583001a-c3a7-4b5f-9e66-d2f9371d2c13', '送惟詳律師自越之義興', '送惟詳律師自越之義兴', 'ef1aeae9-6212-4459-87f2-f096f8e14e05', '唐', '["陽羨諸峰頂，何曾異剡山。","雨晴人到寺，木落夜開關。","縫衲紗燈亮，看心錫杖閑。","西方知有社，未得與師還。"]', '["陽羨諸峰頂，何曾異剡山。","雨晴人到寺，木落夜开关。","縫衲紗灯亮，看心錫杖闲。","西方知有社，未得與師還。"]', '诗', 'shi', '', NULL, '送惟詳律師自越之義興 崔子向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f01db97a-eb46-44bd-9ea8-f567ac9ca447', '上鮑大夫', '上鲍大夫', 'ef1aeae9-6212-4459-87f2-f096f8e14e05', '唐', '["行盡江南塞北時，無人不誦鮑家詩。","東堂桂樹何年折，直至如今少一枝。"]', '["行尽江南塞北时，無人不誦鲍家诗。","东堂桂樹何年折，直至如今少一枝。"]', '诗', 'shi', '', NULL, '上鮑大夫 崔子向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ece95cb-79bc-437a-973b-7c5e388185db', '題越王臺', '題越王台', 'ef1aeae9-6212-4459-87f2-f096f8e14e05', '唐', '["越井崗頭松柏老，越王臺上生秋草。","古木多年無子孫，牛羊踐踏成官道。"]', '["越井崗头松柏老，越王台上生秋草。","古木多年無子孫，牛羊踐踏成官道。"]', '诗', 'shi', '', NULL, '題越王臺 崔子向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35114ff1-afd4-49fd-bc9f-e35acd942986', '贈韓退之', '贈韓退之', 'e9ee4ce0-4692-4371-b3c2-cfb79893599e', '唐', '["九疑峰畔二江前，戀闕思鄉日抵年。","白簡趨朝曾竝命，蒼梧左宦一聊翩。","鮫人遠泛漁舟水，鵩鳥閑飛露裏天。","渙汗幾時流率土，扁舟西下共歸田。"]', '["九疑峰畔二江前，戀闕思乡日抵年。","白簡趨朝曾竝命，蒼梧左宦一聊翩。","鮫人远泛漁舟水，鵩鸟闲飞露裏天。","渙汗幾时流率土，扁舟西下共归田。"]', '诗', 'shi', '', NULL, '贈韓退之 張署 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12784fcd-06f6-4864-bd4b-b8a871c441a5', '享惠昭太子廟樂章', '享惠昭太子廟乐章', 'ab92e4f9-6bd3-455d-8693-dcf57b152e0c', '唐', '["嘉薦既陳，祀事孔明。","間歌在堂，萬舞在庭。","外則盡物，內則盡誠。","鳳笙如聞，歆其潔精。"]', '["嘉薦既陳，祀事孔明。","间歌在堂，万舞在庭。","外則尽物，內則尽誠。","鳳笙如闻，歆其潔精。"]', '诗', 'shi', '', NULL, '享惠昭太子廟樂章 歸登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('954bf9b1-ed59-4bca-8f60-5cc747cbd58c', '剡溪行却寄新別者', '剡溪行却寄新別者', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["潺湲寒溪上，自此成離別。","廻首望歸人，移舟逢暮雪。","頻行識草樹，漸老傷年髮。","唯有白雲心，爲向東山月。"]', '["潺湲寒溪上，自此成離別。","廻首望归人，移舟逢暮雪。","頻行識草樹，漸老傷年髮。","唯有白云心，爲向东山月。"]', '诗', 'shi', '', NULL, '剡溪行却寄新別者 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e68bd0e-37f6-4d40-a6d3-b03589b51cb0', '九日陪劉中丞宴昌樂寺送梁廷評', '九日陪劉中丞宴昌乐寺送梁廷評', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["獨坐三臺妙，重陽百越間。","水心觀遠俗，霜氣入秋山。","不棄遺簪舊，寧辭落帽還。","仍聞西上客，咫尺謁天顏。"]', '["独坐三台妙，重陽百越间。","水心观远俗，霜氣入秋山。","不棄遺簪旧，寧辞落帽還。","仍闻西上客，咫尺謁天顏。"]', '诗', 'shi', '', NULL, '九日陪劉中丞宴昌樂寺送梁廷評 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dfa43bd-32fe-459d-bec3-7e391bc247cd', '經故賀賓客鏡湖道士觀', '經故賀賓客镜湖道士观', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["已得歸鄉里，逍遙一外臣。","那隨流水去，不待鏡湖春。","雪裏登山屐，林間漉酒巾。","空餘道士觀，誰是學仙人。"]', '["已得归乡里，逍遙一外臣。","那隨流水去，不待镜湖春。","雪裏登山屐，林间漉酒巾。","空餘道士观，誰是学仙人。"]', '诗', 'shi', '', NULL, '經故賀賓客鏡湖道士觀 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cee4158e-e753-43bf-9a2a-99d4148d3d1a', '送著公歸越', '送著公归越', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["誰能愁此別，到越會相逢。","長憶雲門寺，門前千萬峰。","石牀埋積雪，山路倒枯松。","莫學白道士，無人知去蹤。"]', '["誰能愁此別，到越會相逢。","长憶云门寺，门前千万峰。","石牀埋積雪，山路倒枯松。","莫学白道士，無人知去蹤。"]', '诗', 'shi', '', NULL, '送著公歸越 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76327dab-5c19-42e7-a276-1294a1709caf', '秣陵送客入京', '秣陵送客入京', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["秣陵春已至，君去學歸鴻。","綠水琴聲切，青袍草色同。","鳥喧金谷樹，花滿洛陽宮。","日日相思處，江邊楊柳風。"]', '["秣陵春已至，君去学归鴻。","綠水琴声切，青袍草色同。","鸟喧金谷樹，花满洛陽宮。","日日相思处，江邊楊柳风。"]', '诗', 'shi', '', NULL, '秣陵送客入京 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27db32d1-c747-4c6d-a937-4091287b6622', '靈門寺贈靈一上人', '靈门寺贈靈一上人', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["所思勞旦夕，惆悵去湘東。","禪客知何在，春山幾處同。","獨行殘雪裏，相見暮雲中。","請住東林寺，彌年事遠公。"]', '["所思勞旦夕，惆悵去湘东。","禪客知何在，春山幾处同。","独行殘雪裏，相见暮云中。","請住东林寺，彌年事远公。"]', '诗', 'shi', '', NULL, '靈門寺贈靈一上人 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4620a2b-9b8d-4eb4-8ca7-ef99fa9b479b', '江上送別', '江上送別', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["浦邊新見柳搖時，北客相逢只自悲。","惆悵空知思後會，艱難不敢料前期。","行看漢月愁征戰，共折江花怨別離。","向夕孤城分首處，寂寥橫笛爲君吹。"]', '["浦邊新见柳搖时，北客相逢只自悲。","惆悵空知思後會，艱难不敢料前期。","行看漢月愁征戰，共折江花怨別離。","向夕孤城分首处，寂寥橫笛爲君吹。"]', '诗', 'shi', '', NULL, '江上送別 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e01dc039-7097-4060-8741-df0ef66ec930', '歸桐廬舊居寄嚴長史', '归桐廬旧居寄嚴长史', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["昨辭天子棹歸舟，家在桐廬憶舊丘。","三月暖時花競發，兩溪分處水爭流。","近聞江老傳鄉語，遙見家山減旅愁。","或在醉中逢夜雪，懷賢應向剡川遊。"]', '["昨辞天子棹归舟，家在桐廬憶旧丘。","三月暖时花競發，兩溪分处水爭流。","近闻江老傳乡語，遙见家山減旅愁。","或在醉中逢夜雪，懷賢應向剡川游。"]', '诗', 'shi', '', NULL, '歸桐廬舊居寄嚴長史 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56f4eb52-4489-494d-a140-817d264544c8', '竹', '竹', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["青林何森然，沈沈獨曙前。","出牆同淅瀝，開戶滿嬋娟。","籜卷初呈粉，苔侵亂上錢。","疎中思水過，深處若山連。","疊夜常栖露，清朝乍有蟬。","砌陰迎緩策，簷翠對欹眠。","迸笋雙分箭，繁梢一向偏。","月過驚散雪，風動極聞泉。","幽谷添詩譜，高人欲製篇。","蕭蕭意何恨，不獨往湘川。"]', '["青林何森然，沈沈独曙前。","出牆同淅瀝，开戶满嬋娟。","籜卷初呈粉，苔侵亂上錢。","疎中思水過，深处若山連。","叠夜常栖露，清朝乍有蟬。","砌陰迎緩策，簷翠对欹眠。","迸笋雙分箭，繁梢一向偏。","月過驚散雪，风动極闻泉。","幽谷添诗譜，高人欲製篇。","蕭蕭意何恨，不独往湘川。"]', '诗', 'shi', '', NULL, '竹 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea3e49a3-7e47-47c3-ad1a-e73f28d3f1b8', '銅雀妓', '銅雀妓', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["恨唱歌聲咽，愁翻舞袖遲。","西陵日欲暮，是妾斷腸時。"]', '["恨唱歌声咽，愁翻舞袖遲。","西陵日欲暮，是妾斷腸时。"]', '诗', 'shi', '', NULL, '銅雀妓 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c229ea7-c9a5-4d13-8c76-376361f3c28e', '毘陵留別', '毘陵留別', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["別離非一處，此處最傷情。","白髮將春草，相隨日日生。"]', '["別離非一处，此处最傷情。","白髮將春草，相隨日日生。"]', '诗', 'shi', '', NULL, '毘陵留別 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2651472-5d43-436f-92d9-d75cb2628c2f', '題竹林寺', '題竹林寺', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["歲月人間促，煙霞此地多。","殷勤竹林寺，能得幾廻過。"]', '["歲月人间促，煙霞此地多。","殷勤竹林寺，能得幾廻過。"]', '诗', 'shi', '', NULL, '題竹林寺 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9a7ddac-9ea3-48a2-a928-0762e9b2c5c5', '答陸[澧]', '答陸[澧]', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["松葉堪爲酒，春來釀幾多。","不辭山路遠，踏雪也相過。"]', '["松葉堪爲酒，春来釀幾多。","不辞山路远，踏雪也相過。"]', '诗', 'shi', '', NULL, '答陸[澧] 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2a8f65a-d509-4498-b266-5bcb6edf8522', '楊子津送人', '楊子津送人', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["今朝楊子津，忽見五溪人。","老病無餘事，丹砂乞五斤。"]', '["今朝楊子津，忽见五溪人。","老病無餘事，丹砂乞五斤。"]', '诗', 'shi', '', NULL, '楊子津送人 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35c33a52-1c3a-48bc-86b3-eb3d0820ea22', '山中謁皇甫曾', '山中謁皇甫曾', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["尋源路已盡，笑入白雲間。","不解乘軺客，那知有此山。"]', '["尋源路已尽，笑入白云间。","不解乘軺客，那知有此山。"]', '诗', 'shi', '', NULL, '山中謁皇甫曾 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61d6b6c0-f564-4af0-9f10-761e37a92b64', '剡山夜月', '剡山夜月', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["月在沃洲山上，人歸剡縣溪邊。","漠漠黃花覆水，時時白鷺驚船。"]', '["月在沃洲山上，人归剡縣溪邊。","漠漠黄花覆水，时时白鷺驚船。"]', '诗', 'shi', '', NULL, '剡山夜月 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5134669f-2f36-4c7e-bf82-6534e429bf0e', '九日與楊凝崔淑期登江上山會有故不得往因贈之', '九日與楊凝崔淑期登江上山會有故不得往因贈之', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["欲從攜手登高去，一到門前意已無。","那得更將頭上髮，學他年少插茱萸。"]', '["欲從携手登高去，一到门前意已無。","那得更將头上髮，学他年少插茱萸。"]', '诗', 'shi', '', NULL, '九日與楊凝崔淑期登江上山會有故不得往因贈之 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4236519-05da-479b-978d-20afd9807dbc', '山中聽子規', '山中听子規', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["幽人自愛山中宿，又近葛洪丹井西。","窗中有箇長松樹，半夜子規來上啼。"]', '["幽人自愛山中宿，又近葛洪丹井西。","窗中有箇长松樹，半夜子規来上啼。"]', '诗', 'shi', '', NULL, '山中聽子規 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81c5f483-c429-41d1-b348-1f9edb94f1d9', '亂後經淮陰岸', '亂後經淮陰岸', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["荒村古岸誰家在，野水浮雲處處愁。","唯有河邊衰柳樹，蟬聲相送到揚州。"]', '["荒村古岸誰家在，野水浮云处处愁。","唯有河邊衰柳樹，蟬声相送到揚州。"]', '诗', 'shi', '', NULL, '亂後經淮陰岸 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96142aad-bfcb-4c04-b2af-19a9d834d365', '送張山人', '送張山人', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["知君住處足風煙，古寺荒村在眼前。","便欲移家逐君去，唯愁未有買山錢。"]', '["知君住处足风煙，古寺荒村在眼前。","便欲移家逐君去，唯愁未有買山錢。"]', '诗', 'shi', '', NULL, '送張山人 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('619f435c-0bff-4d9b-9961-6030b735d13c', '別李季蘭', '別李季蘭', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["古岸新花開一枝，岸傍花下有分離。","莫將羅袖拂花落，便是行人腸斷時。"]', '["古岸新花开一枝，岸傍花下有分離。","莫將羅袖拂花落，便是行人腸斷时。"]', '诗', 'shi', '', NULL, '別李季蘭 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e19d83c-cf9f-4a92-bf32-2dcddb1d280d', '遊石澗寺', '游石澗寺', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["聞道幽深石澗寺，不逢流水亦難知。","莫道山僧無伴侶，獼猴長在古松枝。"]', '["闻道幽深石澗寺，不逢流水亦难知。","莫道山僧無伴侶，獼猴长在古松枝。"]', '诗', 'shi', '', NULL, '遊石澗寺 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1409de04-8027-4732-b7a8-780bcbdcc33c', '新安所居答相訪人所居蕭使君爲制', '新安所居答相訪人所居蕭使君爲制', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["謝公見我多愁疾，爲我開門對碧山。","君若欲來看猿鳥，不須爭把桂枝攀。"]', '["謝公见我多愁疾，爲我开门对碧山。","君若欲来看猿鸟，不須爭把桂枝攀。"]', '诗', 'shi', '', NULL, '新安所居答相訪人所居蕭使君爲制 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f0393eb-6462-45a4-8fe1-c75794310dc2', '送魏校書', '送魏校书', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["長恨江南足別離，幾廻相送復相隨。","楊花撩亂撲流水，愁殺人行知不知。"]', '["长恨江南足別離，幾廻相送复相隨。","楊花撩亂撲流水，愁殺人行知不知。"]', '诗', 'shi', '', NULL, '送魏校書 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5ef3391-9223-4cdc-90c1-4479421166bb', '送溫台', '送溫台', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["眇眇天涯君去時，浮雲流水自相隨。","人生一世長如客，何必今朝是別離。"]', '["眇眇天涯君去时，浮云流水自相隨。","人生一世长如客，何必今朝是別離。"]', '诗', 'shi', '', NULL, '送溫台 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39dfdc61-5137-4cf1-9e16-810c09854ef4', '句', '句', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["愛彼雲外人，求取磵底泉。","風吹芭蕉拆，鳥啄梧桐落。"]', '["愛彼云外人，求取磵底泉。","风吹芭蕉拆，鸟啄梧桐落。"]', '诗', 'shi', '', NULL, '句 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96c2637f-6955-4d16-84da-d365ac65e6f6', '古意', '古意', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["蜀國春與秋，岷江朝夕流。","長波東接海，萬里至揚州。","開門面淮甸，楚俗饒歡宴。","舞榭黃金梯，歌樓白雲面。","蕩子未言歸，池塘月如練。"]', '["蜀国春與秋，岷江朝夕流。","长波东接海，万里至揚州。","开门面淮甸，楚俗饒歡宴。","舞榭黄金梯，歌楼白云面。","蕩子未言归，池塘月如練。"]', '诗', 'shi', '', NULL, '古意 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebdfb300-4a19-402b-8699-36651d5e1e5f', '塞下曲', '塞下曲', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["草枯馬蹄輕，角弓勁如石。","驕虜初欲來，風塵暗南國。","走檄召都尉，星火勦羌狄。","吾身許報主，何暇避鋒鏑。","白露濕鐵衣，半夜待攻擊。","龍沙早立功，名向燕然勒。"]', '["草枯马蹄轻，角弓勁如石。","驕虜初欲来，风塵暗南国。","走檄召都尉，星火勦羌狄。","吾身許報主，何暇避鋒鏑。","白露濕鐵衣，半夜待攻擊。","龙沙早立功，名向燕然勒。"]', '诗', 'shi', '', NULL, '塞下曲 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58e6bae1-ebe7-4d5c-95e9-15a1e3b2196d', '獨不見', '独不见', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["荆門一柱觀，楚國三休殿。","環珮儼神仙，輝光生顧盼。","春風細腰舞，明月高堂宴。","夢澤水連雲，渚宮花似霰。","俄驚白日晚，始悟炎涼變。","別島異波潮，離鴻分海縣。","南北斷相聞，歎嗟獨不見。"]', '["荆门一柱观，楚国三休殿。","环珮儼神仙，輝光生顧盼。","春风細腰舞，明月高堂宴。","梦澤水連云，渚宮花似霰。","俄驚白日晚，始悟炎涼变。","別島異波潮，離鴻分海縣。","南北斷相闻，歎嗟独不见。"]', '诗', 'shi', '', NULL, '獨不見 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4214d7ff-667b-4385-ac26-81484cf19ed2', '旬假南亭寄熊郎中', '旬假南亭寄熊郎中', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["旬休屏戎事，涼雨北窗眠。","江城一夜雨，萬里繞山川。","草木散幽氣，池塘鳴早蟬。","妍芳落春後，旅思生秋前。","紅槿粲庭豔，綠蒲繁渚煙。","行歌獨謠酌，坐發朱絲弦。","哀玉不可扣，華燭徒湛然。","聞君樂林臥，郡閣曠周旋。","酬對龍象侶，灌注清泠泉。","如何無礙智，猶苦病纏牽。"]', '["旬休屏戎事，涼雨北窗眠。","江城一夜雨，万里繞山川。","草木散幽氣，池塘鳴早蟬。","妍芳落春後，旅思生秋前。","紅槿粲庭豔，綠蒲繁渚煙。","行歌独謠酌，坐發朱絲弦。","哀玉不可扣，华燭徒湛然。","闻君乐林臥，郡閣曠周旋。","酬对龙象侶，灌注清泠泉。","如何無礙智，猶苦病纏牽。"]', '诗', 'shi', '', NULL, '旬假南亭寄熊郎中 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77e2e49f-c95f-4deb-84ba-4af7aab28da2', '晨興寄贈竇使君', '晨兴寄贈竇使君', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["江陵歲方晏，晨起眄庭柯。","白露傷紅葉，清風斷綠蘿。","徇時真氣索，念遠懷憂多。","夙昔樂山意，縱橫南浦波。","有美嬋娟子，百慮攢雙蛾。","緘情鬱不舒，幽行駢復羅。","爲予歌苦寒，酌酒朱顏酡。","世事浮雲變，功名將奈何。"]', '["江陵歲方晏，晨起眄庭柯。","白露傷紅葉，清风斷綠蘿。","徇时真氣索，念远懷憂多。","夙昔乐山意，縱橫南浦波。","有美嬋娟子，百慮攢雙蛾。","緘情鬱不舒，幽行駢复羅。","爲予歌苦寒，酌酒朱顏酡。","世事浮云变，功名將奈何。"]', '诗', 'shi', '', NULL, '晨興寄贈竇使君 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3d65f19-7b17-430e-b3c0-cbf69f2c27ff', '秋日對酒', '秋日对酒', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["行年過始衰，秋至獨先悲。","事往憐神魄，感深滋涕洟。","百憂紛在慮，一醉兀無思。","寶瑟拂麈匣，徽音凝朱絲。","幽圃蕙蘭氣，煙窗松桂姿。","我乏濟時略，杖節撫藩維。","山川大兵後，牢落空城池。","驚沙猶振野，綠草生荒陂。","物變風雨順，人懷天地慈。","春耕事秋戰，戎馬去封陲。","波瀾暗超忽，堅白亦磷緇。","客有自嵩潁，重徵棲隱期。","丹訣學仙晚，白雲歸谷遲。","君恩不可報，霜露繞南枝。"]', '["行年過始衰，秋至独先悲。","事往怜神魄，感深滋涕洟。","百憂紛在慮，一醉兀無思。","寶瑟拂麈匣，徽音凝朱絲。","幽圃蕙蘭氣，煙窗松桂姿。","我乏濟时略，杖節撫藩維。","山川大兵後，牢落空城池。","驚沙猶振野，綠草生荒陂。","物变风雨順，人懷天地慈。","春耕事秋戰，戎马去封陲。","波瀾暗超忽，堅白亦磷緇。","客有自嵩潁，重徵棲隐期。","丹訣学仙晚，白云归谷遲。","君恩不可報，霜露繞南枝。"]', '诗', 'shi', '', NULL, '秋日對酒 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d76f7632-9926-40d4-8ac2-497f7ca08223', '安邑里中秋懷寄高員外', '安邑里中秋懷寄高員外', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["原憲素非貧，嵇康自寡欲。","守道識通窮，達命齊榮辱。","庭梧變葱蒨，籬菊揚芳馥。","墜葉翻夕霜，高堂瞬華燭。","況茲寒夜永，復歎流年促。","感物思殷勤，懷賢心躑躅。","雄詞封禪草，麗句陽春曲。","高德十年兄，異才千里足。","咫尺邈雪霜，相望如瓊玉。","欲識歲寒心，松筠更秋綠。"]', '["原憲素非貧，嵇康自寡欲。","守道識通窮，達命齊榮辱。","庭梧变葱蒨，籬菊揚芳馥。","墜葉翻夕霜，高堂瞬华燭。","況茲寒夜永，复歎流年促。","感物思殷勤，懷賢心躑躅。","雄词封禪草，丽句陽春曲。","高德十年兄，異才千里足。","咫尺邈雪霜，相望如瓊玉。","欲識歲寒心，松筠更秋綠。"]', '诗', 'shi', '', NULL, '安邑里中秋懷寄高員外 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8184fda1-03e8-47cf-8d73-569079ec2c93', '送唐次', '送唐次', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["都門去馬嘶，灞水春流淺。","青槐驛路長，白日離尊晚。","望望煙景微，草色行人遠。"]', '["都门去马嘶，灞水春流淺。","青槐驛路长，白日離尊晚。","望望煙景微，草色行人远。"]', '诗', 'shi', '', NULL, '送唐次 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26246a65-c679-431b-8f2a-670769edb7b6', '秋夜雨中懷友', '秋夜雨中懷友', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["庭空雨鳴驕，天寒鴈啼苦。","青燈淡吐光，白髮悄無語。","幾年不與聯牀吟，君方客吳我猶楚。"]', '["庭空雨鳴驕，天寒鴈啼苦。","青灯淡吐光，白髮悄無語。","幾年不與聯牀吟，君方客吳我猶楚。"]', '诗', 'shi', '', NULL, '秋夜雨中懷友 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('401eb402-25a0-471d-a0d2-6c68d273d7ea', '望夫石', '望夫石', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["佳名望夫處，苔蘚封孤石。","萬里水連天，巴江暮雲碧。","湘妃泣下竹成斑，子規夜啼江樹白。"]', '["佳名望夫处，苔蘚封孤石。","万里水連天，巴江暮云碧。","湘妃泣下竹成斑，子規夜啼江樹白。"]', '诗', 'shi', '', NULL, '望夫石 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23fdcbe4-3063-481e-9807-89e47b6daf92', '行路難', '行路难', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["君不見道旁廢井傍開花，原是昔年驕貴家。","幾度美人來照影，濯纖笑引銀瓶綆。","風飄雨散今奈何，繡闥雕甍綠苔多。","笙歌鼎沸君莫矜，豪奢未必長多金。","休說編氓朴無耻，至竟終須合天理。","非故敗他却成此，蘇張終作多言鬼。","行路難，路難不在九折灣。"]', '["君不见道旁廢井傍开花，原是昔年驕貴家。","幾度美人来照影，濯纖笑引銀瓶綆。","风飄雨散今奈何，繡闥雕甍綠苔多。","笙歌鼎沸君莫矜，豪奢未必长多金。","休说編氓朴無耻，至竟終須合天理。","非故敗他却成此，蘇張終作多言鬼。","行路难，路难不在九折灣。"]', '诗', 'shi', '', NULL, '行路難 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb602c4f-bdaa-4fea-9d77-147baac66358', '長相思', '长相思', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["長相思，隴雲愁，單于臺上望伊州。","鴈書絕，蟬鬢秋。","行人天一畔，暮雨海西頭。","殷勤大河水，東注不還流。"]', '["长相思，隴云愁，單于台上望伊州。","鴈书絕，蟬鬢秋。","行人天一畔，暮雨海西头。","殷勤大河水，东注不還流。"]', '诗', 'shi', '', NULL, '長相思 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b56e203-9c57-4ea7-b337-b174f9a00c95', '出塞作', '出塞作', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["夙駕逾人境，長驅出塞垣。","邊風引去騎，胡沙拂征轅。","奏笳山月白，結陣瘴雲昏。","雖云風景異華夏，亦喜地理通樓煩。","白羽矢飛先火礮，黃金甲耀奪朝暾。","要須灑掃龍沙淨，歸謁明光一報恩。"]', '["夙駕逾人境，长驱出塞垣。","邊风引去騎，胡沙拂征轅。","奏笳山月白，結陣瘴云昏。","雖云风景異华夏，亦喜地理通楼煩。","白羽矢飞先火礮，黄金甲耀奪朝暾。","要須灑掃龙沙淨，归謁明光一報恩。"]', '诗', 'shi', '', NULL, '出塞作 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecfeec5e-3205-401e-bc5d-e9b58efb9031', '桃源行送友', '桃源行送友', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["武陵川徑入幽遐，中有雞犬秦人家，家傍流水多桃花。","桃花兩邊種來久，流水一通何時有。","垂條落蘂暗春風，夾岸芳菲至山口。","歲歲年年能寂寥，林下青苔日爲厚。","時有仙鳥來銜花，曾無世人此攜手。","可憐不知若爲名，君往從之多所更。","古驛荒橋平路盡，崩湍怪石小溪行。","相見維舟登覽處，紅堤綠岸宛然成。","多君此去從仙隱，令人晚節悔營營。"]', '["武陵川徑入幽遐，中有雞犬秦人家，家傍流水多桃花。","桃花兩邊種来久，流水一通何时有。","垂條落蘂暗春风，夾岸芳菲至山口。","歲歲年年能寂寥，林下青苔日爲厚。","时有仙鸟来銜花，曾無世人此携手。","可怜不知若爲名，君往從之多所更。","古驛荒橋平路尽，崩湍怪石小溪行。","相见維舟登覽处，紅堤綠岸宛然成。","多君此去從仙隐，令人晚節悔營營。"]', '诗', 'shi', '', NULL, '桃源行送友 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afb30a0c-422f-4656-b0bb-90174c0d3d1f', '長安敘懷寄崔十五', '长安敘懷寄崔十五', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["延首直城西，花飛綠草齊。","迢遙隔山水，悵望思遊子。","百囀黃鸝細雨中，千條翠柳衡門裏。","門對長安九衢路，愁心不惜芳菲度。","風塵冉冉秋復春，鐘鼓喧喧朝復暮。","漢家宮闕在中天，紫陌朝臣車馬連。","蕭蕭霓旌合仙杖，悠悠劍佩入爐煙。","李廣少時思報國，終軍未遇敢論邊。","無媒守儒行，榮悴紛相映。","家甚長卿貧，身多公幹病。","不知身病竟如何，嬾向青山眠薜蘿。","雞黍空多元伯惠，琴書不見子猷過。","超名累歲與君同，自歎還隨鷁退風。","聞說唐生子孫在，何當一爲問窮通。"]', '["延首直城西，花飞綠草齊。","迢遙隔山水，悵望思游子。","百囀黄鸝細雨中，千條翠柳衡门裏。","门对长安九衢路，愁心不惜芳菲度。","风塵冉冉秋复春，鐘鼓喧喧朝复暮。","漢家宮闕在中天，紫陌朝臣车马連。","蕭蕭霓旌合仙杖，悠悠劍佩入爐煙。","李廣少时思報国，終軍未遇敢論邊。","無媒守儒行，榮悴紛相映。","家甚长卿貧，身多公幹病。","不知身病竟如何，嬾向青山眠薜蘿。","雞黍空多元伯惠，琴书不见子猷過。","超名累歲與君同，自歎還隨鷁退风。","闻说唐生子孫在，何當一爲问窮通。"]', '诗', 'shi', '', NULL, '長安敘懷寄崔十五 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0cc0807-e34e-40a0-87db-14a46aa351e4', '兵行褒斜谷作', '兵行褒斜谷作', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["古地接龜沙，邊風送征鴈。","霜明草正腓，峰逼日易晏。","集旅布嵌谷，驅馬歷層澗。","岷河源涉屢，蜀甸途行慣。","矢橐弧室豈領軍，儋爵食祿由從宦。","注意奏凱赴都畿，速令提兵還石坂。","三川頓使氣象清，賣刀買犢消憂患。"]', '["古地接龟沙，邊风送征鴈。","霜明草正腓，峰逼日易晏。","集旅布嵌谷，驱马歷層澗。","岷河源涉屢，蜀甸途行慣。","矢橐弧室豈領軍，儋爵食祿由從宦。","注意奏凱赴都畿，速令提兵還石坂。","三川頓使氣象清，賣刀買犢消憂患。"]', '诗', 'shi', '', NULL, '兵行褒斜谷作 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83f707b8-0404-464e-94dd-2ab8ba345ed9', '西亭早秋送徐員外', '西亭早秋送徐員外', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["鼎鉉辭台座，麾幢領益州。","曲池連月曉，橫角滿城秋。","有美皇華使，曾同白社遊。","今年重相見，偏覺豔歌愁。"]', '["鼎鉉辞台座，麾幢領益州。","曲池連月晓，橫角满城秋。","有美皇华使，曾同白社游。","今年重相见，偏覺豔歌愁。"]', '诗', 'shi', '', NULL, '西亭早秋送徐員外 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('364673e8-596d-48fe-88bd-87dd2d433947', '送徐員外還京', '送徐員外還京', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["九折朱輪動，三巴白露生。","蕙蘭秋意晚，關塞別魂驚。","寶瑟連宵怨，金罍盡醉傾。","旄頭星未落，分手轆轤鳴。"]', '["九折朱輪动，三巴白露生。","蕙蘭秋意晚，关塞別魂驚。","寶瑟連宵怨，金罍尽醉傾。","旄头星未落，分手轆轤鳴。"]', '诗', 'shi', '', NULL, '送徐員外還京 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3619812f-2589-4209-a9c3-e23163d5632a', '送柳郎中裴起居', '送柳郎中裴起居', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["沱江水綠波，喧鳥去喬柯。","南浦別離處，東風蘭杜多。","長亭春婉娩，層漢路蹉跎。","會有歸朝日，班超奈老何。"]', '["沱江水綠波，喧鸟去喬柯。","南浦別離处，东风蘭杜多。","长亭春婉娩，層漢路蹉跎。","會有归朝日，班超奈老何。"]', '诗', 'shi', '', NULL, '送柳郎中裴起居 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91a1ff6c-4cf8-497f-8c79-2e5f9a997e9d', '八月十五酬從兄常望月有懷', '八月十五酬從兄常望月有懷', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["坐愛圓景滿，況茲秋夜長。","寒光生露草，夕韻出風篁。","地遠驚金奏，天高失鴈行。","如何北樓望，不得共池塘。"]', '["坐愛圓景满，況茲秋夜长。","寒光生露草，夕韻出风篁。","地远驚金奏，天高失鴈行。","如何北楼望，不得共池塘。"]', '诗', 'shi', '', NULL, '八月十五酬從兄常望月有懷 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87a501b5-58c6-40d4-a1bd-ad8319227268', '酬太常從兄留別', '酬太常從兄留別', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["鄉路日茲始，征軒行復留。","張騫隨漢節，王濬守刀州。","澤國煙花度，銅梁霧雨愁。","別離無可奈，萬恨錦江流。"]', '["乡路日茲始，征軒行复留。","張騫隨漢節，王濬守刀州。","澤国煙花度，銅梁霧雨愁。","別離無可奈，万恨錦江流。"]', '诗', 'shi', '', NULL, '酬太常從兄留別 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('680c2d30-359c-475e-8e95-069f7018fdb0', '春日與諸公汎舟', '春日與諸公汎舟', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["千里雪山開，沱江春水來。","駐帆雲縹緲，吹管鶴裴回。","身外流年駛，尊前落景催。","不應歸棹遠，明月在高臺。"]', '["千里雪山开，沱江春水来。","駐帆云縹緲，吹管鹤裴回。","身外流年駛，尊前落景催。","不應归棹远，明月在高台。"]', '诗', 'shi', '', NULL, '春日與諸公汎舟 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fc80155-a4b9-42e8-a28e-492b621dfbe2', '送兄歸洛使謁嚴司空', '送兄归洛使謁嚴司空', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["六歲蜀城守，千莖蓬鬢絲。","憂心不自遣，骨肉又傷離。","楚峽饒雲雨，巴江足夢思。","殷勤孔北海，時節易流移。"]', '["六歲蜀城守，千莖蓬鬢絲。","憂心不自遣，骨肉又傷離。","楚峽饒云雨，巴江足梦思。","殷勤孔北海，时節易流移。"]', '诗', 'shi', '', NULL, '送兄歸洛使謁嚴司空 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f2ba0af-e9ae-4140-90f9-a023c565867a', '同洛陽諸公餞盧起居', '同洛陽諸公餞盧起居', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["蕭條寒日晏，悽慘別魂驚。","寶瑟無聲怨，金囊故贈輕。","赤墀方載筆，油幕尚言兵。","暮宿青泥驛，煩君淚滿纓。"]', '["蕭條寒日晏，悽慘別魂驚。","寶瑟無声怨，金囊故贈轻。","赤墀方載笔，油幕尚言兵。","暮宿青泥驛，煩君泪满纓。"]', '诗', 'shi', '', NULL, '同洛陽諸公餞盧起居 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a509b7e-925b-4491-adea-fc0ad238486c', '臺中題壁', '台中題壁', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["柏臺年未老，蓬鬢忽蒼蒼。","無事裨明主，何心弄憲章。","雀聲愁霰雪，鴻思恨關梁。","會脫簪纓去，故山瑤草芳。"]', '["柏台年未老，蓬鬢忽蒼蒼。","無事裨明主，何心弄憲章。","雀声愁霰雪，鴻思恨关梁。","會脫簪纓去，故山瑤草芳。"]', '诗', 'shi', '', NULL, '臺中題壁 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a44e09a-a28d-49b8-849f-33cb5d4c4d1e', '江上寄隱者', '江上寄隐者', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["歸舟不計程，江月屢虧盈。","靄靄滄波路，悠悠離別情。","蒹葭連水國，鼙鼓近梁城。","却憶沿江叟，汀洲春草生。"]', '["归舟不計程，江月屢虧盈。","靄靄滄波路，悠悠離別情。","蒹葭連水国，鼙鼓近梁城。","却憶沿江叟，汀洲春草生。"]', '诗', 'shi', '', NULL, '江上寄隱者 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73c79950-a19d-4340-aa2f-71af524cae13', '送嚴紳遊蘭溪', '送嚴紳游蘭溪', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["剡嶺窮邊海，君遊別嶺西。","暮雲秋水闊，寒雨夜猿啼。","地僻秦人少，山多越路迷。"]', '["剡嶺窮邊海，君游別嶺西。","暮云秋水闊，寒雨夜猿啼。","地僻秦人少，山多越路迷。"]', '诗', 'shi', '', NULL, '送嚴紳遊蘭溪 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5849dc58-0b5b-4181-ad61-285eb6ca25f5', '秋思', '秋思', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["秋室浩煙霧，風柳怨寒蜩。","機杼夜聲切，蕙蘭芳意消。","美人湘水曲，桂檝洞庭遙。","常恐時光謝，蹉跎紅豔凋。"]', '["秋室浩煙霧，风柳怨寒蜩。","機杼夜声切，蕙蘭芳意消。","美人湘水曲，桂檝洞庭遙。","常恐时光謝，蹉跎紅豔凋。"]', '诗', 'shi', '', NULL, '秋思 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f63732c-24f6-45ec-804b-b183463f66dc', '夏日別盧太卿', '夏日別盧太卿', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["漢水清且廣，江波渺復深。","葉舟煙雨夜，之子別離心。","汀草結春怨，山雲連暝陰。","年年南北淚，今古共霑襟。"]', '["漢水清且廣，江波渺复深。","葉舟煙雨夜，之子別離心。","汀草結春怨，山云連暝陰。","年年南北泪，今古共霑襟。"]', '诗', 'shi', '', NULL, '夏日別盧太卿 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87184327-e070-4689-b718-15d9213fd8b4', '西亭題壁寄中書李相公', '西亭題壁寄中书李相公', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["昏旦倦興寢，端憂力尚微。","廉頗不覺老，蘧瑗始知非。","授鉞虛三顧，持衡曠萬機。","空餘蝴蝶夢，迢遰故山歸。"]', '["昏旦倦兴寢，端憂力尚微。","廉頗不覺老，蘧瑗始知非。","授鉞虛三顧，持衡曠万機。","空餘蝴蝶梦，迢遰故山归。"]', '诗', 'shi', '', NULL, '西亭題壁寄中書李相公 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('062b7acd-b84f-4fe3-a61f-27d5123ac326', '八月十五夜與諸公錦樓望月得中字', '八月十五夜與諸公錦楼望月得中字', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["玉輪初滿空，迥出錦城東。","相向秦樓鏡，分飛碣石鴻。","桂香隨窈窕，珠綴隔玲瓏。","不及前秋月，圓輝鳳沼中。"]', '["玉輪初满空，迥出錦城东。","相向秦楼镜，分飞碣石鴻。","桂香隨窈窕，珠綴隔玲瓏。","不及前秋月，圓輝鳳沼中。"]', '诗', 'shi', '', NULL, '八月十五夜與諸公錦樓望月得中字 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36b74977-35c1-4475-b261-5327f9bdcae0', '四川使宅有韋令公時孔雀存焉暇日與諸公同翫座中兼故府賓妓興嗟久之因賦此詩用廣其意', '四川使宅有韋令公时孔雀存焉暇日與諸公同翫座中兼故府賓妓兴嗟久之因賦此诗用廣其意', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["荀令昔居此，故巢留越禽。","動搖金翠尾，飛舞碧梧陰。","上客徹瑤瑟，美人傷蕙心。","會因南國使，得放海雲深。"]', '["荀令昔居此，故巢留越禽。","动搖金翠尾，飞舞碧梧陰。","上客徹瑤瑟，美人傷蕙心。","會因南国使，得放海云深。"]', '诗', 'shi', '', NULL, '四川使宅有韋令公時孔雀存焉暇日與諸公同翫座中兼故府賓妓興嗟久之因賦此詩用廣其意 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1332edf-9a0b-4b95-8ea7-ea76bf7f6fa5', '竇三中丞去歲有臺中五言四韻未及酬報今領黔南途經蜀門百里而近願言欵覿封略間然因追曩篇持以贈之', '竇三中丞去歲有台中五言四韻未及酬報今領黔南途經蜀门百里而近願言欵覿封略间然因追曩篇持以贈之', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["在昔謬司憲，常僚惟有君。","報恩如皎日，致位等青雲。","削藁書難見，除苛事早吟。","雙旌不可駐，風雪路岐分。"]', '["在昔謬司憲，常僚惟有君。","報恩如皎日，致位等青云。","削藁书难见，除苛事早吟。","雙旌不可駐，风雪路岐分。"]', '诗', 'shi', '', NULL, '竇三中丞去歲有臺中五言四韻未及酬報今領黔南途經蜀門百里而近願言欵覿封略間然因追曩篇持以贈之 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a9e9484-43c6-4426-91d3-bd3525ff18e0', '春分與諸公同宴呈陸三十四郎中', '春分與諸公同宴呈陸三十四郎中', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["南國宴佳賓，交情老倍親。","月慙紅燭淚，花笑白頭人。","寶瑟常餘怨，瓊枝不讓春。","更聞歌子夜，桃李豔妝新。"]', '["南国宴佳賓，交情老倍親。","月慙紅燭泪，花笑白头人。","寶瑟常餘怨，瓊枝不讓春。","更闻歌子夜，桃李豔妝新。"]', '诗', 'shi', '', NULL, '春分與諸公同宴呈陸三十四郎中 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1273143-471c-408a-aa03-3880e9c4b6bd', '津梁寺採新茶與幕中諸公遍賞芳香尤異因題四韻兼呈陸郎中', '津梁寺採新茶與幕中諸公遍賞芳香尤異因題四韻兼呈陸郎中', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["靈州碧巖下，荑英初散芳。","塗塗猶宿露，采采不盈筐。","陰竇藏煙濕，單衣染焙香。","幸將調鼎味，一爲奏明光。"]', '["靈州碧巖下，荑英初散芳。","塗塗猶宿露，采采不盈筐。","陰竇藏煙濕，單衣染焙香。","幸將調鼎味，一爲奏明光。"]', '诗', 'shi', '', NULL, '津梁寺採新茶與幕中諸公遍賞芳香尤異因題四韻兼呈陸郎中 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('110c9e6d-a4d8-4d69-ba7d-f6382955c10b', '元和癸巳余領蜀之七年奉詔徴還二月二十八日清明途經百牢關因題石門洞', '元和癸巳余領蜀之七年奉詔徴還二月二十八日清明途經百牢关因題石门洞', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["昔佩兵符去，今持相印還。","天光臨井絡，春物度巴山。","鳥道青冥外，風泉洞壑間。","何慙班定遠，辛苦玉門關。"]', '["昔佩兵符去，今持相印還。","天光臨井絡，春物度巴山。","鸟道青冥外，风泉洞壑间。","何慙班定远，辛苦玉门关。"]', '诗', 'shi', '', NULL, '元和癸巳余領蜀之七年奉詔徴還二月二十八日清明途經百牢關因題石門洞 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21461387-1e42-4761-8936-ee3ae85b549d', '夕次潘山下', '夕次潘山下', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["南國獨行日，三巴春草齊。","漾波歸海疾，危棧入雲迷。","錦谷嵐煙裏，刀州晚照西。","旅情方浩蕩，蜀魄滿林啼。"]', '["南国独行日，三巴春草齊。","漾波归海疾，危棧入云迷。","錦谷嵐煙裏，刀州晚照西。","旅情方浩蕩，蜀魄满林啼。"]', '诗', 'shi', '', NULL, '夕次潘山下 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fc09639-9e38-402f-9827-589c1cc161ff', '夏日對雨寄朱放拾遺', '夏日对雨寄朱放拾遺', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["才非谷永傳，無意謁王侯。","小暑金將伏，微涼麥正秋。","遠山欹枕見，暮雨閉門愁。","更憶東林寺，詩家第一流。"]', '["才非谷永傳，無意謁王侯。","小暑金將伏，微涼麦正秋。","远山欹枕见，暮雨閉门愁。","更憶东林寺，诗家第一流。"]', '诗', 'shi', '', NULL, '夏日對雨寄朱放拾遺 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('953887a3-ceb3-460f-b178-499ba1b1f0b8', '早春送歐陽鍊師歸山', '早春送歐陽鍊師归山', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["雙鶴五雲車，初辭漢帝家。","人寰新甲子，天路舊煙霞。","羽節臨風駐，霓裳逐雨斜。","崑崙有琪樹，相憶寄瑤華。"]', '["雙鹤五云车，初辞漢帝家。","人寰新甲子，天路旧煙霞。","羽節臨风駐，霓裳逐雨斜。","崑崙有琪樹，相憶寄瑤华。"]', '诗', 'shi', '', NULL, '早春送歐陽鍊師歸山 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d506e1b-6e66-4c4e-907f-8347430a7594', '長安春望', '长安春望', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["宿雨淨煙霞，春風綻百花。","綠楊中禁路，朱戟五侯家。","草色金隄晚，鶯聲御柳斜。","無媒猶未達，應共惜年華。"]', '["宿雨淨煙霞，春风綻百花。","綠楊中禁路，朱戟五侯家。","草色金隄晚，鶯声御柳斜。","無媒猶未達，應共惜年华。"]', '诗', 'shi', '', NULL, '長安春望 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8833b8b1-067f-4b02-bf16-4315e7df3d5e', '經嚴祕校維故宅', '經嚴祕校維故宅', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["掩淚山陽宅，生涯此路窮。","香銷芸閣閉，星落草堂空。","麗藻浮名裏，哀聲夕照中。","不堪投釣處，隣笛怨春風。"]', '["掩泪山陽宅，生涯此路窮。","香銷芸閣閉，星落草堂空。","丽藻浮名裏，哀声夕照中。","不堪投釣处，隣笛怨春风。"]', '诗', 'shi', '', NULL, '經嚴祕校維故宅 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5435aa2-b351-4a3e-9035-5aab719775f0', '秋夜寄江南舊遊', '秋夜寄江南旧游', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["寥落九秋晚，端憂時物殘。","隔林螢影度，出禁漏聲寒。","愁雨洞房掩，孤燈遙夜闌。","懷賢夢南國，興盡水漫漫。"]', '["寥落九秋晚，端憂时物殘。","隔林螢影度，出禁漏声寒。","愁雨洞房掩，孤灯遙夜闌。","懷賢梦南国，兴尽水漫漫。"]', '诗', 'shi', '', NULL, '秋夜寄江南舊遊 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30963db0-027c-4aa1-8627-c4312bde6991', '送陸書還吳', '送陸书還吳', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["君住包山下，何年入帝鄉。","成名歸舊業，歎別見秋光。","橘柚吳洲遠，蘆花楚水長。","我行經此路，京口向雲陽。"]', '["君住包山下，何年入帝乡。","成名归旧業，歎別见秋光。","橘柚吳洲远，蘆花楚水长。","我行經此路，京口向云陽。"]', '诗', 'shi', '', NULL, '送陸書還吳 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d2c1165-a191-4109-9b8d-8d0afd1e773c', '山中月夜寄朱張二舍人', '山中月夜寄朱張二舍人', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["午夜更漏裏，九重霄漢間。","月華雲闕迥，秋色鳳池閑。","御錦通清禁，天書出暗關。","嵇康不求達，終歲在空山。"]', '["午夜更漏裏，九重霄漢间。","月华云闕迥，秋色鳳池闲。","御錦通清禁，天书出暗关。","嵇康不求達，終歲在空山。"]', '诗', 'shi', '', NULL, '山中月夜寄朱張二舍人 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e37763c5-6ff1-4e3f-b562-1f8f473ae119', '送馮諫議赴河北宣慰', '送馮諫議赴河北宣慰', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["漢代衣冠盛，堯年雨露多。","恩榮辭紫禁，冰雪渡黃河。","待詔孤城啓，宣風萬歲和。","今宵燕分野，應見使星過。"]', '["漢代衣冠盛，堯年雨露多。","恩榮辞紫禁，冰雪渡黄河。","待詔孤城啓，宣风万歲和。","今宵燕分野，應见使星過。"]', '诗', 'shi', '', NULL, '送馮諫議赴河北宣慰 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86958501-1766-4e82-9993-4f6958a5830c', '夜坐聞雨寄嚴十少府', '夜坐闻雨寄嚴十少府', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["多負雲霄志，生涯歲序侵。","風翻涼葉亂，雨滴洞房深。","迢遰三秋夢，殷勤獨夜心。","懷賢不覺寐，清磬發東林。"]', '["多負云霄志，生涯歲序侵。","风翻涼葉亂，雨滴洞房深。","迢遰三秋梦，殷勤独夜心。","懷賢不覺寐，清磬發东林。"]', '诗', 'shi', '', NULL, '夜坐聞雨寄嚴十少府 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c698e805-b9af-4674-9526-4cfe5df6217c', '資聖寺賁法師晚春茶會', '資聖寺賁法師晚春茶會', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["虛室晝常掩，心源知悟空。","禪庭一雨後，蓮界萬花中。","時節流芳暮，人天此會同。","不知方便理，何路出樊籠。"]', '["虛室晝常掩，心源知悟空。","禪庭一雨後，蓮界万花中。","时節流芳暮，人天此會同。","不知方便理，何路出樊籠。"]', '诗', 'shi', '', NULL, '資聖寺賁法師晚春茶會 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0d6e3cd-5aeb-4b92-9548-2eb6da3ed0f0', '慈恩寺起上人院', '慈恩寺起上人院', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["禪堂支許同，清論道源窮。","起滅秋雲盡，虛無夕靄空。","池澄山倒影，林動葉翻風。","他日焚香待，還來禮惠聰。"]', '["禪堂支許同，清論道源窮。","起滅秋云尽，虛無夕靄空。","池澄山倒影，林动葉翻风。","他日焚香待，還来禮惠聰。"]', '诗', 'shi', '', NULL, '慈恩寺起上人院 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97c270ca-9b1d-46f7-a349-c2650b0828de', '送魏正則擢第歸江陵', '送魏正則擢第归江陵', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["客路商山外，離筵小暑前。","高文常獨步，折桂及齠年。","關國通秦限，波濤隔漢川。","叨同會府選，分手倍依然。"]', '["客路商山外，離筵小暑前。","高文常独步，折桂及齠年。","关国通秦限，波濤隔漢川。","叨同會府選，分手倍依然。"]', '诗', 'shi', '', NULL, '送魏正則擢第歸江陵 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c4dde49-e849-405e-8587-caa4ae37af11', '酬韓弇歸崖見寄', '酬韓弇归崖见寄', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["惆悵人間事，東山遂獨遊。","露凝瑤草晚，魚戲石潭秋。","軒冕應相待，煙霞莫遽留。","君看仲連意，功立始滄洲。"]', '["惆悵人间事，东山遂独游。","露凝瑤草晚，鱼戲石潭秋。","軒冕應相待，煙霞莫遽留。","君看仲連意，功立始滄洲。"]', '诗', 'shi', '', NULL, '酬韓弇歸崖見寄 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d044cf9f-c166-47c0-bd58-e9124cb2900b', '河東贈別鍊師', '河东贈別鍊師', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["多累有行役，相逢秋節分。","游人甘失路，野鶴亦離羣。","戎馬犯邊壘，天兵屯塞雲。","孔璋才素健，羽檄定紛紛。"]', '["多累有行役，相逢秋節分。","游人甘失路，野鹤亦離羣。","戎马犯邊壘，天兵屯塞云。","孔璋才素健，羽檄定紛紛。"]', '诗', 'shi', '', NULL, '河東贈別鍊師 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cba6cf4f-5a8d-45a7-ad4a-c84ab053b9c1', '秋日將赴江上楊弘微時任鳳翔寄詩別', '秋日將赴江上楊弘微时任鳳翔寄诗別', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["寂寞兩相阻，悠悠南北心。","燕驚滄海遠，鴻避朔雲深。","夜夢江亭月，離憂隴樹陰。","兼秋無限思，惆悵屬瑤琴。"]', '["寂寞兩相阻，悠悠南北心。","燕驚滄海远，鴻避朔云深。","夜梦江亭月，離憂隴樹陰。","兼秋無限思，惆悵屬瑤琴。"]', '诗', 'shi', '', NULL, '秋日將赴江上楊弘微時任鳳翔寄詩別 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b3e5eb5-cd73-4302-a588-c1a9c2f50299', '夏與熊王二秀才同宿僧院', '夏與熊王二秀才同宿僧院', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["共將纓上塵，來問雪山人。","世網從知累，禪心自證真。","境空宜入夢，藤古不留春。","一聽林公法，靈嘉願寄身。"]', '["共將纓上塵，来问雪山人。","世網從知累，禪心自證真。","境空宜入梦，藤古不留春。","一听林公法，靈嘉願寄身。"]', '诗', 'shi', '', NULL, '夏與熊王二秀才同宿僧院 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5242c06-b49d-4162-b1bc-ad478bfb6686', '宜陽所居白蜀葵荅詠柬諸公', '宜陽所居白蜀葵荅詠柬諸公', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["冉冉衆芳歇，亭亭虛室前。","敷榮時已背，幽賞地宜偏。","紅豔世方重，素華徒可憐。","何當君子願，知不競喧妍。"]', '["冉冉衆芳歇，亭亭虛室前。","敷榮时已背，幽賞地宜偏。","紅豔世方重，素华徒可怜。","何當君子願，知不競喧妍。"]', '诗', 'shi', '', NULL, '宜陽所居白蜀葵荅詠柬諸公 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7e7bd1f-e3b7-40f8-8fb2-08539c80acbe', '送寇侍御司馬之明州', '送寇侍御司马之明州', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["斗酒上河梁，驚魂去越鄉。","地窮滄海闊，雲入剡山長。","蓮唱蒲萄熟，人煙橘柚香。","蘭亭應駐楫，今古共風光。"]', '["斗酒上河梁，驚魂去越乡。","地窮滄海闊，云入剡山长。","蓮唱蒲萄熟，人煙橘柚香。","蘭亭應駐楫，今古共风光。"]', '诗', 'shi', '', NULL, '送寇侍御司馬之明州 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a964c4bd-9c7b-4294-94b4-51e0ee5e20b0', '送嚴侍御', '送嚴侍御', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["巴檄故人去，蒼蒼楓樹林。","雲山千里合，霧雨四時陰。","峽路猨聲斷，桃源犬吠深。","不須貪勝賞，漢節待南侵。"]', '["巴檄故人去，蒼蒼楓樹林。","云山千里合，霧雨四时陰。","峽路猨声斷，桃源犬吠深。","不須貪勝賞，漢節待南侵。"]', '诗', 'shi', '', NULL, '送嚴侍御 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64e805a4-12a0-40f9-afd1-3a94aefca0a4', '酬元十二', '酬元十二', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["偶尋烏府客，同醉習家池。","積雪初迷徑，孤雲遂失期。","風前勞引領，月下重相思。","何必因尊酒，幽心兩自知。"]', '["偶尋烏府客，同醉習家池。","積雪初迷徑，孤云遂失期。","风前勞引領，月下重相思。","何必因尊酒，幽心兩自知。"]', '诗', 'shi', '', NULL, '酬元十二 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c43f117-eb55-4a6e-b931-45e7c65dce39', '秋晚途次坊州界寄崔玉員外', '秋晚途次坊州界寄崔玉員外', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["崎嶇崖谷迷，寒雨暮成泥。","征路出山頂，亂雲生馬蹄。","望鄉程杳杳，懷遠思悽悽。","欲識分麾重，孤城萬壑西。"]', '["崎嶇崖谷迷，寒雨暮成泥。","征路出山頂，亂云生马蹄。","望乡程杳杳，懷远思悽悽。","欲識分麾重，孤城万壑西。"]', '诗', 'shi', '', NULL, '秋晚途次坊州界寄崔玉員外 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05009d88-f526-447a-b90f-4bb0bf358429', '度東徑嶺', '度东徑嶺', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["又過鴈門北，不勝南客悲。","三邊上巖見，雙淚望鄉垂。","暮角雲中戍，殘陽天際旗。","更看飛白羽，胡馬在封陲。"]', '["又過鴈门北，不勝南客悲。","三邊上巖见，雙泪望乡垂。","暮角云中戍，殘陽天際旗。","更看飞白羽，胡马在封陲。"]', '诗', 'shi', '', NULL, '度東徑嶺 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b3c5a9c-fc55-465e-a297-f097c787f0c6', '送李正字之蜀', '送李正字之蜀', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["已獻甘泉賦，仍登片玉科。","漢官新組綬，蜀國舊煙蘿。","劒壁秋雲斷，巴江夜月多。","無窮別離思，遙寄竹枝歌。"]', '["已獻甘泉賦，仍登片玉科。","漢官新組綬，蜀国旧煙蘿。","劒壁秋云斷，巴江夜月多。","無窮別離思，遙寄竹枝歌。"]', '诗', 'shi', '', NULL, '送李正字之蜀 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d3e991c-f883-4233-98b7-20da065f8e1c', '玉泉寺與潤上人望秋山懷張少尹', '玉泉寺與潤上人望秋山懷張少尹', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["山寒天降霜，煙月共蒼蒼。","況此綠巖晚，尚餘丹桂芳。","禪心殊衆樂，人世滿秋光。","莫怪頻回首，孤雲思帝鄉。"]', '["山寒天降霜，煙月共蒼蒼。","況此綠巖晚，尚餘丹桂芳。","禪心殊衆乐，人世满秋光。","莫怪頻回首，孤云思帝乡。"]', '诗', 'shi', '', NULL, '玉泉寺與潤上人望秋山懷張少尹 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('270f49d1-7cec-4cd8-8638-b6db2913228a', '酬崔使君寄麈尾', '酬崔使君寄麈尾', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["賢人嘉尚同，今製古遺風。","寄我襟懷裏，辭君掌握中。","金聲勞振遠，玉柄借談空。","執玩馳心處，迢迢巴峽東。"]', '["賢人嘉尚同，今製古遺风。","寄我襟懷裏，辞君掌握中。","金声勞振远，玉柄借談空。","執玩驰心处，迢迢巴峽东。"]', '诗', 'shi', '', NULL, '酬崔使君寄麈尾 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fcda882-c433-461b-9dee-3a85a1156d1b', '送鄧州潘使君赴任', '送鄧州潘使君赴任', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["川陸一都會，旌旗千里舒。","虎符中禁授，熊軾上流居。","橘柚金難並，池塘練不如。","春風行部日，應駐士元車。"]', '["川陸一都會，旌旗千里舒。","虎符中禁授，熊軾上流居。","橘柚金难並，池塘練不如。","春风行部日，應駐士元车。"]', '诗', 'shi', '', NULL, '送鄧州潘使君赴任 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6772b365-5daf-4975-9989-621aa7c0d99b', '和李中丞題故將軍林亭', '和李中丞題故將軍林亭', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["帝里清和節，侯家邸第春。","煙霏瑤草露，苔暗杏梁塵。","城郭悲歌舊，池塘麗句新。","年年車馬客，鐘鼓樂他人。"]', '["帝里清和節，侯家邸第春。","煙霏瑤草露，苔暗杏梁塵。","城郭悲歌旧，池塘丽句新。","年年车马客，鐘鼓乐他人。"]', '诗', 'shi', '', NULL, '和李中丞題故將軍林亭 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3622e042-00ac-4616-a5fb-438d5570defe', '送韋侍御司議赴東都', '送韋侍御司議赴东都', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["洛京千里近，離緒亦紛紛。","文憲芙蓉沼，元方羔鴈羣。","河關連鞏樹，嵩少接秦雲。","獨有臨風思，睽攜不可聞。"]', '["洛京千里近，離緒亦紛紛。","文憲芙蓉沼，元方羔鴈羣。","河关連鞏樹，嵩少接秦云。","独有臨风思，睽携不可闻。"]', '诗', 'shi', '', NULL, '送韋侍御司議赴東都 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dc15e9a-78d4-4f51-8a43-dfa771be0d59', '送吳侍御司馬赴台州', '送吳侍御司马赴台州', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["盧耽佐郡遙，川陸共迢迢。","風景輕吳會，文章變越謠。","煙林繁橘柚，雲海浩波潮。","余有靈山夢，前君到石橋。"]', '["盧耽佐郡遙，川陸共迢迢。","风景轻吳會，文章变越謠。","煙林繁橘柚，云海浩波潮。","余有靈山梦，前君到石橋。"]', '诗', 'shi', '', NULL, '送吳侍御司馬赴台州 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1880dfff-1b23-4609-af56-9b9a4904552e', '送七兄赴歙州', '送七兄赴歙州', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["車馬去憧憧，都門聞曉鐘。","客程將日遠，離緒與春濃。","流水踰千度，歸雲隔萬重。","玉杯傾酒盡，不換慘悽容。"]', '["车马去憧憧，都门闻晓鐘。","客程將日远，離緒與春濃。","流水踰千度，归云隔万重。","玉杯傾酒尽，不換慘悽容。"]', '诗', 'shi', '', NULL, '送七兄赴歙州 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('329663b5-4641-4a41-8f0a-106406d9592f', '德宗皇帝挽歌詞三首 一', '德宗皇帝挽歌词三首 一', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["道啓軒皇聖，威揚夏禹功。","謳歌亭育外，文武盛明中。","日月光連璧，煙塵屏大風。","爲人祈福處，臺樹與天通。"]', '["道啓軒皇聖，威揚夏禹功。","謳歌亭育外，文武盛明中。","日月光連璧，煙塵屏大风。","爲人祈福处，台樹與天通。"]', '诗', 'shi', '', NULL, '德宗皇帝挽歌詞三首 一 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dec50ec6-d485-4b06-87e2-bbdeece9bab7', '德宗皇帝挽歌詞三首 二', '德宗皇帝挽歌词三首 二', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["聖曆囗勤政，瑤圖慶運長。","壽宮開此地，仙駕緲何鄉。","風斷清笳調，雲愁綠斾揚。","上升知不恨，弘濟任城王。"]', '["聖曆囗勤政，瑤圖慶運长。","壽宮开此地，仙駕緲何乡。","风斷清笳調，云愁綠斾揚。","上升知不恨，弘濟任城王。"]', '诗', 'shi', '', NULL, '德宗皇帝挽歌詞三首 二 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f3ef68d-e13f-441e-8c9c-0ad85fb66181', '德宗皇帝挽歌詞三首 三', '德宗皇帝挽歌词三首 三', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["嘗聞閶闔前，星拱北辰籙。","今來大明祖，輦駕橋山曲。","松柏韻幽音，魚龍焰寒燭。","歲歲秋風辭，兆人歌不足。"]', '["嘗闻閶闔前，星拱北辰籙。","今来大明祖，輦駕橋山曲。","松柏韻幽音，鱼龙焰寒燭。","歲歲秋风辞，兆人歌不足。"]', '诗', 'shi', '', NULL, '德宗皇帝挽歌詞三首 三 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce49e8c5-8745-4999-b5ab-7cc04b8cd424', '順宗至德大聖皇帝挽歌詞三首 一', '順宗至德大聖皇帝挽歌词三首 一', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["橋山同軌會，軒后葬衣冠。","東海風波變，西陵松柏攢。","鼎湖仙已去，金掌露寧乾。","萬木泉扃月，空憐鳧雁寒。"]', '["橋山同軌會，軒后葬衣冠。","东海风波变，西陵松柏攢。","鼎湖仙已去，金掌露寧乾。","万木泉扃月，空怜鳧雁寒。"]', '诗', 'shi', '', NULL, '順宗至德大聖皇帝挽歌詞三首 一 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2958c332-2b46-42d8-83c2-088c78ae1e49', '順宗至德大聖皇帝挽歌詞三首 二', '順宗至德大聖皇帝挽歌词三首 二', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["容衛曉徘徊，嚴城閶闔開。","烏號龍馭遠，遏密鳳聲哀。","崑浪黃河注，崦嵫白日頹。","恭聞天子孝，不忍望銅臺。"]', '["容衛晓徘徊，嚴城閶闔开。","烏號龙馭远，遏密鳳声哀。","崑浪黄河注，崦嵫白日頹。","恭闻天子孝，不忍望銅台。"]', '诗', 'shi', '', NULL, '順宗至德大聖皇帝挽歌詞三首 二 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cded4d5-abd7-43ce-926b-7f6a4e94d2c2', '順宗至德大聖皇帝挽歌詞三首 三', '順宗至德大聖皇帝挽歌词三首 三', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["哀挽渭川曲，空歌汾水陽。","夜泉愁更咽，秋日慘無光。","纘夏功傳啓，興周業繼昌。","回瞻五陵上，煙雨爲蒼蒼。"]', '["哀挽渭川曲，空歌汾水陽。","夜泉愁更咽，秋日慘無光。","纘夏功傳啓，兴周業繼昌。","回瞻五陵上，煙雨爲蒼蒼。"]', '诗', 'shi', '', NULL, '順宗至德大聖皇帝挽歌詞三首 三 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3419bfd-ba8d-4451-b2f8-3891803eff63', '昭德皇后挽歌詞', '昭德皇后挽歌词', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["玉扆將遷坐，金雞忽報晨。","珮環僊馭遠，星月夜臺新。","劍沒川空冷，菱寒鏡不春。","國門車馬會，多是濯龍親。"]', '["玉扆將遷坐，金雞忽報晨。","珮环僊馭远，星月夜台新。","劍沒川空冷，菱寒镜不春。","国门车马會，多是濯龙親。"]', '诗', 'shi', '', NULL, '昭德皇后挽歌詞 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c5d45b6-fb33-4fc8-91d0-2f7a8377ca98', '春晚奉陪相公西亭宴集', '春晚奉陪相公西亭宴集', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["林花春向闌，高會重邀歡。","感物惜芳景，放懷因綵翰。","玉顏穠處並，銀燭焰中看。","若折持相贈，風光益別難。"]', '["林花春向闌，高會重邀歡。","感物惜芳景，放懷因綵翰。","玉顏穠处並，銀燭焰中看。","若折持相贈，风光益別难。"]', '诗', 'shi', '', NULL, '春晚奉陪相公西亭宴集 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04bcd6fd-df30-47c1-b489-e32f35dc1140', '送崔判官使太原', '送崔判官使太原', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["勞君車馬此逡巡，我與劉君本世親。","兩地山河分節制，十年京洛共風塵。","笙歌幾處胡天月，羅綺長留蜀國春。","報主由來須盡敵，相期萬里寶刀新。"]', '["勞君车马此逡巡，我與劉君本世親。","兩地山河分節制，十年京洛共风塵。","笙歌幾处胡天月，羅綺长留蜀国春。","報主由来須尽敵，相期万里寶刀新。"]', '诗', 'shi', '', NULL, '送崔判官使太原 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc387d29-7565-4b01-9156-47070e954306', '幕中諸公有觀獵之作因繼之', '幕中諸公有观獵之作因繼之', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["刀州城北劒山東，甲士屯雲騎散風。","旌斾遍張林嶺動，豺狼驅盡塞垣空。","銜蘆遠雁愁縈繳，繞樹啼猨怯避弓。","爲報府中諸從事，燕然未勒莫論功。"]', '["刀州城北劒山东，甲士屯云騎散风。","旌斾遍張林嶺动，豺狼驱尽塞垣空。","銜蘆远雁愁縈繳，繞樹啼猨怯避弓。","爲報府中諸從事，燕然未勒莫論功。"]', '诗', 'shi', '', NULL, '幕中諸公有觀獵之作因繼之 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d953b4b3-ab99-402a-aa87-3c342403c268', '同幕中諸公送李侍御歸朝', '同幕中諸公送李侍御归朝', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["昔年專席奉清朝，今日持書即舊僚。","珠履會中簫管思，白雲歸處帝鄉遙。","巴江暮雨連三峽，劍壁危梁上九霄。","歲月不堪相送盡，頹顏更被別離凋。"]', '["昔年專席奉清朝，今日持书即旧僚。","珠履會中簫管思，白云归处帝乡遙。","巴江暮雨連三峽，劍壁危梁上九霄。","歲月不堪相送尽，頹顏更被別離凋。"]', '诗', 'shi', '', NULL, '同幕中諸公送李侍御歸朝 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76a21f2c-6033-4e0e-8d3e-dfbe798bd745', '送張六諫議歸朝', '送張六諫議归朝', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["詔書前日下丹霄，頭戴儒冠脫皂貂。","笛怨柳營煙漠漠，雲愁江館雨蕭蕭。","鴛鴻得路爭先翥，松柏凌寒獨後凋。","歸去朝端如有問，玉關門外老班超。"]', '["詔书前日下丹霄，头戴儒冠脫皂貂。","笛怨柳營煙漠漠，云愁江館雨蕭蕭。","鴛鴻得路爭先翥，松柏凌寒独後凋。","归去朝端如有问，玉关门外老班超。"]', '诗', 'shi', '', NULL, '送張六諫議歸朝 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ea9eba2-8921-40c2-8e52-a8ff4f2a881b', '酬嚴司空荆南見寄', '酬嚴司空荆南见寄', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["金貂再領三公府，玉帳連封萬戶侯。","簾捲青山巫峽曉，煙開碧樹渚宮秋。","劉琨坐嘯風清塞，謝朓題詩月滿樓。","白雪調高歌不得，美人南國翠蛾愁。"]', '["金貂再領三公府，玉帳連封万戶侯。","簾捲青山巫峽晓，煙开碧樹渚宮秋。","劉琨坐嘯风清塞，謝朓題诗月满楼。","白雪調高歌不得，美人南国翠蛾愁。"]', '诗', 'shi', '', NULL, '酬嚴司空荆南見寄 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57379322-b132-4c32-a039-d5300ecb42f6', '南徐別業早春有懷', '南徐別業早春有懷', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["生涯擾擾竟何成，自愛深居隱姓名。","遠雁臨空翻夕照，殘雲帶雨過春城。","花枝入戶猶含潤，泉水侵堦乍有聲。","虛度年華不相見，離腸懷土併關情。"]', '["生涯擾擾竟何成，自愛深居隐姓名。","远雁臨空翻夕照，殘云带雨過春城。","花枝入戶猶含潤，泉水侵堦乍有声。","虛度年华不相见，離腸懷土併关情。"]', '诗', 'shi', '', NULL, '南徐別業早春有懷 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('006a5958-9564-44f8-9192-f43eea6732a4', '摩訶池宴', '摩訶池宴', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["摩訶池上春光早，愛水看花日日來。","穠李雪開歌扇掩，綠楊風動舞腰回。","蕪臺事往空留恨，金谷時危悟惜才。","晝短欲將清夜繼，西園自有月裴回。"]', '["摩訶池上春光早，愛水看花日日来。","穠李雪开歌扇掩，綠楊风动舞腰回。","蕪台事往空留恨，金谷时危悟惜才。","晝短欲將清夜繼，西园自有月裴回。"]', '诗', 'shi', '', NULL, '摩訶池宴 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d8b4a47-338d-4496-aa9b-efaa652b04a0', '至櫟陽崇道寺聞嚴十少府趨侍', '至櫟陽崇道寺闻嚴十少府趨侍', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["雲連萬木夕沈沈，草色泉聲古院深。","聞說羊車趨盛府，何言瓊樹在東林。","松筠自古多年契，風月懷賢此夜心。","惆悵送君身未達，不堪搖落聽秋砧。"]', '["云連万木夕沈沈，草色泉声古院深。","闻说羊车趨盛府，何言瓊樹在东林。","松筠自古多年契，风月懷賢此夜心。","惆悵送君身未達，不堪搖落听秋砧。"]', '诗', 'shi', '', NULL, '至櫟陽崇道寺聞嚴十少府趨侍 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4cafa82-3850-44d1-8db1-65a0c983d8ee', '春暮郊居寄朱舍人', '春暮郊居寄朱舍人', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["幽深不讓子真居，度日閑眠世事疎。","春水滿池新雨霽，香風入戶落花餘。","目隨鴻雁窮蒼翠，心寄溪雲任卷舒。","回首知音青瑣闥，何時一爲薦相如。"]', '["幽深不讓子真居，度日闲眠世事疎。","春水满池新雨霽，香风入戶落花餘。","目隨鴻雁窮蒼翠，心寄溪云任卷舒。","回首知音青瑣闥，何时一爲薦相如。"]', '诗', 'shi', '', NULL, '春暮郊居寄朱舍人 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92786fed-bd1f-4b19-bbe1-145d5120f253', '送溫況遊蜀', '送溫況游蜀', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["遊人西去客三巴，身逐孤蓬不定家。","山近峨眉飛暮雨，江連濯錦起朝霞。","雲深九折刀州遠，路繞千巖劍閣斜。","應到嚴君開卦處，將余一爲問生涯。"]', '["游人西去客三巴，身逐孤蓬不定家。","山近峨眉飞暮雨，江連濯錦起朝霞。","云深九折刀州远，路繞千巖劍閣斜。","應到嚴君开卦处，將余一爲问生涯。"]', '诗', 'shi', '', NULL, '送溫況遊蜀 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2807db58-9cdd-448f-9381-d33a361a2a63', '崔敷歎春物將謝恨不同覽時余方爲事牽束及往尋不遇題之留贈', '崔敷歎春物將謝恨不同覽时余方爲事牽束及往尋不遇題之留贈', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["九陌遲遲麗景斜，禁街西訪隱淪賒。","門依高柳空飛絮，身逐閑雲不在家。","軒冕強來趨世路，琴尊空負賞年華。","殘陽寂寞東城去，惆悵春風落盡花。"]', '["九陌遲遲丽景斜，禁街西訪隐淪賒。","门依高柳空飞絮，身逐闲云不在家。","軒冕強来趨世路，琴尊空負賞年华。","殘陽寂寞东城去，惆悵春风落尽花。"]', '诗', 'shi', '', NULL, '崔敷歎春物將謝恨不同覽時余方爲事牽束及往尋不遇題之留贈 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f218bb2-5f46-423d-869b-fa166ac8ba49', '秋燈對雨寄史近崔積', '秋灯对雨寄史近崔積', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["坐聽宮城傳晚漏，起看衰葉下寒枝。","空庭綠草結離念，細雨黃花贈所思。","蟋蟀已驚良節度，茱萸偏憶故人期。","相逢莫厭尊前醉，春去秋來自不知。"]', '["坐听宮城傳晚漏，起看衰葉下寒枝。","空庭綠草結離念，細雨黄花贈所思。","蟋蟀已驚良節度，茱萸偏憶故人期。","相逢莫厭尊前醉，春去秋来自不知。"]', '诗', 'shi', '', NULL, '秋燈對雨寄史近崔積 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77ffead6-d168-4e78-9468-6677c93c6ac5', '春題龍門香山寺', '春題龙门香山寺', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["衆香天上梵仙宮，鐘磬寥寥半碧空。","清景乍開松嶺月，亂流長響石樓風。","山河杳映春雲外，城闕參差茂樹中。","欲盡出尋那可得，三千世界本無窮。"]', '["衆香天上梵仙宮，鐘磬寥寥半碧空。","清景乍开松嶺月，亂流长响石楼风。","山河杳映春云外，城闕參差茂樹中。","欲尽出尋那可得，三千世界本無窮。"]', '诗', 'shi', '', NULL, '春題龍門香山寺 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2ffb461-56cb-4e79-99b4-b2eed80d739c', '酬陸三與鄒十八侍御', '酬陸三與鄒十八侍御', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["城分流水郭連山，拂露開懷一解顏。","令尹關中仙史會，河陽縣裏玉人閑。","共憐秋隼驚飛至，久想雲鴻待侶還。","莫恨殷勤留此地，東崖桂樹昔同攀。"]', '["城分流水郭連山，拂露开懷一解顏。","令尹关中仙史會，河陽縣裏玉人闲。","共怜秋隼驚飞至，久想云鴻待侶還。","莫恨殷勤留此地，东崖桂樹昔同攀。"]', '诗', 'shi', '', NULL, '酬陸三與鄒十八侍御 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6686869d-f1aa-43f9-9159-7a55ba801eaf', '酬談校書長安秋夜對月寄諸故舊', '酬談校书长安秋夜对月寄諸故旧', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["故園千里渺遐情，黃葉蕭條白露生。","驚鵲遶枝風滿幌，寒鐘送曉月當楹。","蓬山高價傳新韻，槐市芳年挹盛名。","莫怪孔融悲歲序，五侯門館重婁卿。"]', '["故园千里渺遐情，黄葉蕭條白露生。","驚鵲遶枝风满幌，寒鐘送晓月當楹。","蓬山高價傳新韻，槐市芳年挹盛名。","莫怪孔融悲歲序，五侯门館重婁卿。"]', '诗', 'shi', '', NULL, '酬談校書長安秋夜對月寄諸故舊 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ef0bce0-bb24-434c-97ae-e58f3f64cb11', '送田三端公還鄂州', '送田三端公還鄂州', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["孤雲迢遰戀滄洲，勸酒梨花對白頭。","南陌送歸車騎合，東城怨別管弦愁。","青油幕裏人如玉，黃鶴樓中月並鉤。","君去庾公應借問，馳心千里大江流。"]', '["孤云迢遰戀滄洲，勸酒梨花对白头。","南陌送归车騎合，东城怨別管弦愁。","青油幕裏人如玉，黄鹤楼中月並鉤。","君去庾公應借问，驰心千里大江流。"]', '诗', 'shi', '', NULL, '送田三端公還鄂州 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25cbb64b-a015-4a1a-a76a-1cc554f0495d', '送李秀才赴滑州詣大夫舅', '送李秀才赴滑州詣大夫舅', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["陌頭車馬去翩翩，白面懷書美少年。","東武楊公姻婭重，西州謝傅舅甥賢。","長亭叫月新秋雁，官渡含風古樹蟬。","知己滿朝留不住，貴臣河上擁旌旃。"]', '["陌头车马去翩翩，白面懷书美少年。","东武楊公姻婭重，西州謝傅舅甥賢。","长亭叫月新秋雁，官渡含风古樹蟬。","知己满朝留不住，貴臣河上擁旌旃。"]', '诗', 'shi', '', NULL, '送李秀才赴滑州詣大夫舅 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d65129a-ea27-4ec6-b8ed-8c12ee3d0d0a', '秋日書懷', '秋日书懷', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["金貂玉鉉奉君恩，夜漏晨鐘老掖垣。","參決萬機空有媿，靜觀羣動亦無言。","杯中壯志紅顏歇，林下秋聲絳葉翻。","倦鳥不知歸去日，青蕪白露滿郊園。"]', '["金貂玉鉉奉君恩，夜漏晨鐘老掖垣。","參決万機空有媿，静观羣动亦無言。","杯中壯志紅顏歇，林下秋声絳葉翻。","倦鸟不知归去日，青蕪白露满郊园。"]', '诗', 'shi', '', NULL, '秋日書懷 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c9b4547-74bf-416f-9f05-8f0e73350cf7', '南昌灘', '南昌灘', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["渠江明淨峽逶迤，船到名灘拽𥮘遲。","櫓窡動搖妨作夢，巴童指點笑吟詩。","畬餘宿麥黃山腹，日背殘花白水湄。","物色可憐心莫限，此行都是獨行時。"]', '["渠江明淨峽逶迤，船到名灘拽𥮘遲。","櫓窡动搖妨作梦，巴童指点笑吟诗。","畬餘宿麦黄山腹，日背殘花白水湄。","物色可怜心莫限，此行都是独行时。"]', '诗', 'shi', '', NULL, '南昌灘 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0ec2762-0412-493a-8c83-ed182eb41db0', '奉和聖製豐年多慶九日示懷', '奉和聖製豐年多慶九日示懷', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["令節寰宇泰，神都佳氣濃。","賡歌禹功盛，擊壤堯年豐。","九奏碧霄裏，千官皇澤中。","南山澄凝黛，曲水清涵空。","金玉美王度，歡康謠國風。","睿文垂日月，永與天無窮。"]', '["令節寰宇泰，神都佳氣濃。","賡歌禹功盛，擊壤堯年豐。","九奏碧霄裏，千官皇澤中。","南山澄凝黛，曲水清涵空。","金玉美王度，歡康謠国风。","睿文垂日月，永與天無窮。"]', '诗', 'shi', '', NULL, '奉和聖製豐年多慶九日示懷 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efdc20e0-6f18-4acd-b3d4-a4d6ad7cdbb4', '夏日陪馮許二侍郎與嚴祕書遊昊天觀覽舊題寄同里楊華州中丞', '夏日陪馮許二侍郎與嚴祕书游昊天观覽旧題寄同里楊华州中丞', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["三伏草木變，九城車馬煩。","碧霄迴騎射，丹洞入桃源。","臺殿雲浮棟，緌纓鶴在軒。","莫將真破妄，聊用靜持喧。","石甃古苔冷，水筠涼簟翻。","黃公壚下歎，旌斾國東門。"]', '["三伏草木变，九城车马煩。","碧霄迴騎射，丹洞入桃源。","台殿云浮棟，緌纓鹤在軒。","莫將真破妄，聊用静持喧。","石甃古苔冷，水筠涼簟翻。","黄公壚下歎，旌斾国东门。"]', '诗', 'shi', '', NULL, '夏日陪馮許二侍郎與嚴祕書遊昊天觀覽舊題寄同里楊華州中丞 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16a990e0-e926-434c-9150-229f494df28c', '奉和聖製重陽日即事', '奉和聖製重陽日即事', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["玉燭降寒露，我皇歌古風。","重陽德澤展，萬國歡娛同。","綺陌擁行騎，香塵凝曉空。","神都自藹藹，佳氣助葱葱。","律呂陰陽暢，景光天地通。","徒然被鴻霈，無以報玄功。"]', '["玉燭降寒露，我皇歌古风。","重陽德澤展，万国歡娛同。","綺陌擁行騎，香塵凝晓空。","神都自藹藹，佳氣助葱葱。","律呂陰陽暢，景光天地通。","徒然被鴻霈，無以報玄功。"]', '诗', 'shi', '', NULL, '奉和聖製重陽日即事 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bdd44ad-6a7e-4c17-802a-c88127770ca2', '秋日臺中寄懷簡諸僚', '秋日台中寄懷簡諸僚', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["憲府日多事，秋光照碧林。","干雲巖翠合，布石地苔深。","憂悔耿遐抱，塵埃緇素襟。","物情牽跼促，友道曠招尋。","頹節風霜變，流年芳景侵。","池荷足幽氣，煙竹又繁陰。","簪組赤墀戀，池魚滄海心。","滌煩滯幽賞，永度瑤華音。"]', '["憲府日多事，秋光照碧林。","干云巖翠合，布石地苔深。","憂悔耿遐抱，塵埃緇素襟。","物情牽跼促，友道曠招尋。","頹節风霜变，流年芳景侵。","池荷足幽氣，煙竹又繁陰。","簪組赤墀戀，池鱼滄海心。","滌煩滯幽賞，永度瑤华音。"]', '诗', 'shi', '', NULL, '秋日臺中寄懷簡諸僚 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd5ea081-ba07-43c1-b11e-39afe809736a', '奉酬淮南中書相公見寄', '奉酬淮南中书相公见寄', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["揚州隋故都，竹使漢名儒。","翊聖恩華異，持衡節制殊。","朝廷連受脤，台座接訐謨。","金玉裁王度，丹書奉帝俞。","九重辭象魏，千[里]握兵符。","鐵馬秋臨塞，虹旌夜渡瀘。","江長梅笛怨，天遠桂輪孤。","浩歎煙霜曉，芳期蘭蕙蕪。","雅言書一札，賓海雁東隅。","歲月奔波盡，音徽霧雨濡。","蜀江分井絡，錦浪入淮湖。","獨抱相思恨，關山不可踰。"]', '["揚州隋故都，竹使漢名儒。","翊聖恩华異，持衡節制殊。","朝廷連受脤，台座接訐謨。","金玉裁王度，丹书奉帝俞。","九重辞象魏，千[里]握兵符。","鐵马秋臨塞，虹旌夜渡瀘。","江长梅笛怨，天远桂輪孤。","浩歎煙霜晓，芳期蘭蕙蕪。","雅言书一札，賓海雁东隅。","歲月奔波尽，音徽霧雨濡。","蜀江分井絡，錦浪入淮湖。","独抱相思恨，关山不可踰。"]', '诗', 'shi', '', NULL, '奉酬淮南中書相公見寄 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d91c1f1-898f-43ed-86f5-4442aa7b1332', '甫搆西亭偶題因呈監軍及幕中諸公', '甫搆西亭偶題因呈監軍及幕中諸公', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["瀛海無因泛，崑丘豈易尋。","數峰聊在目，一境暫清心。","悅彼松柏性，愛茲桃李陰。","列芳憑有土，叢幹聚成林。","信矣子牟戀，歸歟尼父吟。","暗香蘭露滴，空翠蕙樓深。","負鼎位嘗忝，荷戈年屢侵。","百城煩鞅掌，九仞喜嶇嶔。","巴漢泝沿楫，岷峨千萬岑。","恩偏不敢去，范蠡畏鎔金。"]', '["瀛海無因泛，崑丘豈易尋。","數峰聊在目，一境暫清心。","悅彼松柏性，愛茲桃李陰。","列芳憑有土，叢幹聚成林。","信矣子牟戀，归歟尼父吟。","暗香蘭露滴，空翠蕙楼深。","負鼎位嘗忝，荷戈年屢侵。","百城煩鞅掌，九仞喜嶇嶔。","巴漢泝沿楫，岷峨千万岑。","恩偏不敢去，范蠡畏鎔金。"]', '诗', 'shi', '', NULL, '甫搆西亭偶題因呈監軍及幕中諸公 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6bc760d-d420-42bb-981a-177263452906', '和楊弘微春日曲江南望', '和楊弘微春日曲江南望', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["遲景靄悠悠，傷春南陌頭。","暄風一澹蕩，遐思幾殷憂。","龍去空仙沼，鸞飛掩妓樓。","芳菲餘雨露，冠蓋舊公侯。","朱戟千門閉，黃鸝百囀愁。","煙濛宮樹晚，花咽石泉流。","寒谷律潛應，中林蘭自幽。","商山將避漢，晉室正藩周。","黍稷聞興歎，瓊瑤畏見投。","君心即吾事，微向在滄洲。"]', '["遲景靄悠悠，傷春南陌头。","暄风一澹蕩，遐思幾殷憂。","龙去空仙沼，鸾飞掩妓楼。","芳菲餘雨露，冠蓋旧公侯。","朱戟千门閉，黄鸝百囀愁。","煙濛宮樹晚，花咽石泉流。","寒谷律潛應，中林蘭自幽。","商山將避漢，晉室正藩周。","黍稷闻兴歎，瓊瑤畏见投。","君心即吾事，微向在滄洲。"]', '诗', 'shi', '', NULL, '和楊弘微春日曲江南望 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('679f0501-efc8-480c-ae38-3c95b10b9c70', '長安秋夜懷陳京昆季', '长安秋夜懷陳京昆季', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["鐘鼓九衢絕，出門千里同。","遠情高枕夜，秋思北窗空。","靜見煙凝燭，閑聽葉墜桐。","玉壺思洞徹，瓊樹憶葱籠。","螢影疎簾外，鴻聲暗雨中。","羇愁難會面，嬾慢責微躬。","甲乙科攀桂，圖書閣踐蓬。","一瓢非可樂，六翮未因風。","寥落悲秋盡，蹉跎惜歲窮。","明朝不相見，流淚菊花叢。"]', '["鐘鼓九衢絕，出门千里同。","远情高枕夜，秋思北窗空。","静见煙凝燭，闲听葉墜桐。","玉壺思洞徹，瓊樹憶葱籠。","螢影疎簾外，鴻声暗雨中。","羇愁难會面，嬾慢責微躬。","甲乙科攀桂，圖书閣踐蓬。","一瓢非可乐，六翮未因风。","寥落悲秋尽，蹉跎惜歲窮。","明朝不相见，流泪菊花叢。"]', '诗', 'shi', '', NULL, '長安秋夜懷陳京昆季 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8674fa82-1c80-400d-b329-2c6ef1c5fee2', '冬日漢江南行將赴夏口途次江陵界寄裴尚書', '冬日漢江南行將赴夏口途次江陵界寄裴尚书', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["五部擁雙旌，南依墨客卿。","關山迥梁甸，波浪接湓城。","煙景迷時候，雲帆渺去程。","蛤珠馮月吐，蘆雁觸羅驚。","浦樹凝寒晦，江天湛鏡清。","賞心隨處愜，壯志逐年輕。","舟檝不可駐，提封如任情。","向方曾指路，射策許言兵。","蘭渚歇芳意，菱歌非應聲。","元戎武昌守，羊祜幸連營。"]', '["五部擁雙旌，南依墨客卿。","关山迥梁甸，波浪接湓城。","煙景迷时候，云帆渺去程。","蛤珠馮月吐，蘆雁觸羅驚。","浦樹凝寒晦，江天湛镜清。","賞心隨处愜，壯志逐年轻。","舟檝不可駐，提封如任情。","向方曾指路，射策許言兵。","蘭渚歇芳意，菱歌非應声。","元戎武昌守，羊祜幸連營。"]', '诗', 'shi', '', NULL, '冬日漢江南行將赴夏口途次江陵界寄裴尚書 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e9ade9a-2235-4368-9bc2-c8435380a20e', '奉酬中書李相公早朝於中書候傳點偶書所懷', '奉酬中书李相公早朝於中书候傳点偶书所懷', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["寥落曙鍾斷，微明煙月沈。","翠霞仙仗合，清漏掖垣深。","北極星遙拱，南山闕迥臨。","蘭釭竟曉燄，琪樹欲秋陰。","霄漢慙聯步，貂蟬媿並簪。","德容溫比玉，王度式如金。","魚水千里運，簫韶九奏音。","代天驚度日，擲地喜開襟。","文武時方泰，唐虞道可尋。","忝陪申及甫，清淨奉堯心。"]', '["寥落曙鍾斷，微明煙月沈。","翠霞仙仗合，清漏掖垣深。","北極星遙拱，南山闕迥臨。","蘭釭竟晓燄，琪樹欲秋陰。","霄漢慙聯步，貂蟬媿並簪。","德容溫比玉，王度式如金。","鱼水千里運，簫韶九奏音。","代天驚度日，擲地喜开襟。","文武时方泰，唐虞道可尋。","忝陪申及甫，清淨奉堯心。"]', '诗', 'shi', '', NULL, '奉酬中書李相公早朝於中書候傳點偶書所懷 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bf75e10-ba3d-40d6-935c-890040648101', '甲午歲相國李公有北園寄贈之作吟翫歷時屢促酬答機務不暇未及報章今古遽分電波增感留墓劒而心許感鄰笛而意傷寓哀冥寞以廣遺韻云', '甲午歲相国李公有北园寄贈之作吟翫歷时屢促酬答機務不暇未及報章今古遽分電波增感留墓劒而心許感鄰笛而意傷寓哀冥寞以廣遺韻云', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["機事勞西掖，幽懷寄北園。","鶴巢深更靜，蟬噪斷猶喧。","仙醞百花馥，豔歌雙袖翻。","碧雲詩變雅，皇澤葉流根。","未報雕龍贈，俄傷淚劒痕。","佳城關白日，哀挽向青門。","禮命公台重，煙霜隴樹繁。","天高不可問，空使輔星昏。"]', '["機事勞西掖，幽懷寄北园。","鹤巢深更静，蟬噪斷猶喧。","仙醞百花馥，豔歌雙袖翻。","碧云诗变雅，皇澤葉流根。","未報雕龙贈，俄傷泪劒痕。","佳城关白日，哀挽向青门。","禮命公台重，煙霜隴樹繁。","天高不可问，空使輔星昏。"]', '诗', 'shi', '', NULL, '甲午歲相國李公有北園寄贈之作吟翫歷時屢促酬答機務不暇未及報章今古遽分電波增感留墓劒而心許感鄰笛而意傷寓哀冥寞以廣遺韻云 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe65064b-17cb-4690-b640-903a94145fa9', '和楊三舍人晚秋與崔二舍人張祕監苗考功同遊昊天觀時中書寓直不得陪隨因追往年曾與舊僚聯遊此觀紀題在壁已有淪亡書事感懷輙以呈寄兼呈東省三給事之作楊君見徴鄙詞因以繼和', '和楊三舍人晚秋與崔二舍人張祕監苗考功同游昊天观时中书寓直不得陪隨因追往年曾與旧僚聯游此观紀題在壁已有淪亡书事感懷輙以呈寄兼呈东省三給事之作楊君见徴鄙词因以繼和', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["瑤圃高秋會，金閨奉詔辰。","朱輪天上客，白石洞中人。","珮響泉聲雜，朝衣羽服親。","九重青瑣閉，三秀紫芝新。","化藥秦方士，偷桃漢侍臣。","玉笙王子駕，遼鶴令威身。","歎逝頹波速，緘詞麗曲春。","重將悽恨意，苔壁問遺塵。"]', '["瑤圃高秋會，金閨奉詔辰。","朱輪天上客，白石洞中人。","珮响泉声杂，朝衣羽服親。","九重青瑣閉，三秀紫芝新。","化藥秦方士，偷桃漢侍臣。","玉笙王子駕，遼鹤令威身。","歎逝頹波速，緘词丽曲春。","重將悽恨意，苔壁问遺塵。"]', '诗', 'shi', '', NULL, '和楊三舍人晚秋與崔二舍人張祕監苗考功同遊昊天觀時中書寓直不得陪隨因追往年曾與舊僚聯遊此觀紀題在壁已有淪亡書事感懷輙以呈寄兼呈東省三給事之作楊君見徴鄙詞因以繼和 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8be65627-6edb-4233-8cc5-cc61311253aa', '酬李十一尚書西亭暇日書懷見寄十二韻之作', '酬李十一尚书西亭暇日书懷见寄十二韻之作', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["鼎鉉昔云忝，西南分主憂。","煙塵開僰道，旌節護蠻陬。","任重功無立，力微恩未酬。","據鞍慙齒髮，責帥懼春秋。","高德聞鄭履，儉居稱晏裘。","三刀君入夢，九折我回輈。","時景屢遷易，茲言期退休。","方追故山事，豈謂台堦留。","遐抱清淨理，眷言蘭杜幽。","一緘瓊玖贈，萬里別離愁。","巴嶺雲外沒，蜀江天際流。","懷賢耿遙思，相望鳳池頭。"]', '["鼎鉉昔云忝，西南分主憂。","煙塵开僰道，旌節護蠻陬。","任重功無立，力微恩未酬。","據鞍慙齒髮，責帥懼春秋。","高德闻鄭履，儉居稱晏裘。","三刀君入梦，九折我回輈。","时景屢遷易，茲言期退休。","方追故山事，豈謂台堦留。","遐抱清淨理，眷言蘭杜幽。","一緘瓊玖贈，万里別離愁。","巴嶺云外沒，蜀江天際流。","懷賢耿遙思，相望鳳池头。"]', '诗', 'shi', '', NULL, '酬李十一尚書西亭暇日書懷見寄十二韻之作 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7e92d31-202f-4ab2-9cf3-fdfc4176541b', '秋懷奉寄朱補闕', '秋懷奉寄朱補闕', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["上苑繁霜降，騷人起恨初。","白雲深陋巷，衰草遍閑居。","暮色秋煙重，寒聲牖葉虛。","潘生秋思苦，陶令世情疎。","已製歸田賦，猶陳諫獵書。","不知青瑣客，投分竟何如。"]', '["上苑繁霜降，騷人起恨初。","白云深陋巷，衰草遍闲居。","暮色秋煙重，寒声牖葉虛。","潘生秋思苦，陶令世情疎。","已製归田賦，猶陳諫獵书。","不知青瑣客，投分竟何如。"]', '诗', 'shi', '', NULL, '秋懷奉寄朱補闕 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a77fedb-d9b8-417a-9d70-26c41f0adc68', '奉酬中書相公至日圜丘行事合於中書宿齋移止於集賢院敘情見寄之什', '奉酬中书相公至日圜丘行事合於中书宿斋移止於集賢院敘情见寄之什', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["郊廟祗嚴祀，齋莊覿上玄。","別開金虎觀，不離紫微天。","樹古長楊接，池清太液連。","仲山方補衮，文舉自傷年。","風溢銅壺漏，香凝綺閣煙。","仍聞白雪唱，流詠滿鵾弦。"]', '["郊廟祗嚴祀，斋莊覿上玄。","別开金虎观，不離紫微天。","樹古长楊接，池清太液連。","仲山方補衮，文舉自傷年。","风溢銅壺漏，香凝綺閣煙。","仍闻白雪唱，流詠满鵾弦。"]', '诗', 'shi', '', NULL, '奉酬中書相公至日圜丘行事合於中書宿齋移止於集賢院敘情見寄之什 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b6164d7-7d64-4f68-9f6b-138d67ebb18f', '途次', '途次', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["去國策羸馬，勞歌行路難。","地崇秦制險，人樂漢恩寬。","御沼澄泉碧，宮梨拂露丹。","鼎成仙馭遠，龍化宿雲殘。","不問三苗寵，誰陪萬國歡。","至今松桂色，長助玉樓寒。"]', '["去国策羸马，勞歌行路难。","地崇秦制險，人乐漢恩寬。","御沼澄泉碧，宮梨拂露丹。","鼎成仙馭远，龙化宿云殘。","不问三苗寵，誰陪万国歡。","至今松桂色，长助玉楼寒。"]', '诗', 'shi', '', NULL, '途次 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a768c8d-8fc9-4267-8893-7a6973f092e1', '題故蔡國公主九華觀上池院', '題故蔡国公主九华观上池院', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["朱門臨九衢，雲木藹仙居。","曲沼天波接，層臺鳳舞餘。","曙煙深碧篠，香露濕紅蕖。","瑤瑟含風韻，紗窗積翠虛。","秦樓今寂寞，真界竟何如。","不與蓬瀛異，迢迢遠玉除。"]', '["朱门臨九衢，云木藹仙居。","曲沼天波接，層台鳳舞餘。","曙煙深碧篠，香露濕紅蕖。","瑤瑟含风韻，紗窗積翠虛。","秦楼今寂寞，真界竟何如。","不與蓬瀛異，迢迢远玉除。"]', '诗', 'shi', '', NULL, '題故蔡國公主九華觀上池院 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('362a7588-6f4e-41f5-bf4e-787b98cb0f18', '酬嚴維秋夜見寄', '酬嚴維秋夜见寄', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["遙夜思悠悠，聞鐘遠夢休。","亂林螢燭暗，零露竹風秋。","啓戶雲歸棟，褰簾月上鉤。","昭明逢聖代，羈旅別滄洲。","騎省潘郎思，衡闈宋玉愁。","神仙慙李郭，詞賦謝曹劉。","松柏應無變，瓊瑤不可酬。","誰堪此時景，寂寞下高樓。"]', '["遙夜思悠悠，闻鐘远梦休。","亂林螢燭暗，零露竹风秋。","啓戶云归棟，褰簾月上鉤。","昭明逢聖代，羈旅別滄洲。","騎省潘郎思，衡闈宋玉愁。","神仙慙李郭，词賦謝曹劉。","松柏應無变，瓊瑤不可酬。","誰堪此时景，寂寞下高楼。"]', '诗', 'shi', '', NULL, '酬嚴維秋夜見寄 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('685aaf3f-2a67-44f6-b2c7-278457aa960d', '途次近蜀驛蒙恩賜寶刀及飛龍廏馬使還奉寄中書李鄭二公', '途次近蜀驛蒙恩賜寶刀及飞龙廏马使還奉寄中书李鄭二公', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["草草事行役，遲遲違故關。","碧幃遙隱霧，紅斾漸依山。","感激酬恩淚，星霜去國顏。","捧刀金錫字，歸馬玉連環。","威鳳翔雙闕，征夫縱百蠻。","應憐宣室召，溫樹不同攀。"]', '["草草事行役，遲遲違故关。","碧幃遙隐霧，紅斾漸依山。","感激酬恩泪，星霜去国顏。","捧刀金錫字，归马玉連环。","威鳳翔雙闕，征夫縱百蠻。","應怜宣室召，溫樹不同攀。"]', '诗', 'shi', '', NULL, '途次近蜀驛蒙恩賜寶刀及飛龍廏馬使還奉寄中書李鄭二公 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f1175f4-16cc-4a34-acda-983fcb2021d9', '歸燕', '归燕', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["春色遍芳菲，閑簷雙燕歸。","還同舊侶至，來遶故巢飛。","敢望煙霄達，多慙羽翮微。","銜泥傍金砌，拾蘂到荆扉。","雲海經時別，雕梁長日依。","主人能一顧，轉盻自光輝。"]', '["春色遍芳菲，闲簷雙燕归。","還同旧侶至，来遶故巢飞。","敢望煙霄達，多慙羽翮微。","銜泥傍金砌，拾蘂到荆扉。","云海經时別，雕梁长日依。","主人能一顧，轉盻自光輝。"]', '诗', 'shi', '', NULL, '歸燕 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5aeeb83-14fb-4498-b270-42593d2ae1ca', '送許著作分司東都', '送許著作分司东都', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["瑤瑟激悽響，征鴻翻夕陽。","署分刊竹簡，書蠹護芸香。","馬色關城曉，蟬聲驛路長。","石渠榮正禮，蘭室重元方。","不作經年別，離魂亦暫傷。"]', '["瑤瑟激悽响，征鴻翻夕陽。","署分刊竹簡，书蠹護芸香。","马色关城晓，蟬声驛路长。","石渠榮正禮，蘭室重元方。","不作經年別，離魂亦暫傷。"]', '诗', 'shi', '', NULL, '送許著作分司東都 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81dd66ce-a15f-47fb-83bd-dde434d551db', '聞相公三兄小園置宴以元衡寓直因寄上兼呈中書三兄', '闻相公三兄小园置宴以元衡寓直因寄上兼呈中书三兄', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["休沐限中禁，家山傳勝遊。","露寒潘省夜，木落庾園秋。","蘭菊迴幽步，壺觴洽舊儔。","位高天祿閣，詞異畔牢愁。","孤思琴先覺，馳暉水競流。","明朝不相見，清祀在圜丘。"]', '["休沐限中禁，家山傳勝游。","露寒潘省夜，木落庾园秋。","蘭菊迴幽步，壺觴洽旧儔。","位高天祿閣，词異畔牢愁。","孤思琴先覺，驰暉水競流。","明朝不相见，清祀在圜丘。"]', '诗', 'shi', '', NULL, '聞相公三兄小園置宴以元衡寓直因寄上兼呈中書三兄 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ff2ebbc-b1c0-4661-89c6-b022af75a633', '酬陸員外歙州許員外郢州二使君', '酬陸員外歙州許員外郢州二使君', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["吳洲雲海接，楚驛夢林長。","符節分憂重，鵷鴻去路翔。","豔歌愁翠黛，寶瑟韻清商。","洲草遙池合，春風曉斾張。","晉臣多樂廣，漢主識馮唐。","不作經年別，離魂亦未傷。"]', '["吳洲云海接，楚驛梦林长。","符節分憂重，鵷鴻去路翔。","豔歌愁翠黛，寶瑟韻清商。","洲草遙池合，春风晓斾張。","晉臣多乐廣，漢主識馮唐。","不作經年別，離魂亦未傷。"]', '诗', 'shi', '', NULL, '酬陸員外歙州許員外郢州二使君 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26f3e892-a633-4286-a597-0eb6707607c8', '漸至涪州先寄王使君', '漸至涪州先寄王使君', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["治敎通夷俗，均輸問大田。","江分巴字水，樹入夜郎煙。","毒霧含秋氣，陰巖蔽曙天。","路難空計日，身老不由年。","將命寧知遠，歸心詎可傳。","星郎復何事，出守五溪邊。"]', '["治敎通夷俗，均輸问大田。","江分巴字水，樹入夜郎煙。","毒霧含秋氣，陰巖蔽曙天。","路难空計日，身老不由年。","將命寧知远，归心詎可傳。","星郎复何事，出守五溪邊。"]', '诗', 'shi', '', NULL, '漸至涪州先寄王使君 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b323c71f-ed8e-49cd-8baf-42089fa17706', '石州城', '石州城', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["丈夫心愛橫行，報國知嫌命輕。","樓蘭徑百戰，更道戍龍城。","錦字竇車騎，胡笳李少卿。","生離兩不見，萬古難爲情。"]', '["丈夫心愛橫行，報国知嫌命轻。","楼蘭徑百戰，更道戍龙城。","錦字竇车騎，胡笳李少卿。","生離兩不见，万古难爲情。"]', '诗', 'shi', '', NULL, '石州城 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8ddf0f5-ccbc-4e18-ab1e-fa3f78b70b52', '寒食下第', '寒食下第', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["柳挂九衢絲，花飄萬家雪。","如何憔悴人，對此芳菲節。"]', '["柳挂九衢絲，花飄万家雪。","如何憔悴人，对此芳菲節。"]', '诗', 'shi', '', NULL, '寒食下第 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f502cd6-45ad-40ad-be9e-008ecaf3b5ee', '途中即事', '途中即事', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["南征復北還，擾擾百年間。","自笑紅塵裏，生涯不暫閑。"]', '["南征复北還，擾擾百年间。","自笑紅塵裏，生涯不暫闲。"]', '诗', 'shi', '', NULL, '途中即事 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfec44d3-f3cc-448c-ac00-14a74136052a', '春日偶作', '春日偶作', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["縱橫桃李枝，淡蕩春風吹。","美人歌白苧，萬恨在蛾眉。"]', '["縱橫桃李枝，淡蕩春风吹。","美人歌白苧，万恨在蛾眉。"]', '诗', 'shi', '', NULL, '春日偶作 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adbb2adc-c1a8-46e8-bae3-8e1560d723d6', '夏夜作', '夏夜作', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["夜久喧暫息，池臺惟月明。","無因駐清景，日出事還生。"]', '["夜久喧暫息，池台惟月明。","無因駐清景，日出事還生。"]', '诗', 'shi', '', NULL, '夏夜作 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27b07714-e121-47ce-8c42-5517591d40fc', '左掖梨花', '左掖梨花', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["巧笑解迎人，晴雪香堪惜。","隨風蝶影翻，誤點朝衣赤。"]', '["巧笑解迎人，晴雪香堪惜。","隨风蝶影翻，誤点朝衣赤。"]', '诗', 'shi', '', NULL, '左掖梨花 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d70d3707-c751-4237-9b57-6f0e897d6c4d', '同陳六侍御寒食遊禪定藏山上人院', '同陳六侍御寒食游禪定藏山上人院', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["年少輕行樂，東城南陌頭。","與君寂寞意，共作草堂遊。"]', '["年少轻行乐，东城南陌头。","與君寂寞意，共作草堂游。"]', '诗', 'shi', '', NULL, '同陳六侍御寒食遊禪定藏山上人院 武元衡 shi');
